function poolSlug(v){
  return String(v||"").trim().toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,42);
}
function normalizePoolCode(v){
  return poolSlug(v);
}
function displayPoolCode(v){
  return String(v||currentPoolId||"").trim().toLowerCase();
}
function removeCredentialSpaces(v){
  return String(v||"").replace(/\s+/g,"");
}
function poolPasscode(v){
  return removeCredentialSpaces(v).slice(0,80);
}
function invalidPoolPasscode(v){
  var s=poolPasscode(v);
  return /[\/\\]/.test(s)||s==="."||s==="..";
}
function weakPoolPasscodeReason(v){
  var s=poolPasscode(v);
  if(s.length<6)return "Join passcode needs at least 6 characters.";
  if(invalidPoolPasscode(s))return "Join passcode cannot use / or \\.";
  return "";
}
function validAccountPasswordReason(v){
  if(/\s/.test(String(v||"")))return "Password cannot use spaces.";
  if(removeCredentialSpaces(v).length<8)return "Password needs at least 8 characters.";
  return "";
}
function invalidJoinCodeMessage(){
  return "Code invalid: create a pool or join a pool with a real password.";
}
function reservedPoolCodePoolId(v){
  var aliases=Array.isArray(v)?v:[v];
  for(var i=0;i<aliases.length;i++){
    var code=normalizePoolCode(aliases[i]);
    if(code==="freedom250"||code==="freedom-250"||code==="freedom250-pool"||code==="freedom-250-pool")return FREEDOM250_PRIMARY_COMMUNITY_POOL_ID;
  }
  return "";
}
function isReservedPoolCodeAlias(v){
  return !!reservedPoolCodePoolId(v);
}
function isFreedom250CommunityPool(poolId){
  var id=String(poolId||currentPoolId||"").trim().toLowerCase();
  return FREEDOM250_COMMUNITY_POOL_IDS.indexOf(id)>-1;
}
