async function resolvePoolCode(code,passcode){
  if(localDemoMode)return "";
  var typed=String(code||"").trim();
  var raw=normalizePoolCode(typed);
  var slug=poolSlug(typed);
  var candidates=[raw,slug].filter(Boolean).filter(function(v,i,a){return a.indexOf(v)===i;});
  if(!candidates.length)return "";
  var reservedPoolId=reservedPoolCodePoolId(candidates);
  if(reservedPoolId&&(passcode===undefined||poolPasscode(passcode).toLowerCase()==="freedom250"))return await resolveFreedom250CommunityPoolId();
  try{
    for(var i=0;i<candidates.length;i++){
      code=candidates[i];
      var codeSnap=await getDoc(doc(db,"poolCodes",code));
      var poolId=codeSnap.exists()&&codeSnap.data().poolId?poolSlug(codeSnap.data().poolId):poolSlug(code);
      if(poolId){
        var poolSnap=await getDoc(doc(db,"pools",poolId));
        if(poolSnap.exists()){
          if(passcode===undefined)return poolId;
          var poolData=poolSnap.data()||{};
          if(poolPasscode(poolData.joinCode)===poolPasscode(passcode))return poolId;
        }
      }
    }
  }catch(e){console.warn("Could not resolve pool code",e);}
  return "";
}
async function communityPoolAvailable(poolId){
  poolId=poolSlug(poolId);
  if(!poolId)return false;
  try{
    var deleted=await getDoc(doc(db,"deletedPools",poolId));
    if(deleted.exists())return false;
  }catch(e){console.warn("Could not check community deleted marker",e);}
  try{
    var snap=await getDoc(doc(db,"pools",poolId));
    return snap.exists();
  }catch(e){
    console.warn("Could not check community pool",e);
    return false;
  }
}
async function resolveFreedom250CommunityPoolId(){
  for(var i=0;i<FREEDOM250_COMMUNITY_POOL_IDS.length;i++){
    var id=FREEDOM250_COMMUNITY_POOL_IDS[i];
    if(await communityPoolAvailable(id))return id;
  }
  return FREEDOM250_PRIMARY_COMMUNITY_POOL_ID;
}
