window.confirmTransferPoolAdmin=async function(){
  var msg=document.getElementById("transferAdminMsg");
  var select=document.getElementById("transferAdminSelect");
  var confirmBox=document.getElementById("transferAdminConfirm");
  if(msg){msg.classList.remove("good");msg.textContent="";}
  if(!isPoolAdmin()){if(msg)msg.textContent="Only the current pool admin can transfer admin access.";return;}
  var uid=select&&select.value;
  if(!uid){if(msg)msg.textContent="Choose someone in this pool first.";return;}
  var target=adminTransferCandidates().find(function(c){return c.uid===uid;});
  if(!target){if(msg)msg.textContent="That member could not be found in this pool.";return;}
  if(msg)msg.textContent="Transferring admin access...";
  try{
    await transferAdminToMember(currentPoolId,target,msg);
    if(confirmBox)confirmBox.style.display="none";
    if(msg){msg.classList.add("good");msg.textContent="Admin access transferred successfully.";}
    showTab("profile",document.querySelector(".tabs button[onclick*=profile]"));
    var profileMsg=document.getElementById("profileActionMsg");
    if(profileMsg){profileMsg.classList.add("good");profileMsg.innerHTML='Admin access was transferred to '+safeHtml(target.name)+'. You can stay in this pool as a regular member or choose Leave This Pool below.';}
  }catch(e){
    console.error(e);
    if(msg)msg.textContent="Could not transfer admin access. Please try again.";
  }
};
