window.stripCredentialSpaces=function(input){
  if(!input)return "";
  var cleaned=removeCredentialSpaces(input.value);
  if(input.value!==cleaned){
    var start=input.selectionStart, removedBefore=String(input.value).slice(0,start==null?0:start).length-removeCredentialSpaces(String(input.value).slice(0,start==null?0:start)).length;
    input.value=cleaned;
    if(start!=null&&input.setSelectionRange){
      var next=Math.max(0,start-removedBefore);
      try{input.setSelectionRange(next,next);}catch(e){}
    }
  }
  return cleaned;
};
window.stripUsernameSpaces=function(input){
  if(!input)return "";
  var original=String(input.value||"");
  var cleaned=cleanUsernameHandle(original);
  if(original!==cleaned){
    var start=input.selectionStart;
    var before=original.slice(0,start==null?0:start);
    var cleanedBefore=cleanUsernameHandle(before);
    input.value=cleaned;
    if(start!=null&&input.setSelectionRange){
      try{input.setSelectionRange(cleanedBefore.length,cleanedBefore.length);}catch(e){}
    }
  }
  return cleaned;
};
