function authFriendlyError(e){
  var code=e&&e.code?e.code:"";
  if(code==="auth/configuration-not-found"){
    return "Firebase is not wired to this project yet. Copy the web app config from your ufc328pool Firebase project into this site.";
  }
  if(code==="auth/api-key-not-valid"){
    return "Firebase rejected this API key. Re-copy the web app config from Project settings and make sure every character matches.";
  }
  if(code==="auth/unauthorized-domain"){
    return "This address is not authorized in Firebase. Add localhost, 127.0.0.1, and your live domain under Authentication settings.";
  }
  if(code==="auth/invalid-email")return "That email does not look valid. Check it and try again.";
  if(code==="auth/weak-password")return "Password needs at least 8 characters.";
  if(code==="auth/wrong-password"||code==="auth/invalid-credential"||code==="auth/user-not-found")return "We could not sign in with that email and password. Check both, or create a new account first.";
  if(code==="auth/too-many-requests")return "Firebase blocked attempts for a bit. Wait a minute, then try again.";
  if(code==="auth/timeout")return (e&&e.message)||"Firebase did not answer. Check the internet connection, then try signing in again.";
  if(code==="auth/network-request-failed")return "Could not reach Firebase right now, so your profile was not created yet. Check the internet connection, then tap Create Account again.";
  return (e&&e.message)||"Firebase could not complete that account step.";
}
function firebaseTimeoutError(action){
  var err=new Error("Firebase is taking longer than expected while "+action+". Check the internet connection, then try again.");
  err.code="auth/timeout";
  return err;
}
function withFirebaseTimeout(promise,action,ms){
  var timer;
  var timeout=new Promise(function(_,reject){
    timer=setTimeout(function(){reject(firebaseTimeoutError(action));},ms||15000);
  });
  return Promise.race([promise,timeout]).finally(function(){clearTimeout(timer);});
}
function showFirebaseStillTrying(action,ms){
  return setTimeout(function(){
    var msg="Still connecting to Firebase while "+action+". Keep this tab open.";
    setSetupMessage(msg);
    setMemberMessage(msg);
  },ms||12000);
}
function profileSaveFriendlyError(e){
  var code=e&&e.code?e.code:"";
  if(code==="username-taken")return "Username taken.";
  if(code==="unavailable"||code==="deadline-exceeded"||code==="cancelled"||code==="auth/network-request-failed"){
    return "Could not reach Firebase right now, so your profile was not created yet. Check the internet connection, then tap Create Account again.";
  }
  if(code==="permission-denied"){
    return "Firebase would not save this profile yet. Check the database rules for this pool, then tap Create Account again.";
  }
  return "Your account was created, but your profile was not saved yet. Tap Create Account again so we can finish saving it.";
}
function isFirebaseReachabilityError(e){
  var code=e&&e.code?e.code:"";
  return code==="auth/network-request-failed"||code==="unavailable"||code==="deadline-exceeded"||code==="cancelled";
}
