window.validateAccountInputs=function(){
  var p=getProfileInputs();
  var message="";
  var bad=false;
  if(p.firstName&&!p.lastName){message="Add your last name too.";bad=true;}
  else if(p.lastName&&!p.firstName){message="Add your first name too.";bad=true;}
  else if(p.usernameHadSpaces){message="Username cannot include spaces.";bad=true;}
  else if(p.username&&p.username.length<2){message="Username needs at least 2 characters.";bad=true;}
  else if(p.email&&!validEmail(p.email)){message="Enter a real email address, like name@example.com.";bad=true;}
  else if(p.password&&validAccountPasswordReason(p.password)){message=validAccountPasswordReason(p.password);bad=true;}
  else if(!currentUser&&p.firstName&&p.lastName&&p.username&&p.email&&validEmail(p.email)&&p.password&&!validAccountPasswordReason(p.password)&&!p.termsAccepted){message="Agree to the Terms and Privacy Policy before creating an account.";bad=true;}
  else if(p.firstName&&p.lastName&&p.username&&p.email&&validEmail(p.email)&&(currentUser||p.password&&!validAccountPasswordReason(p.password))){message=currentUser?"Looks good. Save your profile, then create a pool or join one.":"Looks good. Create your account, then create a pool or join one.";}
  setSetupMessage(message,bad);
  setMemberMessage(message,bad);
};
function getPasswordInput(){
  var setupVisible=document.body.classList.contains("app-profile-locked");
  var el=document.getElementById(setupVisible?"setupPasswordInput":"memberPasswordInput")||document.getElementById("setupPasswordInput")||document.getElementById("memberPasswordInput");
  return removeCredentialSpaces(el&&el.value);
}
function userRootDoc(uid){return doc(db,"users",uid);}
function usernameReservationDoc(key){return doc(db,"usernames",key);}
function usernameReservationOwner(data){
  data=data||{};
  return String(data.uid||data.authUid||data.memberId||data.userId||"");
}
async function usernameIsTaken(username,uid){
  var key=usernameKey(username);
  if(!key)return false;
  var snap=await getDoc(usernameReservationDoc(key));
  if(!snap.exists())return false;
  var owner=usernameReservationOwner(snap.data()||{});
  return !(uid&&owner&&String(owner)===String(uid));
}
async function usernameAvailableOrMessage(username,uid,messageFn){
  try{
    if(await usernameIsTaken(username,uid)){
      messageFn("Username taken.",true);
      return false;
    }
    return true;
  }catch(e){
    console.warn("Could not check username availability",e);
    messageFn("Could not check if that username is available. Check the connection, then try again.",true);
    return false;
  }
}
function setProfileUsernameStatus(text,state){
  var el=document.getElementById("profileUsernameStatus");
  if(!el)return;
  el.classList.remove("good","bad","checking");
  if(state)el.classList.add(state);
  el.textContent=text||"";
}
window.scheduleProfileUsernameAvailabilityCheck=function(){
  clearTimeout(window.__profileUsernameCheckTimer);
  setProfileUsernameConfirm(false);
  window.__pendingProfileUsernameChange="";
  var input=document.getElementById("profileUsernameInput");
  var rawUsername=input&&input.value;
  var username=cleanUsernameHandle(rawUsername);
  var oldUsername=currentMember&&(currentMember.username||currentMember.name)||"";
  if(!username){setProfileUsernameStatus("",null);return;}
  if(usernameHasInvalidSpacing(rawUsername)){setProfileUsernameStatus("Username cannot include spaces.","bad");return;}
  if(username.length<2){setProfileUsernameStatus("Username needs at least 2 characters.","bad");return;}
  if(usernameKey(username)===usernameKey(oldUsername)){setProfileUsernameStatus("This is your current username.","good");return;}
  setProfileUsernameStatus("Checking username...","checking");
  var requestId=Date.now();
  window.__profileUsernameCheckRequest=requestId;
  window.__profileUsernameCheckTimer=setTimeout(async function(){
    if(window.__profileUsernameCheckRequest!==requestId)return;
    if(shouldUseLocalFightLocksPreviewProfile()){
      setProfileUsernameStatus("Available in this preview.","good");
      return;
    }
    var uid=(currentUser&&currentUser.uid)||(currentMember&&currentMember.authUid)||(currentMember&&currentMember.memberId);
    try{
      var taken=await usernameIsTaken(username,uid);
      if(window.__profileUsernameCheckRequest!==requestId)return;
      setProfileUsernameStatus(taken?"Username taken.":"Username available.",taken?"bad":"good");
    }catch(e){
      console.warn("Could not check username availability",e);
      if(window.__profileUsernameCheckRequest!==requestId)return;
      setProfileUsernameStatus("Could not check availability. Try again.","bad");
    }
  },500);
};
async function reserveUsernameForProfile(profile){
  if(!currentUser)return {key:"",oldKey:""};
  var uid=currentUser.uid;
  var username=profile&&((profile.username||profile.name)||"");
  var key=usernameKey(username);
  if(!key)return {key:"",oldKey:""};
  var previousUsername=(currentAccountData&&currentAccountData.username)||(currentMember&&(currentMember.username||currentMember.name))||"";
  var oldKey=usernameKey(previousUsername);
  var ref=usernameReservationDoc(key);
  var now=new Date().toISOString();
  var reservationData={
    uid:uid,
    authUid:uid,
    memberId:uid,
    displayName:username,
    username:username,
    usernameKey:key,
    updatedAt:now
  };
  if(typeof runTransaction==="function"){
    await runTransaction(db,async function(transaction){
      var snap=await transaction.get(ref);
      if(snap.exists()){
        var owner=usernameReservationOwner(snap.data()||{});
        if(owner&&String(owner)!==String(uid)){
          var error=new Error("Username taken.");
          error.code="username-taken";
          throw error;
        }
      }
      transaction.set(ref,Object.assign({},reservationData,{createdAt:(snap.exists()&&snap.data()&&snap.data().createdAt)||now}),{merge:true});
    });
  }else{
    var snap=await getDoc(ref);
    if(snap.exists()){
      var owner=usernameReservationOwner(snap.data()||{});
      if(owner&&String(owner)!==String(uid)){
        var error=new Error("Username taken.");
        error.code="username-taken";
        throw error;
      }
    }
    await setDoc(ref,Object.assign({},reservationData,{createdAt:(snap.exists()&&snap.data()&&snap.data().createdAt)||now}),{merge:true});
  }
  return {key:key,oldKey:oldKey&&oldKey!==key?oldKey:""};
}
async function releaseUsernameReservation(key,uid){
  key=usernameKey(key);
  if(!key||!uid)return;
  try{
    var snap=await getDoc(usernameReservationDoc(key));
    if(!snap.exists())return;
    if(String(usernameReservationOwner(snap.data()||{}))===String(uid))await deleteDoc(usernameReservationDoc(key));
  }catch(e){console.warn("Could not release old username reservation",e);}
}
async function releaseUsernameReservationsForDeletedUser(user){
  user=user||{};
  var uid=String(user.uid||user.docId||user.memberId||user.authUid||"");
  var email=String(user.email||"").toLowerCase();
  var keys=[user.usernameKey,user.username,user.name,user.fullName].map(usernameKey).filter(Boolean);
  await Promise.all(keys.map(function(key){return releaseUsernameReservation(key,uid);}));
  try{
    var snap=await getDocs(collection(db,"usernames"));
    var deletes=[];
    snap.docs.forEach(function(d){
      var data=d.data()||{};
      var owner=usernameReservationOwner(data);
      var docEmail=String(data.email||data.actorEmail||"").toLowerCase();
      var docKey=usernameKey(data.usernameKey||data.username||data.displayName||d.id);
      var ownerMatch=uid&&owner&&String(owner)===uid;
      var emailMatch=email&&docEmail===email;
      var keyMatch=keys.indexOf(docKey)>-1&&(uid?(!owner||String(owner)===uid):true);
      if(ownerMatch||emailMatch||keyMatch)deletes.push(deleteDoc(d.ref));
    });
    await Promise.all(deletes);
    return deletes.length;
  }catch(e){
    console.warn("Could not scan username reservations for deletion",e);
    return 0;
  }
}
async function recordAccountPoolAction(type,poolId,poolName){
  if(!currentUser)return;
  poolId=poolSlug(poolId)||currentPoolId;
  poolName=poolName||displayPoolName(poolId);
  var now=new Date().toISOString();
  var patch={lastPoolAction:{type:type,poolId:poolId,poolName:poolName,at:now},updatedAt:now};
  if(type==="joined_pool"||type==="joined_by_code"||type==="joined_from_invite"){
    patch.joinedPools={[poolId]:{poolId:poolId,poolName:poolName,joinedAt:now,updatedAt:now}};
  }
  if(type==="hosting_admin"){
    patch.hostedPools={[poolId]:{poolId:poolId,poolName:poolName,createdAt:now,updatedAt:now}};
  }
  try{
    await setDoc(userRootDoc(currentUser.uid),patch,{merge:true});
    currentAccountData=Object.assign({},currentAccountData,patch,{
      joinedPools:Object.assign({},currentAccountData.joinedPools||{},patch.joinedPools||{}),
      hostedPools:Object.assign({},currentAccountData.hostedPools||{},patch.hostedPools||{})
    });
  }catch(e){console.warn("Could not record pool action",e);}
}
async function persistAccountProfile(profile,options){
  if(!currentUser)return;
  options=options||{};
  var joinPool=options.joinPool!==false;
  var now=new Date().toISOString();
  var names=normalizedProfileNames(profile);
  var profileBanner=profile.profileBanner||profile.bannerKey||(currentMember&&(currentMember.profileBanner||currentMember.bannerKey))||(currentAccountData&&(currentAccountData.profileBanner||currentAccountData.bannerKey))||"";
  var account={uid:currentUser.uid,memberId:currentUser.uid,firstName:names.firstName,lastName:names.lastName,fullName:names.fullName,username:profile.username||profile.name,usernameKey:usernameKey(profile.username||profile.name),name:profile.name,email:profile.email,profileBanner:profileBanner,createdAt:(currentAccountData&&currentAccountData.createdAt)||profile.createdAt||now,updatedAt:now};
  if(profile.acceptedTermsAt||currentAccountData.acceptedTermsAt){
    account.acceptedTermsAt=profile.acceptedTermsAt||currentAccountData.acceptedTermsAt;
    account.acceptedTermsVersion=profile.acceptedTermsVersion||currentAccountData.acceptedTermsVersion||FIGHT_LOCKS_TERMS_VERSION;
    account.acknowledgedNoBetting=profile.acknowledgedNoBetting!==undefined?!!profile.acknowledgedNoBetting:!!currentAccountData.acknowledgedNoBetting;
  }
  if(joinPool){
    account.joinedPools={[currentPoolId]:{poolId:currentPoolId,poolName:displayPoolName(currentPoolId),joinedAt:now,updatedAt:now}};
    account.lastPoolAction={type:"profile_created",poolId:currentPoolId,poolName:displayPoolName(currentPoolId),at:now};
  }
  var wasPoolMember=false;
  var usernameReservation=null;
  if(joinPool){
    try{
      var existingMember=await getDoc(poolDoc("members",currentUser.uid));
      wasPoolMember=existingMember.exists();
    }catch(e){}
  }
  usernameReservation=await reserveUsernameForProfile(account);
  await setDoc(userRootDoc(currentUser.uid),account,{merge:true});
  if(joinPool){
    await setDoc(poolDoc("members",currentUser.uid),Object.assign({},profile,{firstName:names.firstName,lastName:names.lastName,fullName:names.fullName,memberId:currentUser.uid,authUid:currentUser.uid}),{merge:true});
    currentPoolMemberApproved=true;
    if(!wasPoolMember){
      await addPoolNotice("member_joined",currentPoolId,{uid:currentUser.uid,memberId:currentUser.uid,email:profile.email,name:profile.name||profile.username||names.fullName,poolName:displayPoolName(currentPoolId)});
    }
  }else{
    currentPoolMemberApproved=false;
  }
  if(usernameReservation&&usernameReservation.oldKey)await releaseUsernameReservation(usernameReservation.oldKey,currentUser.uid);
  currentAccountData=Object.assign({},currentAccountData,account,{joinedPools:Object.assign({},currentAccountData.joinedPools||{},account.joinedPools||{})});
}
async function ensureAuthAccount(name,email,password){
  lastAuthError=null;
  if(localDemoMode){
    setSetupMessage("Demo mode uses a local sample profile. Firebase account creation is disabled.",true);
    setMemberMessage("Demo mode uses a local sample profile. Firebase account creation is disabled.",true);
    return null;
  }
  if(currentUser){
    if(currentUser.email&&currentUser.email.toLowerCase()!==email.toLowerCase()){
      setSetupMessage("Sign out first if you want to use a different email.",true);
      setMemberMessage("Sign out first if you want to use a different email.",true);
      return null;
    }
    return currentUser;
  }
  var passwordReason=validAccountPasswordReason(password);
  if(!password||passwordReason){
    setSetupMessage(passwordReason||"Enter a password with at least 8 characters.",true);
    setMemberMessage(passwordReason||"Enter a password with at least 8 characters.",true);
    return null;
  }
	  try{
	    var created=await withFirebaseTimeout(createUserWithEmailAndPassword(auth,email,password),"creating your account",15000);
	    currentUser=created.user;
	    try{await updateProfile(currentUser,{displayName:name});}catch(e){}
	    trackCreatorEvent("signup",{uid:currentUser.uid,email:email,name:name,poolId:currentPoolId});
	    return currentUser;
  }catch(e){
    lastAuthError=e;
    if(e&&e.code==="auth/email-already-in-use"){
      setSetupMessage("A Firebase Authentication login still exists with that email. Delete it under Firebase Authentication > Users, or use the deployed Creator Tools signed in as a creator. This local preview can clean website profile data, but it cannot remove Firebase Authentication logins.",true);
      setMemberMessage("A Firebase Authentication login still exists with that email. Delete it in Firebase Authentication > Users, or sign in/reset the password.",true);
      return null;
    }
    setSetupMessage(authFriendlyError(e),true);
    setMemberMessage(authFriendlyError(e),true);
    return null;
  }
}
async function hydrateProfileFromAccount(user){
  if(!user)return;
  try{
    clearStaleActiveProfile(user);
    var poolMember=await getDoc(poolDoc("members",user.uid));
    var account=await getDoc(userRootDoc(user.uid));
    var accountData=account.exists()?account.data():null;
    currentAccountData=accountData||{};
    var hosted=accountData&&accountData.hostedPools&&accountData.hostedPools[currentPoolId];
    currentAdminKey=(hosted&&hosted.adminKey)||localAdminKey(currentPoolId)||"";
    if(currentAdminKey)rememberAdminKey(currentPoolId,currentAdminKey);
    var poolMemberData=poolMember.exists()?poolMember.data():null;
    currentPoolMemberApproved=poolMember.exists();
    var accountHasProfile=!!(accountData&&(accountData.name||accountData.username)&&accountData.email);
    var poolMemberHasProfile=!!(poolMemberData&&(poolMemberData.name||poolMemberData.username)&&poolMemberData.email);
    var data=accountHasProfile?accountData:(poolMemberHasProfile?poolMemberData:accountData);
    if(data&&(data.name||data.username)&&data.email){
      var nameSource=Object.assign({},data,{fullName:data.fullName||user.displayName||""});
      var names=normalizedProfileNames(nameSource);
    var hydratedProfile={memberId:user.uid,authUid:user.uid,poolId:currentPoolId,firstName:names.firstName,lastName:names.lastName,fullName:names.fullName,username:data.username||data.name,usernameKey:data.usernameKey||usernameKey(data.username||data.name),name:data.username||data.name,email:(user.email||data.email||""),profileBanner:data.profileBanner||data.bannerKey||"",createdAt:data.createdAt||new Date().toISOString(),updatedAt:data.updatedAt||new Date().toISOString()};
      storeMemberProfile(hydratedProfile);
      if(profileHasFullName(hydratedProfile)&&(!accountData||!accountData.firstName||!accountData.lastName))await persistAccountProfile(hydratedProfile,{joinPool:false});
      if(profileHasFullName(hydratedProfile)&&poolMember.exists()&&(!poolMemberData||poolMemberData.email!==hydratedProfile.email||poolMemberData.name!==hydratedProfile.name||!poolMemberData.firstName||!poolMemberData.lastName))await persistAccountProfile(hydratedProfile,{joinPool:true});
    }else{
      var setupName=document.getElementById("setupNameInput"), setupFirst=document.getElementById("setupFirstNameInput"), setupLast=document.getElementById("setupLastNameInput"), setupEmail=document.getElementById("setupEmailInput"), memberEmail=document.getElementById("memberEmailInput");
      var split=splitFullName(user.displayName||"");
      if(setupFirst&&!setupFirst.value&&split.firstName)setupFirst.value=split.firstName;
      if(setupLast&&!setupLast.value&&split.lastName)setupLast.value=split.lastName;
      if(setupName&&!setupName.value&&user.displayName)setupName.value=user.displayName.split(" ")[0]||user.displayName;
      if(setupEmail&&!setupEmail.value&&user.email)setupEmail.value=user.email;
      if(memberEmail&&!memberEmail.value&&user.email)memberEmail.value=user.email;
    }
    renderKnownPools();
    syncAdminAccess();
  }catch(e){console.warn("Could not load account profile",e);}
}
function readSavedMember(){
  try{
    var raw=localStorage.getItem(memberStorageKey("profile"));
    return raw?JSON.parse(raw):null;
  }catch(e){return null;}
}
function readGlobalProfile(){
  try{
    var raw=localStorage.getItem(globalProfileKey());
    return raw?JSON.parse(raw):null;
  }catch(e){return null;}
}
function userIdentityEmail(user){
  return String(user&&user.email||"").trim().toLowerCase();
}
function profileIdentityEmail(profile){
  return String(profile&&profile.email||"").trim().toLowerCase();
}
function isLocalFallbackEmail(email){
  email=String(email||"").trim().toLowerCase();
  return !!email&&(/@fightlocks\.local$/i.test(email)||/@fightlocks\.preview$/i.test(email));
}
function authenticatedAccountEmail(){
  var user=currentUser||(typeof auth!=="undefined"&&auth&&auth.currentUser);
  return String(user&&user.email||"").trim().toLowerCase();
}
function preferredProfileEmail(profile){
  var authEmail=authenticatedAccountEmail();
  if(authEmail)return authEmail;
  var candidates=[
    currentAccountData&&currentAccountData.email,
    profile&&profile.accountEmail,
    profile&&profile.authEmail
  ];
  try{
    var globalProfile=readGlobalProfile&&readGlobalProfile();
    if(globalProfile)candidates.push(globalProfile.email,globalProfile.accountEmail,globalProfile.authEmail);
  }catch(e){}
  for(var i=0;i<candidates.length;i++){
    var candidate=String(candidates[i]||"").trim().toLowerCase();
    if(candidate&&!isLocalFallbackEmail(candidate))return candidate;
  }
  var savedEmail=profileIdentityEmail(profile);
  if(savedEmail&&!isLocalFallbackEmail(savedEmail))return savedEmail;
  return savedEmail;
}
function profileBelongsToCurrentUser(profile,user){
  user=user||currentUser;
  if(!profile||!user)return true;
  var uid=String(user.uid||"");
  var ids=[profile.memberId,profile.authUid,profile.uid,profile.userId].filter(Boolean).map(String);
  if(uid&&ids.indexOf(uid)>-1)return true;
  var userEmail=userIdentityEmail(user);
  var profileEmail=profileIdentityEmail(profile);
  if(userEmail&&profileEmail&&userEmail===profileEmail)return true;
  return false;
}
function clearStaleActiveProfile(user){
  try{
    var saved=readSavedMember();
    if(saved&&!profileBelongsToCurrentUser(saved,user)){
      localStorage.removeItem(memberStorageKey("profile"));
      localStorage.removeItem(memberStorageKey("id"));
    }
    var globalSaved=readGlobalProfile();
    if(globalSaved&&!profileBelongsToCurrentUser(globalSaved,user)){
      localStorage.removeItem(globalProfileKey());
    }
  }catch(e){}
  if(user&&currentMember&&!profileBelongsToCurrentUser(currentMember,user)){
    currentMember=null;
    currentMemberId=null;
  }
}
function storeMemberProfile(profile){
  if(currentUser&&profile&&!profileBelongsToCurrentUser(profile,currentUser)){
    console.warn("Ignored stale local profile because it does not match the signed-in user.");
    clearStaleActiveProfile(currentUser);
    return;
  }
  if(profile){
    var names=normalizedProfileNames(profile);
    var email=preferredProfileEmail(profile);
    profile=Object.assign({},profile,{firstName:names.firstName,lastName:names.lastName,fullName:names.fullName,usernameKey:profile.usernameKey||usernameKey(profile.username||profile.name),email:email||profile.email||""});
  }
  currentMember=profile;
  currentMemberId=profile&&profile.memberId;
  try{
    localStorage.setItem(memberStorageKey("id"),currentMemberId||"");
    localStorage.setItem(memberStorageKey("profile"),JSON.stringify(profile||{}));
    if(profile)localStorage.setItem(globalProfileKey(),JSON.stringify({memberId:profile.memberId,authUid:profile.authUid||profile.memberId,firstName:profile.firstName||"",lastName:profile.lastName||"",fullName:profile.fullName||"",username:profile.username||profile.name,usernameKey:profile.usernameKey||usernameKey(profile.username||profile.name),name:profile.name,email:profile.email,profileBanner:profile.profileBanner||profile.bannerKey||"",createdAt:profile.createdAt||new Date().toISOString()}));
  }catch(e){}
}
