    if(isCommunityJoinFlowActive()){
      keepCommunityJoinReady("Email verified. Tap Join Freedom 250 Pool to enter the community pool.");
      setMemberMessage("Email verified. Tap Join Freedom 250 Pool to enter the community pool.");
      return;
    }
    setSetupMessage(accountCreatedMessage());
    setMemberMessage("Email verified. You can choose a pool now.");
