function cleanPostLoginRoute(scrollTarget){
  if(!currentUser&&!currentMember)return;
  setLandingRouteActive(false);
  var params=new URLSearchParams(window.location.search);
  [
    "myPicksChampionBelt","titleBeltSelection","footerLogo","footerLogoSize","footerBrandCenter",
    "footerTight","previewBanner","previewBannerShort","previewBannerScale","previewBannerShortAsset",
    "previewBlackBanner","featureRailRestored","poolBadgeCompact","previewOuterBg","arenaPreviewBg",
    "champBelt","bannerPreview"
  ].forEach(function(k){params.delete(k);});
  var keepHash=window.location.hash&&!/^#(setupPreview|landingFeatures|landingStats|landingContact)$/i.test(window.location.hash);
  var next=window.location.pathname+(params.toString()?"?"+params.toString():"")+(keepHash?window.location.hash:"");
  if((window.location.pathname+window.location.search+window.location.hash)!==next){
    try{history.replaceState(null,"",next);}catch(e){}
  }
  setTimeout(function(){
    var target=scrollTarget||(accountNeedsPoolChoice?".setup-body":".tabs");
    var el=document.querySelector(target);
    if(el)el.scrollIntoView({behavior:"auto",block:"start"});
    else window.scrollTo({top:0,behavior:"auto"});
  },0);
}
