async function pruneDeletedSavedPools(){
  if(localDemoMode||!currentUser||!currentUser.uid||!currentAccountData||window.__pruningDeletedSavedPools)return;
  var pruneUid=currentUser.uid;
  var pools=savedPoolsList();
  if(!pools.length)return;
  window.__pruningDeletedSavedPools=true;
  try{
    var removeIds=[];
    await Promise.all(pools.map(async function(p){
      var id=poolSlug(p.poolId);
      if(!id)return;
      try{
        var snap=await getDoc(doc(db,"deletedPools",id));
        if(snap.exists()){removeIds.push(id);return;}
        var poolSnap=await getDoc(doc(db,"pools",id));
        if(!poolSnap.exists())removeIds.push(id);
      }catch(e){}
    }));
    if(!removeIds.length)return;
    var joined=Object.assign({},currentAccountData.joinedPools||{}), hosted=Object.assign({},currentAccountData.hostedPools||{}), patch={updatedAt:new Date().toISOString()}, changed=false;
    removeIds.forEach(function(id){
      if(joined[id]){delete joined[id];changed=true;}
      if(hosted[id]){delete hosted[id];changed=true;}
    });
    if(!changed)return;
    patch.joinedPools=joined;
    patch.hostedPools=hosted;
    if(!pruneUid)return;
    try{await setDoc(userRootDoc(pruneUid),patch,{merge:true});}catch(e){console.warn("Could not prune deleted saved pools",e);}
    currentAccountData=Object.assign({},currentAccountData,{joinedPools:joined,hostedPools:hosted});
    if(removeIds.indexOf(currentPoolId)>-1)handleDeletedPool({poolId:currentPoolId,poolName:displayPoolName(currentPoolId)});
    else renderKnownPools();
  }finally{
    window.__pruningDeletedSavedPools=false;
  }
}
