window.setLandingPublicSection=function(section,opts){
  opts=opts||{};
  setLandingRouteActive(true);
  var labels={"how-it-works":"How It Works",features:"Features",pricing:"Pricing",faq:"FAQ"};
  var shell=document.getElementById("setupHome");
  var home=document.getElementById("landingHomeContent");
  var publicSection=document.getElementById("landingPublicSection");
  var how=document.getElementById("landingHowItWorksContent");
  var features=document.getElementById("landingFeaturesContent");
  var pricing=document.getElementById("landingPricingContent");
  var faq=document.getElementById("landingFaqContent");
  var placeholder=document.getElementById("landingPublicPlaceholder");
  var title=document.getElementById("landingPublicSectionTitle");
  var account=document.querySelector(".fight-landing > .setup-body");
  var myPools=document.getElementById("myPoolsView");
  var isHome=!section||section==="home";
  var isHow=section==="how-it-works";
  var isFeatures=section==="features";
  var isPricing=section==="pricing";
  var isFaq=section==="faq";
  if(home)home.hidden=!isHome;
  if(publicSection)publicSection.hidden=isHome;
  if(how)how.hidden=!isHow;
  if(features)features.hidden=!isFeatures;
  if(pricing)pricing.hidden=!isPricing;
  if(faq)faq.hidden=!isFaq;
  if(placeholder)placeholder.hidden=isHome||isHow||isFeatures||isPricing||isFaq;
  if(title&&!isHome&&!isHow&&!isFeatures&&!isPricing&&!isFaq)title.textContent=labels[section]||"FAQ";
  if(account)account.hidden=true;
  if(myPools)myPools.hidden=true;
  if(shell)shell.classList.remove("onboarding-active","my-pools-active");
  resetLandingPreviewForPublicNav(isHome);
  if(!opts.preserveHash)updateLandingRouteHash(isHome?"home":section);
  if(opts.scroll!==false){
    if(isHome)resetPublicLandingScroll("setLandingPublicSection-home");
    else window.scrollTo({top:0,behavior:"smooth"});
  }
};
