function startPoolPlanLabel(plan){
  return ({free:"Fight Locks Free Pool",free_starter:"Fight Locks Free Pool",single:"Fight Locks Event Pass",single_event:"Fight Locks Event Pass",commissioner:"Fight Locks Commissioner",premium:"Founder Deal",premium_community:"Founder Deal",all_events:"Fight Locks All Events Pass",founder:"Founder Deal"})[plan]||planDisplayName(plan)||planDisplayName(normalizeStartPoolPlan(plan));
}
function startPoolEventHasConfiguredCard(event){
  return !!(event&&Array.isArray(event.fights)&&event.fights.length);
}
function startPoolEventUnavailableMessage(){
  return "Fight card setup is coming soon. Pools open after Fight Locks adds the fighters.";
}
function startPoolFreeEventNotOpenMessage(event){
  var name=(event&&((event.eventLabel||event.eventName)))||"this card";
  return name+" pool setup opens when Fight Locks opens the card for picks. Start a Free Pool on the current open card for now.";
}
function startPoolSelectionBlockedMessage(){
  var event=getEventById(window.selectedStartPoolEventId);
  var access=event?startPoolPlanEventAccess(event,window.selectedStartPoolPlan||""):{};
  return (access&&access.note)||"Choose an event that is open and ready before continuing.";
}
function startPoolEventCanBeSelected(event,plan){
  if(!startPoolEventHasConfiguredCard(event))return false;
  var normalized=normalizeStartPoolPlan(plan||window.selectedStartPoolPlan||"");
  if(normalized==="free_starter")return normalizeEventStatus(event&&event.eventStatus)==="open_for_picks";
  return true;
}
function startPoolDefaultReadyEventId(){
  var active=getEventById(getActiveEventId());
  if(startPoolEventCanBeSelected(active,window.selectedStartPoolPlan||"free_starter"))return active.eventId;
  var ready=startPoolVisibleEventList().filter(function(event){return startPoolEventCanBeSelected(event,window.selectedStartPoolPlan||"free_starter");});
  return (ready[0]&&ready[0].eventId)||DEFAULT_EVENT_ID;
}
function selectedStartPoolEventIds(allowEmpty){
  var ids=Array.isArray(window.selectedStartPoolEventIds)?window.selectedStartPoolEventIds.slice():[];
  if(window.selectedStartPoolEventId&&!ids.includes(window.selectedStartPoolEventId))ids.unshift(window.selectedStartPoolEventId);
  ids=ids.filter(function(id,index,self){
    var event=getEventById(id);
    return !!event&&startPoolEventCanBeSelected(event,window.selectedStartPoolPlan||"")&&self.indexOf(id)===index;
  });
  if(!ids.length&&!allowEmpty)ids=[startPoolDefaultReadyEventId()];
  window.selectedStartPoolEventIds=ids;
  window.selectedStartPoolEventId=ids[0]||"";
  return ids;
}
function selectedStartPoolEventLabels(){
  return selectedStartPoolEventIds((window.selectedStartPoolPlan||"")==="single").map(function(id){
    var event=getEventById(id);
    return event&&(event.eventLabel||event.eventName)||id;
  });
}
function eventPassSelectionSummaryText(){
  var labels=selectedStartPoolEventLabels();
  var count=labels.length;
  if(!count)return "No Event Passes selected";
  return count+" Event Pass"+(count===1?"":"es")+" selected";
}
function eventPassSelectionDetailText(){
  var labels=selectedStartPoolEventLabels();
  if(!labels.length)return "Choose one or more upcoming events to include in checkout.";
  return "Selected Event Pass"+(labels.length===1?"":"es")+": "+labels.join(", ")+".";
}
function updateEventPassSelectionSummary(){
  var summary=document.getElementById("landingEventPassSummary");
  if(!summary)return;
  var active=(window.selectedStartPoolPlan||"")==="single";
  summary.classList.toggle("show",active);
  if(!active){summary.innerHTML="";return;}
  var labels=selectedStartPoolEventLabels();
  var count=labels.length;
  if(!count){
    summary.innerHTML='<span><strong>No Event Passes selected</strong><br>'+escapeHtml(eventPassSelectionDetailText())+'</span><span class="landing-event-pass-count">0 passes</span>';
    return;
  }
  summary.innerHTML='<span><strong>'+escapeHtml(eventPassSelectionSummaryText())+'</strong><br>'+escapeHtml(eventPassSelectionDetailText())+'</span><span class="landing-event-pass-count">'+escapeHtml(String(count))+' pass'+(count===1?'':'es')+'</span>';
}
function startPoolEventStatusLabel(status){
  return eventStatusDisplay(status);
}
function startPoolEventDateValue(event){
  if(!event||!event.eventDate)return null;
  var raw=String(event.eventDate).trim();
  var now=new Date();
  var year=now.getFullYear();
  var parsed=new Date(raw+" "+year+" 12:00:00");
  if(isNaN(parsed.getTime()))parsed=new Date(raw+", "+year+" 12:00:00");
  if(isNaN(parsed.getTime()))return null;
  if(parsed<new Date(now.getFullYear(),now.getMonth(),now.getDate()-14,0,0,0,0)){
    parsed.setFullYear(parsed.getFullYear()+1);
  }
  return parsed;
}
function isStartPoolAnnualPlan(plan){
  return plan==="premium"||plan==="all_events"||plan==="founder";
}
function isPaidStartPoolPlan(plan){
  var normalized=normalizeStartPoolPlan(plan||window.selectedStartPoolPlan||"");
  return normalized==="single_event"||normalized==="commissioner"||normalized==="premium_community"||normalized==="all_events"||normalized==="founder";
}
function startPoolCheckoutPrice(plan){
  var normalized=normalizeStartPoolPlan(plan||window.selectedStartPoolPlan||"");
  if(normalized==="single_event"){
    var count=selectedStartPoolEventLabels().length||1;
    return "$"+(count*9.99).toFixed(2);
  }
  if(normalized==="commissioner")return "$19.99 / month";
  if(normalized==="premium_community"||normalized==="all_events"||normalized==="founder")return "$69.99 first year";
  return "$0";
}
function startPoolCheckoutBenefit(plan){
  var normalized=normalizeStartPoolPlan(plan||window.selectedStartPoolPlan||"");
  if(normalized==="single_event")return "Includes unlimited players for the selected event pass checkout.";
  if(normalized==="commissioner")return "Includes player results history inside your pool for recurring events.";
  if(normalized==="premium_community"||normalized==="all_events"||normalized==="founder")return "Includes one year of event access and player results history inside your pool.";
  return "Includes the full Fight Locks pool experience with unlimited players through UFC 329.";
}
