function updateLandingLaunchCodePanel(){
  var panel=document.getElementById("landingLaunchCodePanel");
  var msg=document.getElementById("landingLaunchCodeMsg");
  var input=document.getElementById("landingLaunchCodeInput");
  if(!panel)return;
  var plan=normalizeStartPoolPlan(window.selectedStartPoolPlan||"");
  var show=plan==="free_starter"&&!LAUNCH_FREE_PROMO_ACTIVE;
  panel.hidden=!show;
  if(!show){
    if(input)input.value="";
    if(msg){msg.classList.remove("bad");msg.textContent="";}
    return;
  }
  if(msg){
    msg.classList.remove("bad");
    msg.textContent="Leave blank for the standard launch Free Pool.";
  }
}
function startPoolLaunchCodePatch(planType){
  var input=document.getElementById("landingLaunchCodeInput");
  var msg=document.getElementById("landingLaunchCodeMsg");
  var code=String((input&&input.value)||"").trim().toUpperCase().replace(/\s+/g,"");
  if(msg){msg.classList.remove("bad");}
  if(normalizeStartPoolPlan(planType)!=="free_starter")return null;
  if(LAUNCH_FREE_PROMO_ACTIVE){
    var promoNow=new Date().toISOString();
    if(msg)msg.textContent="Launch promo will be applied when this pool is created.";
    return {freePoolUnlimitedPlayers:true,launchCodeUnlimitedPlayers:true,launchUnlockCodeApplied:true,launchUnlockCode:"LAUNCH_PROMO_UFC_329",launchUnlockCodeAppliedAt:promoNow};
  }
  if(!code)return null;
  if(code!==FREE_POOL_LAUNCH_UNLOCK_CODE){
    if(msg){msg.classList.add("bad");msg.textContent="That code did not match. Use GSPGOAT or leave it blank for the standard launch Free Pool.";}
    setSetupMessage("Launch access code did not match. Use GSPGOAT or leave it blank.",true);
    return false;
  }
  var now=new Date().toISOString();
  if(msg)msg.textContent="GSPGOAT will be applied when this pool is created.";
  return {freePoolUnlimitedPlayers:true,launchCodeUnlimitedPlayers:true,launchUnlockCodeApplied:true,launchUnlockCode:"GSPGOAT",launchUnlockCodeAppliedAt:now};
}
