window.startPoolCheckoutPlaceholder=function(){
  setSetupMessage("Checkout review is ready. Stripe checkout connects here next; after payment succeeds, the pool will be created and unlocked.");
};
async function createStartPoolFromSetup(profile,planType,paidMeta){
  var poolName=document.getElementById("setupNewPoolName");
  var codeInput=document.getElementById("setupNewPoolCode");
  var typedName=(poolName&&poolName.value||"").trim();
  planType=normalizeStartPoolPlan(planType||window.selectedStartPoolPlan||"");
  if(!typedName){setSetupMessage("Name your pool first.",true);return false;}
  var requestedCode=poolPasscode(codeInput&&codeInput.value);
  var passcodeReason=weakPoolPasscodeReason(requestedCode);
  if(passcodeReason){setSetupMessage(passcodeReason,true);return false;}
  var selectedEventIds=selectedStartPoolEventIds(planType==="single_event");
  if(!selectedEventIds.length){
    setSetupMessage(startPoolSelectionBlockedMessage(),true);
    return false;
  }
  var newId=await uniquePoolCode(typedName);
  if(joinPasscodeLooksGenerated(requestedCode,newId,newId)){setSetupMessage("Choose a join passcode that is different from the generated Pool Name Code.",true);return false;}
  var launchPatch=startPoolLaunchCodePatch(planType);
  if(launchPatch===false)return false;
  setSetupMessage((paidMeta&&paidMeta.testCheckout)?"Test checkout complete. Creating your pool and admin key...":"Creating your pool and admin key...");
  try{await createAdminPool(newId,typedName,profile,requestedCode,planType,selectedEventIds[0],selectedEventIds,launchPatch||{});}
  catch(e){console.error(e);setSetupMessage("Could not create admin pool. Try again.",true);return false;}
  markManualPoolOpen(newId);
  window.location.href=quickPoolSetupUrl(newId);
  return true;
}
window.completeStartPoolTestCheckout=async function(){
  if(!currentUser||!currentMember){
    setSetupMessage("Sign in or finish creating your account before test checkout.",true);
    return;
  }
  if(currentUser&&!(await requireVerifiedEmailForPath()))return;
  var planType=normalizeStartPoolPlan(window.selectedStartPoolPlan);
  if(!isPaidStartPoolPlan(planType)){
    setSetupMessage("Test checkout is only needed for paid plans.",true);
    return;
  }
  var btn=document.querySelector("#landingCheckoutReview .primary");
  if(btn){btn.disabled=true;btn.textContent="Completing Test Checkout...";}
  setSetupMessage("Completing test checkout...");
  var ok=await createStartPoolFromSetup(currentMember,planType,{testCheckout:true});
  if(!ok&&btn){btn.disabled=false;btn.textContent="Complete Test Checkout";}
};
function startPoolPlanEventAccess(event,plan){
  plan=plan||window.selectedStartPoolPlan||"free";
  var date=startPoolEventDateValue(event);
  var today=new Date();
  var start=new Date(today.getFullYear(),today.getMonth(),today.getDate(),0,0,0,0);
  var firstWindowEnd=new Date(start.getTime());
  firstWindowEnd.setDate(firstWindowEnd.getDate()+30);
  var annualEnd=new Date(start.getTime());
  annualEnd.setFullYear(annualEnd.getFullYear()+1);
  var setupPending=!startPoolEventHasConfiguredCard(event);
  var setupPendingNote=" Fight card setup is coming soon; this event is still covered by your plan.";
  if(plan==="commissioner"){
    if(date&&date>=start&&date<firstWindowEnd){
      return {className:"commissioner-included"+(setupPending?" start-card-setup-pending":""),badge:"Included in your plan",badgeClass:"included",note:"Included in your Commissioner plan first billing window if you start today."+(setupPending?setupPendingNote:""),disabled:setupPending};
    }
    return {className:"commissioner-renewal"+(setupPending?" start-card-setup-pending":""),badge:"Included with renewal",badgeClass:"renewal",note:"Included as long as your monthly Commissioner access continues. You would only lose access to this event if you cancel before that billing window."+(setupPending?setupPendingNote:""),disabled:setupPending};
  }
  if(isStartPoolAnnualPlan(plan)){
    if(!date||date<annualEnd)return {className:"annual-included"+(setupPending?" start-card-setup-pending":""),badge:"Included in your plan",badgeClass:"annual",note:"Included in your All Events Pass upcoming events during your 12-month access window."+(setupPending?setupPendingNote:""),disabled:setupPending};
  }
  if(setupPending){
    if(plan==="single")return {className:"start-card-unavailable",badge:"Event Pass Soon",badgeClass:"event-pass",note:"Event Pass purchase opens after Fight Locks adds the fighters.",disabled:true};
    return {className:"start-card-unavailable",badge:"Setup Coming Soon",badgeClass:"unavailable",note:startPoolEventUnavailableMessage(),disabled:true};
  }
  if(normalizeStartPoolPlan(plan)==="free_starter"&&normalizeEventStatus(event&&event.eventStatus)!=="open_for_picks"){
    return {className:"start-card-unavailable",badge:"Not Open Yet",badgeClass:"unavailable",note:startPoolFreeEventNotOpenMessage(event),disabled:true};
  }
  if(plan==="single"){
    return {className:"",badge:"Event Pass",badgeClass:"event-pass",note:"Add this event pass to your checkout. The first selected event starts this pool."};
  }
  if(normalizeEventStatus(event&&event.eventStatus)==="locked"){
    return {className:"",badge:startPoolEventStatusLabel(event&&event.eventStatus),badgeClass:"",note:"You can create the pool now. Picks open when Fight Locks unlocks this card."};
  }
  return {className:"",badge:startPoolEventStatusLabel(event&&event.eventStatus),badgeClass:"",note:""};
}
function updateStartPoolEventSubtitle(){
  var subtitle=document.querySelector("#landingEventSelect .landing-event-subtitle");
  if(!subtitle)return;
  var plan=window.selectedStartPoolPlan||"";
  if(plan==="commissioner")subtitle.textContent="Green events are included in your plan now. Gold events are included later as long as your monthly access continues; you only lose future access if you cancel before that billing window.";
  else if(isStartPoolAnnualPlan(plan))subtitle.textContent="All upcoming eligible events are included in your plan during your 12-month All Events Pass window.";
  else if(plan==="single")subtitle.textContent="Choose one or more Event Passes. The first selected event is where this pool starts.";
  else subtitle.textContent="Choose the fight card this pool is for.";
}
function startPoolVisibleEventList(){
  return Object.keys(EVENTS).map(function(id){return EVENTS[id];}).filter(function(event){return event&&isEventVisibleToUsers(event)&&!isEventCompleted(event)&&!event.startPoolHidden;}).sort(function(a,b){
    var ad=startPoolEventDateValue(a), bd=startPoolEventDateValue(b);
    var dateDiff=(ad?ad.getTime():Infinity)-(bd?bd.getTime():Infinity);
    if(dateDiff)return dateDiff;
    return String(a&&a.eventName||"").localeCompare(String(b&&b.eventName||""));
  });
}
function startPoolCommissionerIncludedEvents(){
  return startPoolVisibleEventList().filter(function(event){
    return startPoolEventCanBeSelected(event,"commissioner")&&startPoolPlanEventAccess(event,"commissioner").className==="commissioner-included";
  });
}
function startPoolCommissionerDefaultEventId(){
  var included=startPoolCommissionerIncludedEvents();
  included.sort(function(a,b){
    var ad=startPoolEventDateValue(a), bd=startPoolEventDateValue(b);
    return (ad?ad.getTime():Infinity)-(bd?bd.getTime():Infinity);
  });
  return (included[0]&&included[0].eventId)||startPoolDefaultReadyEventId();
}
function startPoolAnnualDefaultEventId(){
  var events=startPoolVisibleEventList().filter(function(event){return startPoolEventCanBeSelected(event,window.selectedStartPoolPlan||"all_events");});
  return (events[0]&&events[0].eventId)||startPoolDefaultReadyEventId();
}
function renderStartPoolEvents(){
  var grid=document.getElementById("landingEventGrid");
  if(!grid)return;
  if((window.selectedStartPoolPlan||"")!=="single"){
    var currentSelected=getEventById(window.selectedStartPoolEventId);
    window.selectedStartPoolEventId=startPoolEventCanBeSelected(currentSelected,window.selectedStartPoolPlan||"")?window.selectedStartPoolEventId:startPoolDefaultReadyEventId();
    window.selectedStartPoolEventIds=[window.selectedStartPoolEventId];
  }
  if((window.selectedStartPoolPlan||"")==="single")selectedStartPoolEventIds(true);
  if((window.selectedStartPoolPlan||"")==="commissioner"){
    window.selectedStartPoolEventId=startPoolCommissionerDefaultEventId();
    window.selectedStartPoolEventIds=startPoolCommissionerIncludedEvents().map(function(event){return event.eventId;});
  }else if(isStartPoolAnnualPlan(window.selectedStartPoolPlan||"")){
    window.selectedStartPoolEventId=startPoolAnnualDefaultEventId();
    window.selectedStartPoolEventIds=startPoolVisibleEventList().filter(function(event){return startPoolEventCanBeSelected(event,window.selectedStartPoolPlan||"");}).map(function(event){return event.eventId;});
  }
  installStartPoolEventCardClicks();
  updateStartPoolEventSubtitle();
  updateEventPassSelectionSummary();
  var eventList=startPoolVisibleEventList();
  grid.innerHTML=eventList.map(function(event){
    var eventPassMode=(window.selectedStartPoolPlan||"")==="single";
    var selectedIds=eventPassMode?selectedStartPoolEventIds(true):[];
    var annualMode=isStartPoolAnnualPlan(window.selectedStartPoolPlan||"");
    var commissionerMode=(window.selectedStartPoolPlan||"")==="commissioner";
    var access=startPoolPlanEventAccess(event,window.selectedStartPoolPlan);
    var unavailable=!!access.disabled;
    var selected=annualMode?String(access.className||"").indexOf("annual-included")>-1:(commissionerMode?String(access.className||"").indexOf("commissioner-included")>-1:(!unavailable&&(eventPassMode?selectedIds.includes(event.eventId):event.eventId===window.selectedStartPoolEventId)));
    var primary=eventPassMode&&selectedIds[0]===event.eventId;
    var dateLine=event.eventDate?'<p class="landing-plan-meta"><strong>Date:</strong> '+escapeHtml(event.eventDate)+'</p>':"";
    var accessNote=access.note?'<p class="landing-event-access-note">'+escapeHtml(access.note)+'</p>':"";
    var eventPassClasses=eventPassMode&&selected?" event-pass-selected"+(primary?" event-pass-primary":""):"";
    var buttonText=annualMode?(String(access.className||"").indexOf("annual-included")>-1?"Included In Your Plan":"Not Ready Yet"):(commissionerMode?(String(access.className||"").indexOf("commissioner-renewal")>-1?"Included With Renewal":"Included In Your Plan"):(unavailable?(eventPassMode?"Coming Soon":"Not Ready Yet"):(eventPassMode?(selected?"Selected":"Add Event Pass"):(selected?'Selected':'Select Event'))));
    var cardAttrs=(commissionerMode||annualMode||unavailable)?' data-plan-auto="1" aria-disabled="'+(unavailable?'true':'false')+'"':' role="button" tabindex="0" onclick="selectStartPoolEvent(\''+escapeHtml(event.eventId)+'\')" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();selectStartPoolEvent(\''+escapeHtml(event.eventId)+'\')}"';
    return '<div class="landing-pool-type-card landing-event-card '+(selected?'selected ':'')+escapeHtml(access.className||"")+eventPassClasses+'" data-start-event="'+escapeHtml(event.eventId)+'"'+cardAttrs+'>'
      +'<div class="landing-pool-type-top"><h4>'+escapeHtml(event.eventName||event.eventLabel||"Fight Card")+'</h4><span class="landing-plan-badge '+escapeHtml(access.badgeClass||"")+'">'+escapeHtml(access.badge||startPoolEventStatusLabel(event.eventStatus))+'</span></div>'
      +dateLine
      +'<p class="landing-plan-meta"><strong>Card:</strong> '+escapeHtml(event.eventLabel||event.eventName||"Fight Card")+'</p>'
      +accessNote
      +'<button class="landing-plan-action" type="button" '+((commissionerMode||annualMode||unavailable)?'disabled':'onclick="event.stopPropagation();selectStartPoolEvent(\''+escapeHtml(event.eventId)+'\')"')+'>'+buttonText+'</button>'
      +'</div>';
  }).join("");
}
window.selectStartPoolEvent=function(eventId){
  var event=(getEventById(eventId)||getEventById(DEFAULT_EVENT_ID));
  var plan=window.selectedStartPoolPlan||"";
  if(plan==="commissioner"||isStartPoolAnnualPlan(plan))return;
  var access=startPoolPlanEventAccess(event,plan);
  if(!startPoolEventHasConfiguredCard(event)||access.disabled){
    var status=document.getElementById("landingStartPlanStatus");
    if(status){
      status.textContent=(access&&access.note)||startPoolEventUnavailableMessage();
      status.classList.add("show");
    }
    return;
  }
  if(plan==="single"){
    var ids=selectedStartPoolEventIds(true);
    if(ids.includes(event.eventId)){
      if(ids.length>1)ids=ids.filter(function(id){return id!==event.eventId;});
    }else{
      ids.push(event.eventId);
    }
    window.selectedStartPoolEventIds=ids;
    window.selectedStartPoolEventId=ids[0]||event.eventId;
  }else{
    window.selectedStartPoolEventId=event.eventId;
    window.selectedStartPoolEventIds=[event.eventId];
  }
  renderStartPoolEvents();
  var account=document.querySelector(".fight-landing > .setup-body");
  var status=document.getElementById("landingStartPlanStatus");
  var selectedLine=document.getElementById("landingSelectedPlanLine");
  if(account)account.classList.remove("pool-details-ready");
  hideStartPoolCheckoutReview();
  if(status&&plan==="single"&&status.classList.contains("show"))status.textContent="Event Pass selected. "+eventPassSelectionSummaryText()+". "+eventPassSelectionDetailText()+" Continue when the event passes look right.";
  if(selectedLine){selectedLine.textContent="";selectedLine.classList.remove("show");}
  updateLandingLaunchCodePanel();
};
function installStartPoolEventCardClicks(){
  var grid=document.getElementById("landingEventGrid");
  if(!grid||grid.dataset.cardClickReady==="1")return;
  grid.dataset.cardClickReady="1";
  grid.addEventListener("click",function(event){
    if((window.selectedStartPoolPlan||"")==="commissioner"||isStartPoolAnnualPlan(window.selectedStartPoolPlan||""))return;
    var card=event.target&&event.target.closest?event.target.closest(".landing-event-card[data-start-event]"):null;
    if(!card||!grid.contains(card))return;
    if(event.target.closest&&event.target.closest(".landing-plan-action"))return;
    window.selectStartPoolEvent(card.getAttribute("data-start-event"));
  });
  grid.addEventListener("keydown",function(event){
    if((window.selectedStartPoolPlan||"")==="commissioner"||isStartPoolAnnualPlan(window.selectedStartPoolPlan||""))return;
    if(event.key!=="Enter"&&event.key!==" ")return;
    var card=event.target&&event.target.closest?event.target.closest(".landing-event-card[data-start-event]"):null;
    if(!card||!grid.contains(card))return;
    event.preventDefault();
    window.selectStartPoolEvent(card.getAttribute("data-start-event"));
  });
}
window.selectStartPoolPlan=function(plan){
  var account=document.querySelector(".fight-landing > .setup-body");
  var status=document.getElementById("landingStartPlanStatus");
  var continueBtn=document.getElementById("landingStartPlanContinue");
  var actionRow=document.getElementById("landingEventActionRow");
  var selectedLine=document.getElementById("landingSelectedPlanLine");
  var paidPlanPaused=false;
  if(isPaidStartPoolPlan(plan)){
    plan="free";
    paidPlanPaused=true;
    if(status){
      status.textContent=paidStartPoolPausedMessage();
      status.classList.add("show");
    }
  }
  window.selectedStartPoolPlan=plan||"";
  if(plan==="commissioner"){
    window.selectedStartPoolEventId=startPoolCommissionerDefaultEventId();
    window.selectedStartPoolEventIds=startPoolCommissionerIncludedEvents().map(function(event){return event.eventId;});
  }else if(isStartPoolAnnualPlan(plan)){
    window.selectedStartPoolEventId=startPoolAnnualDefaultEventId();
    window.selectedStartPoolEventIds=startPoolVisibleEventList().filter(function(event){return startPoolEventCanBeSelected(event,plan);}).map(function(event){return event.eventId;});
  }else if(plan!=="single"){
    var selectedEvent=getEventById(window.selectedStartPoolEventId);
    window.selectedStartPoolEventId=startPoolEventCanBeSelected(selectedEvent,plan)?window.selectedStartPoolEventId:startPoolDefaultReadyEventId();
    window.selectedStartPoolEventIds=[window.selectedStartPoolEventId];
  }
  else {window.selectedStartPoolEventId="";window.selectedStartPoolEventIds=[];}
  if(account)account.classList.remove("pool-details-ready");
  if(account)account.classList.toggle("start-plan-selected",!!plan);
  if(actionRow)actionRow.classList.toggle("ready",!!plan);
  if(selectedLine){selectedLine.textContent="";selectedLine.classList.remove("show");}
  document.querySelectorAll("[data-start-plan]").forEach(function(card){
    card.classList.toggle("selected",card.getAttribute("data-start-plan")===plan);
  });
  updateStartPoolCreateButton();
  updateLandingLaunchCodePanel();
  renderStartPoolEvents();
  setStartPoolTypeNote(plan==="single"?"Choose one or more Event Passes below, then tap Continue.":isStartPoolAnnualPlan(plan)?"Eligible events are included below. Tap Continue when this plan looks right.":plan==="commissioner"?"Review included events below, then tap Continue to set up your pool details.":"Review the selected event below, then tap Continue to name your Free Pool.","selected");
  if(status){
    status.textContent=paidPlanPaused?paidStartPoolPausedMessage():(plan==="commissioner"?"Commissioner selected. Green events are included in your plan now; gold events are included later as long as your monthly Commissioner access continues. You would only lose future event access if you cancel before that billing window.":plan==="single"?"Event Pass selected. "+eventPassSelectionDetailText():isStartPoolAnnualPlan(plan)?"All Events Pass selected. Every eligible upcoming event shown below is included in your plan during your 12-month access window. Continue to set up your pool details.":startPoolPlanLabel(plan)+" selected. Continue to set up your pool details.");
    status.classList.add("show");
  }
  if(continueBtn)continueBtn.classList.toggle("show",!!plan);
};
window.continueStartPoolPlan=function(){
  var account=document.querySelector(".fight-landing > .setup-body");
  var status=document.getElementById("landingStartPlanStatus");
  var selectedLine=document.getElementById("landingSelectedPlanLine");
  if(!window.selectedStartPoolPlan){
    if(status){
      status.textContent="Choose a pool type before continuing.";
      status.classList.add("show");
    }
    return;
  }
  if(window.selectedStartPoolPlan==="single"&&!selectedStartPoolEventIds(true).length){
    if(status){
      status.textContent="Choose at least one Event Pass before continuing.";
      status.classList.add("show");
    }
    return;
  }
  var readyEventIds=selectedStartPoolEventIds(window.selectedStartPoolPlan==="single");
  if(!readyEventIds.length){
    if(status){
      status.textContent=startPoolSelectionBlockedMessage();
      status.classList.add("show");
    }
    return;
  }
  if(account)account.classList.add("pool-details-ready");
  updateLandingLaunchCodePanel();
  hideStartPoolCheckoutReview();
  if(selectedLine){
    var selectedEvent=getEventById(readyEventIds[0]||window.selectedStartPoolEventId||DEFAULT_EVENT_ID)||getEventById(DEFAULT_EVENT_ID);
    var access=startPoolPlanEventAccess(selectedEvent,window.selectedStartPoolPlan);
    var accessText=access&&access.note?" · "+access.note:"";
    var eventPassText=window.selectedStartPoolPlan==="single"?" · Event passes: "+selectedStartPoolEventLabels().join(", "):isStartPoolAnnualPlan(window.selectedStartPoolPlan)?" · Included events: "+selectedStartPoolEventLabels().join(", "):" · Event: "+((selectedEvent&&selectedEvent.eventLabel)||(selectedEvent&&selectedEvent.eventName)||DEFAULT_EVENT_NAME)+accessText;
    selectedLine.textContent="Selected plan: "+startPoolPlanLabel(window.selectedStartPoolPlan)+eventPassText;
    selectedLine.classList.add("show");
  }
  if(status){
    status.textContent="Pool details are ready. Finish naming your pool and setting the join passcode.";
    status.classList.add("show");
  }
  setStartPoolTypeNote("Pool details are ready below. Name your pool, set the join passcode, then create it.", "ready");
  var firstDetail=document.getElementById("setupNewPoolName");
  if(firstDetail)firstDetail.scrollIntoView({behavior:"smooth",block:"center"});
};
function resetStartPoolPlanSelection(){
  window.selectedStartPoolPlan="";
  window.selectedStartPoolEventId=getActiveEventId();
  window.selectedStartPoolEventIds=[window.selectedStartPoolEventId];
  var account=document.querySelector(".fight-landing > .setup-body");
  var status=document.getElementById("landingStartPlanStatus");
  var continueBtn=document.getElementById("landingStartPlanContinue");
  var actionRow=document.getElementById("landingEventActionRow");
  var selectedLine=document.getElementById("landingSelectedPlanLine");
  if(account)account.classList.remove("pool-details-ready","start-plan-selected");
  hideStartPoolCheckoutReview();
  updateStartPoolCreateButton();
  updateLandingLaunchCodePanel();
  document.querySelectorAll("[data-start-plan]").forEach(function(card){card.classList.remove("selected");});
  renderStartPoolEvents();
  if(status){status.textContent="";status.classList.remove("show");}
  if(continueBtn)continueBtn.classList.remove("show");
  if(actionRow)actionRow.classList.remove("ready");
  updateEventPassSelectionSummary();
  if(selectedLine){selectedLine.textContent="";selectedLine.classList.remove("show");}
  setStartPoolTypeNote("Choose a host plan above to reveal event options.", "idle");
}
window.showLandingOnboarding=function(mode,opts){
  opts=opts||{};
  setLandingRouteActive(true);
  mode=mode||"join";
  var shell=document.getElementById("setupHome");
  var home=document.getElementById("landingHomeContent");
  var publicSection=document.getElementById("landingPublicSection");
  var account=document.querySelector(".fight-landing > .setup-body");
  var myPools=document.getElementById("myPoolsView");
  var title=document.getElementById("landingOnboardingTitle");
  var subtitle=document.getElementById("landingOnboardingSubtitle");
  var note=document.getElementById("landingOnboardingNote");
  var poolTypes=document.getElementById("landingPoolTypeSelect");
  var pathPanel=document.getElementById("setupPathPanel");
  var pathTitle=pathPanel&&pathPanel.querySelector(".setup-panel-title");
  var pathCopy=pathPanel&&pathPanel.querySelector(".setup-panel-copy");
  var signedInReady=!!(currentUser&&((currentMember&&((currentMember.name||currentMember.username||currentMember.fullName)||(currentMember.email)))||currentUser.email));
  if(typeof setCommunityJoinFieldsLocked==="function")setCommunityJoinFieldsLocked(false);
  if(home)home.hidden=true;
  if(publicSection)publicSection.hidden=true;
  if(myPools)myPools.hidden=true;
  if(shell){
    shell.classList.add("onboarding-active");
    shell.classList.remove("my-pools-active");
  }
  if(account){
    account.hidden=false;
    account.classList.remove("onboarding-join","onboarding-start","onboarding-login","account-ready");
    account.classList.add("onboarding-"+mode);
    account.classList.toggle("account-ready",signedInReady&&mode!=="login");
  }
  updateSignedInAccountCard(signedInReady&&mode!=="login");
  if(poolTypes)poolTypes.classList.toggle("show",mode==="start");
  if(mode==="login"){
    resetStartPoolPlanSelection();
    if(title){title.classList.add("has-title-art","login-title-wrap");title.innerHTML='<span>Log In</span>';}
    if(subtitle)subtitle.textContent="Log in to access pools you joined or pools you manage.";
    if(note)note.textContent="After logging in, users should be able to access the pools they joined or manage.";
    showSignInMode();
  }else if(mode==="start"){
    resetStartPoolPlanSelection();
    if(title){title.classList.remove("login-title-wrap");title.classList.add("has-title-art");title.innerHTML='<span>Start Your Pool</span>';}
    if(subtitle)subtitle.textContent="Create your account. Choose how you want to host. Pick the plan that fits best for your pool needs.";
    if(note)note.textContent="Start with a Free Pool or choose an upgraded host plan. You can review everything before the pool is created.";
    if(pathTitle)pathTitle.textContent="Choose How You Want to Host";
    if(pathCopy)pathCopy.textContent="Pick a pool type, choose your event, then continue to pool details.";
    setStartPoolTypeNote("Choose a host plan above to reveal event options.", "idle");
    if(!signedInReady)showCreateAccountMode();
    else setSetupMessage("Choose a pool type to start a new pool.");
  }else{
    resetStartPoolPlanSelection();
    if(title){title.classList.remove("login-title-wrap");title.classList.add("has-title-art");title.innerHTML='<span>Join Your Fight Locks Pool</span>';}
    if(subtitle)subtitle.textContent=signedInReady?"Enter the pool code and passcode from your host to request access with your signed-in profile.":"Create an account or sign in, then enter the pool code and passcode from your host.";
    if(note)note.textContent=signedInReady?"You're signed in, so joining another pool will use your current account.":"Players do not pay Fight Locks to join a pool. Any private group arrangements are handled outside Fight Locks by the host and participants.";
    if(pathTitle)pathTitle.textContent="Join By Code";
    if(pathCopy)pathCopy.textContent="Enter the pool code and join passcode from your host.";
    if(!signedInReady)showCreateAccountMode();
    else setSetupMessage("Enter the pool code and join passcode.");
  }
  if(!opts.preserveHash)updateLandingRouteHash(mode==="start"?"start-pool":(mode==="login"?"login":"join-pool"));
  if(mode==="join"&&typeof shouldActivateCommunityJoin==="function"&&shouldActivateCommunityJoin()){
    setTimeout(prefillCommunityPoolJoin,0);
  }
  if(opts.scroll!==false)window.scrollTo({top:0,behavior:"smooth"});
};
window.scrollToPreview=function(){
  var el=document.getElementById("preview-experience")||document.getElementById("setupPreview");
  if(el)el.scrollIntoView({behavior:"smooth",block:"start"});
};
function setCommunityJoinFieldsLocked(locked){
  var codeInput=document.getElementById("setupJoinPoolCode");
  var passInput=document.getElementById("setupJoinPoolPasscode");
  var joinByCodeBtn=document.querySelector("#setupPathPanel button[onclick=\"completeProfileSetup('code')\"]");
  [codeInput,passInput].forEach(function(input){
    if(!input)return;
    input.readOnly=!!locked;
    input.classList.toggle("community-join-locked",!!locked);
    input.setAttribute("aria-readonly",locked?"true":"false");
    input.title=locked?"Preset for the Freedom 250 community pool.":"";
  });
  if(joinByCodeBtn){
    if(locked){
      joinByCodeBtn.textContent="Join Freedom 250 Pool";
      joinByCodeBtn.dataset.communityJoin="1";
    }else if(joinByCodeBtn.dataset.communityJoin==="1"){
      joinByCodeBtn.textContent="Join By Code";
      delete joinByCodeBtn.dataset.communityJoin;
    }
  }
}
function syncCommunityPoolUi(){
  var isCommunity=isFreedom250CommunityPool();
  if(isCommunity){
    var publicCode=communityPoolPublicCode(currentPoolId);
    var publicPass=communityPoolPublicPasscode(currentPoolId);
    ["poolCurrentCode","poolCodeDisplay","currentPicksPoolCode"].forEach(function(id){var el=document.getElementById(id);if(el)el.textContent=publicCode;});
    ["poolCurrentPasscode","poolPasscodeDisplay","currentPicksPoolPasscode"].forEach(function(id){var el=document.getElementById(id);if(el)el.textContent=publicPass;});
    var link=document.getElementById("poolInviteLink");
    var profileLink=document.getElementById("profileInviteLink");
    var message=document.getElementById("poolInviteMessage");
    var inviteUrl=communityPoolInviteUrl(currentPoolId,true);
    if(link)link.value=inviteUrl;
    if(profileLink)profileLink.value=inviteUrl;
    if(message)message.value=inviteMessageText();
  }
}
function prefillCommunityPoolJoin(){
  var communityPoolCode=FREEDOM250_PRIMARY_COMMUNITY_POOL_ID;
  var communityJoinPasscode="Freedom250";
  var codeInput=document.getElementById("setupJoinPoolCode");
  var passInput=document.getElementById("setupJoinPoolPasscode");
  var inviteBtn=document.getElementById("setupJoinInviteBtn");
  setCommunityJoinFieldsLocked(false);
  if(codeInput)codeInput.value=communityPoolCode;
  if(passInput)passInput.value=communityJoinPasscode;
  setCommunityJoinFieldsLocked(true);
  if(inviteBtn){
    inviteBtn.style.display="none";
  }
  if(typeof setSetupMessage==="function")setSetupMessage(currentUser?"Freedom 250 pool is ready. Tap Join Freedom 250 Pool to enter.":"Freedom 250 pool is ready. Sign in or create your account, then tap Join Freedom 250 Pool.");
}
function setCommunityPoolJoinHint(message,bad){
  var hint=document.getElementById("communityPoolJoinHint");
  if(!hint)return;
  hint.textContent=message||"";
  hint.classList.toggle("bad",!!bad);
  hint.classList.toggle("show",!!message);
}
window.joinCommunityPool=async function(){
  if(typeof setLandingPublicSection==="function")setLandingPublicSection("home");
  if(typeof showLandingOnboarding==="function")showLandingOnboarding("join",{preserveHash:false,scroll:false});
  prefillCommunityPoolJoin();
  var signedIn=!!(currentUser&&((currentMember&&((currentMember.name||currentMember.username||currentMember.fullName)||(currentMember.email)))||currentUser.email));
  var message=signedIn?"Freedom 250 is ready. Tap Join Freedom 250 Pool to request access with this account.":"Create an account or sign in first. We filled in the Freedom 250 pool code and passcode for you.";
  setCommunityPoolJoinHint(message,!signedIn);
  if(typeof setSetupMessage==="function")setSetupMessage(message,!signedIn);
  var target=document.querySelector(".fight-landing > .setup-body")||document.getElementById("createAccountMode")||document.getElementById("setupPathPanel");
  if(target&&target.scrollIntoView)target.scrollIntoView({behavior:"smooth",block:"start"});
};
function shouldActivateCommunityJoin(){
  try{
    var params=new URLSearchParams(window.location.search);
    return params.get("community")==="1"&&isFreedom250CommunityPool(currentPoolId)&&/^#join-pool$/i.test(window.location.hash||"");
  }catch(e){return false;}
}
function isCommunityJoinFlowActive(){
  return shouldActivateCommunityJoin();
}
function keepCommunityJoinReady(message,bad){
  accountNeedsPoolChoice=true;
  markSetupPathReady(true);
  setEmailVerifyPanel(false);
  if(typeof showLandingOnboarding==="function")showLandingOnboarding("join",{preserveHash:true,scroll:false});
  if(message)setSetupMessage(message,bad);
  renderMemberGate();
  prefillCommunityPoolJoin();
  if(message)setSetupMessage(message,bad);
  renderLandingAuthNav();
}
function activateCommunityJoinFromUrl(){
  if(!shouldActivateCommunityJoin())return;
  if(typeof showLandingOnboarding==="function")showLandingOnboarding("join",{preserveHash:true,scroll:false});
  setTimeout(prefillCommunityPoolJoin,0);
  setTimeout(async function(){
    var resolved=await resolveFreedom250CommunityPoolId();
    if(resolved&&resolved!==currentPoolId){
      window.location.replace("index.html?pool="+encodeURIComponent(resolved)+"&new=1&community=1&cb=community-pool#join-pool");
    }
  },0);
}
window.scrollToAccountStart=function(){
  var el=document.querySelector(".setup-body");
  if(el&&el.hidden&&typeof showLandingOnboarding==="function")showLandingOnboarding("start");
  if(el)el.scrollIntoView({behavior:"smooth",block:"start"});
};
setTimeout(function(){
  restoreLandingRouteFromHash();
  activateCommunityJoinFromUrl();
},0);
