function previewResultRoundLabel(fight){
  if(fight.resultTiming==="distance")return (fight.title?"R5":"R3")+" 5:00";
  var match=String(fight.resultText||"").match(/R\d+\s+\d+:\d+/i);
  if(match)return match[0].toUpperCase();
  return String(fight.resultTiming||"").toUpperCase();
}
function previewResultMethodLabel(method){
  if(method==="ko")return "KO/TKO";
  if(method==="sub")return "Submission";
  return "Decision";
}
function previewTimingPts(fight,timing){
  return previewScoringRules.timingPts[timing]||0;
}
function previewMethodPts(method){
  return previewScoringRules.methodPts[method]||0;
}
function previewFightScore(fight){
  var side=fight.dantePick||fight.pick, correct=side===fight.resultWinner, total=0;
  if(correct)total+=previewSidePts(fight,side);
  if(correct&&fight.danteMethod===fight.resultMethod)total+=previewMethodPts(fight.resultMethod);
  if(correct&&fight.danteTiming===fight.resultTiming)total+=previewTimingPts(fight,fight.resultTiming);
  if(fight.danteOu===fight.resultOu)total+=previewScoringRules.overUnderPts;
  if(fight.lock&&correct)total+=previewLockPts();
  return total;
}
