function previewLeaderboardRows(){
  var rows=previewBasePlayers().map(function(player,index){
    var score=previewEntryScoreSummary(player,index);
    return Object.assign({},player,{sourceIndex:index,pts:score.pts,sub:score.correct+" / 13 Correct",correct:score.correct});
  }).sort(function(a,b){return b.pts-a.pts||b.correct-a.correct||a.name.localeCompare(b.name);});
  rows.forEach(function(row,index){row.place=(index+1)+".";row.leader=index===0;});
  return rows;
}
function renderPreviewMyPicksPanel(){
  var target=document.getElementById("previewPicksScrollContent");
  if(!target)return;
  var fights=previewUfc328Fights(), methods={ko:"KO/TKO",sub:"Sub",dec:"Decision"};
  var totals=[],running=0;
  fights.slice().reverse().forEach(function(fight){
    running+=previewFightScore(fight);
    totals[fights.indexOf(fight)]=running;
  });
  var finalTotal=previewEntryScoreSummary(previewBasePlayers()[0],0).pts;
  var details=fights.map(function(fight,index){
    var side=fight.dantePick||fight.pick, name=side===1?fight.f1:fight.f2, odds=side===1?fight.o1:fight.o2, resultName=fight.resultWinner===1?fight.f1:fight.f2, correct=side===fight.resultWinner;
    var fightPts=previewFightScore(fight), runningTotal=totals[index]||fightPts;
    var bg=correct?"#1c4532":"#742a2a", col=correct?"#68d391":"#fc8181";
    var result='<div class="my-result-line"><span class="my-result-label">Result</span><span class="my-result-pill">'+escapeHtml(resultName.split(" ").pop())+'</span><span class="my-result-method">'+previewResultMethodLabel(fight.resultMethod)+'</span><span class="my-result-method">'+previewResultRoundLabel(fight)+'</span></div>';
    var methodOk=correct&&fight.danteMethod===fight.resultMethod, timingOk=correct&&fight.danteTiming===fight.resultTiming, ouOk=fight.danteOu===fight.resultOu;
    var timingLabel=timingOk?previewResultRoundLabel(fight):(fight.danteTiming==="distance"?"Distance":fight.danteTiming.toUpperCase());
    var extras='<span class="my-method-pill" style="background:'+(methodOk?'#1c4532':'#742a2a')+';color:'+(methodOk?'#68d391':'#fc8181')+'">'+methods[fight.danteMethod]+'<span class="my-method-pts">'+(methodOk?'+'+previewMethodPts(fight.danteMethod)+'pt ✓':'0pt')+'</span></span>'
      +'<span class="extra-pill" style="background:'+(timingOk?'#1c4532':'#742a2a')+';color:'+(timingOk?'#68d391':'#fc8181')+'">'+timingLabel+' <span>'+(timingOk?'+'+previewTimingPts(fight,fight.danteTiming)+'pt ✓':'0pt')+'</span></span>'
      +'<span class="extra-pill" style="background:'+(ouOk?'#1c4532':'#742a2a')+';color:'+(ouOk?'#68d391':'#fc8181')+'">'+fight.danteOu.toUpperCase()+' '+fight.line+' Rounds <span>'+(ouOk?'+'+previewScoringRules.overUnderPts+'pt ✓':'0pt')+'</span></span>';
    var row='<div class="my-row"><div class="my-fight-wrap"><span class="my-fight">'+escapeHtml(fight.f1.split(" ").pop()+" vs "+fight.f2.split(" ").pop())+'</span>'+result+'<div class="fight-score-line"><span class="fight-score-pill '+(fightPts>0?'':'zero')+'">This fight +'+fightPts+' pt</span><span class="fight-score-pill">Total '+runningTotal+' pt</span></div></div><div class="my-right"><span class="my-tag combined-pick" style="background:'+bg+';color:'+col+'">'+(correct?'✓ ':'')+escapeHtml(name.split(" ").pop())+'<span class="my-tag-pts">'+(correct?'+'+previewSidePts(fight,side)+'pt ✓':'0pt')+'</span></span>'+extras+(fight.lock?'<span class="my-lock-line"><span class="my-lock-pill hit">Lock +'+previewLockPts()+'pt ✓</span></span>':'')+'</div></div>';
    var openByDefault=index<2||index===5||index===fights.length-1;
    return '<details class="my-pick-detail" '+(openByDefault?'open':'')+'><summary><span class="my-pick-title">'+escapeHtml(fight.f1.split(" ").pop()+" vs "+fight.f2.split(" ").pop())+'</span><span class="my-running-pill '+(fightPts>0?'':'zero')+'">'+runningTotal+' pt</span><span class="my-pick-chevron">▼</span></summary>'+row+'</details>';
  }).join('');
  target.innerHTML=previewPoolStripHtml()
    +'<div class="preview-tab-title">My Picks</div>'
    +'<div class="preview-panel-note">Finished-event preview: real UFC 328 results are shown from the first fight to the main event, with the running total building as each result comes in.</div>'
    +'<div class="my-banner plain-nameplate"><div class="my-champion-stack"><div class="my-sub">Dante</div></div><div class="my-score">'+finalTotal+'<span> pt</span></div></div>'
    +'<button class="summary-edit-btn" type="button">Edit Picks</button><div class="summary-edit-note">You can edit picks until the fights begin.</div>'
    +'<div class="my-official-wrap"><div class="my-official-head"><div class="my-official-title">Official Picks</div><div class="my-official-lock-reminder lock-hit"><span class="lock-label">Lock of the Night</span><span class="lock-name">Strickland</span></div><div class="my-official-actions"><button type="button" class="my-small-btn">Open All</button><button type="button" class="my-small-btn">Close All</button></div></div>'+details+'</div>';
  if(target.parentElement)target.parentElement.scrollTop=0;
}
function renderPreviewAllPicksPanel(){
  var target=document.getElementById("previewPicksScrollContent");
  if(!target)return;
  var rows=previewLeaderboardRows(), fights=previewUfc328Fights(), methods={ko:"KO/TKO",sub:"Sub",dec:"Decision"}, html=previewPoolStripHtml()
    +'<div class="preview-tab-title">All Picks</div>'
    +'<div class="preview-panel-note">This mirrors the real All Picks tab: each fight opens to show the leaderboard total after that fight, plus the winner, method, round, over/under, and lock details.</div>';
  function previewAllPickResult(fight,fightIndex,entry,entryIndex){
    return previewAllPickResultForEntry(fight,fightIndex,entry,entryIndex);
  }
  function previewAllPicksProgression(entry,entryIndex){
    var eventOrder=fights.slice().reverse();
    var raw=eventOrder.map(function(fight){
      return previewAllPickResult(fight,fights.indexOf(fight),entry,entryIndex).fightScore;
    });
    var running=0,totals={},gains={};
    eventOrder.forEach(function(fight,i){
      running+=raw[i];
      totals[fights.indexOf(fight)]=running;
      gains[fights.indexOf(fight)]=raw[i];
    });
    return {totals:totals,gains:gains};
  }
  fights.forEach(function(fight,orderIndex){
    var fightIndex=fights.indexOf(fight);
    var f1c=0,f2c=0,fightRows=[];
    rows.forEach(function(entry,entryIndex){
      var sourceIndex=typeof entry.sourceIndex==="number"?entry.sourceIndex:entryIndex;
      var pickData=previewAllPickResult(fight,fightIndex,entry,sourceIndex);
      if(pickData.side===1)f1c++;else f2c++;
      var progress=previewAllPicksProgression(entry,sourceIndex);
      var score=progress.totals[fightIndex]||0;
      var gain=progress.gains[fightIndex]||0;
      var previous=Math.max(0,score-gain);
      var scoreHtml='<div class="ap-score"><span class="ap-score-total">Total Points: '+score+' PT</span><span class="ap-score-breakdown">'+previous+' PT before + '+gain+' this fight = '+score+' PT</span></div>';
      fightRows.push({score:score,index:entryIndex,html:'<div class="ap-row plain-nameplate"><div><div class="ap-name">'+escapeHtml(entry.name)+'</div>'+scoreHtml+'</div><div class="ap-right"><div class="ap-pick"><span class="ap-tag combined-pick" style="background:'+pickData.bg+';color:'+pickData.col+'">'+(pickData.correct?'✓ ':'')+escapeHtml(pickData.selected.split(" ").pop())+'<span class="ap-tag-pts">'+(pickData.correct?'+'+previewSidePts(fight,pickData.side)+'pt ✓':'0pt')+'</span></span></div>'
        +'<div><span class="ap-method-pill" style="background:'+(pickData.methodOk?'#1c4532':'#742a2a')+';color:'+(pickData.methodOk?'#68d391':'#fc8181')+'">'+methods[pickData.method]+'<span class="ap-method-pts">'+(pickData.methodOk?'+'+previewMethodPts(pickData.method)+'pt ✓':'0pt')+'</span></span></div>'
        +'<div><span class="ap-method-pill" style="background:'+(pickData.timingOk?'#1c4532':'#742a2a')+';color:'+(pickData.timingOk?'#68d391':'#fc8181')+'">'+pickData.timingText+'<span class="ap-method-pts">'+(pickData.timingOk?'+'+previewTimingPts(fight,pickData.timingPick)+'pt ✓':'0pt')+'</span></span></div>'
        +'<div><span class="ap-method-pill" style="background:'+(pickData.ouOk?'#1c4532':'#742a2a')+';color:'+(pickData.ouOk?'#68d391':'#fc8181')+'">'+pickData.ouPick.toUpperCase()+' '+fight.line+'<span class="ap-method-pts">'+(pickData.ouOk?'+'+previewScoringRules.overUnderPts+'pt ✓':'0pt')+'</span></span></div>'
        +(pickData.isDante&&fight.lock?'<div class="ap-lock-line"><span class="ap-lock-pill '+(pickData.lockOk?'hit':'miss')+'">Lock '+(pickData.lockOk?'+'+previewLockPts()+'pt ✓':'0pt')+'</span></div>':'')
        +'</div></div>'});
    });
    var body=fightRows.sort(function(a,b){return b.score-a.score||a.index-b.index;}).map(function(row){return row.html;}).join('');
    html+='<div class="ap-block '+(orderIndex<2?'open':'')+'" id="preview_ap_'+orderIndex+'"><div class="ap-header" onclick="document.getElementById(\'preview_ap_'+orderIndex+'\').classList.toggle(\'open\')"><div><div class="ap-title">'+escapeHtml(fight.f1.split(" ").pop()+" vs "+fight.f2.split(" ").pop())+'</div><div class="ap-split">'+escapeHtml(fight.f1.split(" ").pop())+' '+f1c+' · '+escapeHtml(fight.f2.split(" ").pop())+' '+f2c+'</div></div><div style="display:flex;align-items:center;gap:8px"><span class="ap-result-label">RESULT</span><span style="color:#68d391;font-size:10px">✓ '+escapeHtml((fight.resultWinner===1?fight.f1:fight.f2).split(" ").pop())+' ('+(fight.resultWinner===1?f1c:f2c)+'/15)</span><span class="ap-chevron">▼</span></div></div><div class="ap-body">'+body+'</div></div>';
  });
  target.innerHTML=html;
  if(target.parentElement)target.parentElement.scrollTop=0;
}
