var currentPoolPreviewTab="picks";
window.setPoolPreviewTab=function(tab){
  currentPoolPreviewTab=tab||"picks";
  document.querySelectorAll(".preview-demo-tab").forEach(function(btn){
    btn.classList.toggle("active",btn.getAttribute("data-preview-tab")===currentPoolPreviewTab);
  });
  document.querySelectorAll(".preview-belt-tab,.preview-secondary-tab").forEach(function(btn){
    btn.classList.toggle("active",btn.getAttribute("data-preview-tab")===currentPoolPreviewTab);
  });
  renderPoolPreviewContent();
};
function renderPoolPreviewContent(){
  if(currentPoolPreviewTab==="leaderboard"){renderPreviewLeaderboardPanel();return;}
  if(currentPoolPreviewTab==="mine"){renderPreviewMyPicksPanel();return;}
  if(currentPoolPreviewTab==="all"){renderPreviewAllPicksPanel();return;}
  if(currentPoolPreviewTab!=="picks"){renderPreviewMiniPanel(currentPoolPreviewTab);return;}
  renderUfc328PreviewPicks();
}
function suggestSignInForKnownAccount(message){
  if(currentUser)return false;
  if(publicLanding&&!message)return false;
  var saved=readGlobalProfile();
  if(!(saved&&saved.email))return false;
  signInPromptShown=true;
  var emailEl=document.getElementById("signInEmailInput");
  if(emailEl&&!emailEl.value)emailEl.value=saved.email;
  showSignInMode();
  setSetupMessage(message||"Welcome back. Sign in to continue with your saved account.");
  return true;
}
function requireSignInOrAccountForPath(){
  var msg="Enter your password and sign in first to join a pool, create a pool, or open your saved pools.";
  if(suggestSignInForKnownAccount(msg)){
    setSetupMessage(msg,true);
    setMemberMessage(msg,true);
    return;
  }
  var signInEmail=document.getElementById("signInEmailInput");
  if(signInEmail&&signInEmail.value){
    showSignInMode();
    setSetupMessage(msg,true);
    setMemberMessage(msg,true);
    return;
  }
  showCreateAccountMode();
  setSetupMessage("Create an account first.",true);
  setMemberMessage("Create an account first.",true);
}
window.showCreateAccountMode=function(){
  var createMode=document.getElementById("createAccountMode");
  var signInMode=document.getElementById("signInMode");
  updateSignedInAccountCard(false);
  if(signInMode)signInMode.classList.add("auth-mode-hidden");
  if(createMode)createMode.classList.remove("auth-mode-hidden");
  setSetupMessage("");
  setCreateAccountBusy(false);
};
window.openPolicyModal=function(type){
  type=type==="privacy"?"privacy":"terms";
  var modal=document.getElementById("policyModal");
  var title=document.getElementById("policyModalTitle");
  var content=document.getElementById("policyModalContent");
  if(!modal||!title||!content)return;
  if(type==="privacy"){
    title.textContent="Privacy Policy";
    content.innerHTML='<p><strong>Last updated: June 2, 2026.</strong> This summary explains how Fight Locks handles account and pool information.</p>'
      +'<h3>Information We Use</h3><p>Fight Locks may store your name, username, email address, pool memberships, picks, results, leaderboard history, profile settings, and account activity needed to operate the site.</p>'
      +'<h3>How It Is Used</h3><p>We use this information to create accounts, let users join pools, save picks, display leaderboards, support pool admin tools, prevent duplicate usernames, and operate Fight Locks.</p>'
      +'<h3>What Fight Locks Does Not Do</h3><ul><li>Fight Locks does not process bets, wagers, prize pools, payouts, or entry-fee payments between users.</li><li>Fight Locks does not sell sportsbook services or hold user funds for contests.</li></ul>'
      +'<h3>Contact</h3><p>Questions can be sent to team@fight-locks.com.</p>';
  }else{
    title.textContent="Terms";
    content.innerHTML='<p><strong>Last updated: June 2, 2026.</strong> By creating or using a Fight Locks account, you agree to use the site responsibly and follow these terms.</p>'
      +'<h3>No Betting Or Wagering</h3><p>Fight Locks is a picks pool and leaderboard platform. Fight Locks is not a sportsbook, betting site, gambling operator, payment processor, escrow service, or prize provider.</p>'
      +'<h3>Hosts And Prizes</h3><p>Any private group arrangements, entry fees, prizes, promotions, or payouts are handled outside Fight Locks by the host, venue, or participants. Fight Locks does not collect, hold, manage, guarantee, or distribute those funds or prizes.</p>'
      +'<h3>User Responsibility</h3><ul><li>Use Fight Locks only where your use is allowed.</li><li>Do not use the platform for illegal gambling or unlawful activity.</li><li>Keep your account information accurate and do not impersonate other users.</li><li>Pool hosts are responsible for how they run their private pool and communicate with participants.</li></ul>'
      +'<h3>Platform Access</h3><p>Fight Locks may update, limit, suspend, or remove access when needed to protect the site, users, or launch operations.</p>';
  }
  modal.classList.add("show");
  modal.setAttribute("aria-hidden","false");
};
window.closePolicyModal=function(){
  var modal=document.getElementById("policyModal");
  if(!modal)return;
  modal.classList.remove("show");
  modal.setAttribute("aria-hidden","true");
};
document.addEventListener("click",function(e){
  var modal=document.getElementById("policyModal");
  if(modal&&e.target===modal)closePolicyModal();
});
document.addEventListener("keydown",function(e){
  if(e.key==="Escape")closePolicyModal();
});
function handleAuthModeSwitch(e){
    var btn=e.target&&e.target.closest&&e.target.closest("#showSignInModeBtn,#showCreateAccountModeBtn,#signInAccountBtn,#signInForgotPasswordBtn");
    if(!btn)return;
    if(btn.id==="showSignInModeBtn")window.showSignInMode();
    else if(btn.id==="showCreateAccountModeBtn")window.showCreateAccountMode();
    else if(btn.id==="signInAccountBtn"){
      if(typeof window.signInExistingAccount==="function")window.signInExistingAccount();
      else setSetupMessage("Sign in is still loading. Refresh the page and try again.",true);
    }
    else if(btn.id==="signInForgotPasswordBtn"){
      if(typeof window.sendPasswordResetFromSignIn==="function")window.sendPasswordResetFromSignIn();
      else setSetupMessage("Password reset is still loading. Refresh the page and try again.",true);
    }
    e.preventDefault();
  e.stopPropagation();
  if(e.stopImmediatePropagation)e.stopImmediatePropagation();
}
