async function sendPasswordResetForEmail(email,msg){
  email=String(email||"").trim().toLowerCase();
  if(localDemoMode){if(msg)msg.textContent="Demo mode: Firebase password reset is disabled.";return;}
  if(!validEmail(email)){if(msg)msg.textContent="Enter the email for your account first.";return;}
  if(msg){msg.classList.remove("good");msg.textContent="Sending password reset email...";}
  try{
    await sendPasswordResetEmail(auth,email);
    showTemporaryMessage(msg,"Password reset email sent to "+email+". Check your inbox and spam folder.",true,180000);
  }catch(e){
    console.error(e);
    var code=e&&e.code?e.code:"";
    if(!msg)return;
    if(code==="auth/user-not-found")msg.textContent="No account was found with that email.";
    else if(code==="auth/invalid-email")msg.textContent="That email does not look valid.";
    else if(code==="auth/network-request-failed")msg.textContent="Could not reach Firebase right now. Check the connection and try again.";
    else msg.textContent="Could not send the reset email. Try again in a minute.";
  }
}
window.sendPasswordResetFromSignIn=function(){
  var email=(document.getElementById("signInEmailInput")&&document.getElementById("signInEmailInput").value||"").trim().toLowerCase();
  sendPasswordResetForEmail(email,document.getElementById("setupStatus"));
};
window.sendPasswordResetFromProfile=async function(){
  if(currentUser&&typeof currentUser.reload==="function"){
    try{await currentUser.reload();}catch(e){}
  }
  var email=((currentUser&&currentUser.email)||(document.getElementById("profileEmailInput")&&document.getElementById("profileEmailInput").value)||(currentMember&&currentMember.email)||"").trim().toLowerCase();
  var profileEmail=document.getElementById("profileEmailInput");
  if(profileEmail&&currentUser&&currentUser.email)profileEmail.value=currentUser.email;
  sendPasswordResetForEmail(email,document.getElementById("passwordMsg"));
};
function validateCreateAccountFields(profileInputs,messageFn){
  messageFn=messageFn||setSetupMessage;
  if(!profileInputs.firstName){messageFn("Add your first name before creating an account.",true);return false;}
  if(!profileInputs.lastName){messageFn("Add your last name before creating an account.",true);return false;}
  if(!profileInputs.username){messageFn("Add a username before creating an account.",true);return false;}
  if(profileInputs.usernameHadSpaces){messageFn("Username cannot include spaces.",true);return false;}
  if(profileInputs.username.length<2){messageFn("Username needs at least 2 characters.",true);return false;}
  if(!profileInputs.email){messageFn("Add your email before creating an account.",true);return false;}
  if(!validEmail(profileInputs.email)){messageFn("Enter a real email address, like name@example.com.",true);return false;}
  if(!currentUser&&!profileInputs.password){messageFn("Create a password before creating an account.",true);return false;}
  if(!currentUser&&validAccountPasswordReason(profileInputs.password)){messageFn(validAccountPasswordReason(profileInputs.password),true);return false;}
  if(!currentUser&&!profileInputs.termsAccepted){messageFn("Agree to the Terms and Privacy Policy before creating an account.",true);return false;}
  return true;
}
window.signInExistingAccount=async function(){
  if(accountSignInBusy)return;
  if(localDemoMode){setSetupMessage("Demo mode uses a local sample profile. Firebase sign-in is disabled.",true);setMemberMessage("Demo mode uses a local sample profile. Firebase sign-in is disabled.",true);return;}
  signedOutOnPurpose=false;
  forceNewProfileResetPending=false;
  publicLandingAuthIntent=true;
  var profileInputs=getSignInInputs();
  signInPromptShown=true;
  if(!validEmail(profileInputs.email)){setSetupMessage("Enter the email for the account you already created.",true);setMemberMessage("Enter your account email first.",true);return;}
  if(!profileInputs.password){setSetupMessage("Enter the password for that account.",true);setMemberMessage("Enter your password first.",true);return;}
  setSetupMessage("Signing in...");
  setMemberMessage("Signing in...");
  setSignInBusy(true);
  var stillTryingTimer=showFirebaseStillTrying("signing in",12000);
  try{
	    await withFirebaseTimeout(setPersistence(auth,browserLocalPersistence),"preparing sign in",20000);
	    var result=await withFirebaseTimeout(signInWithEmailAndPassword(auth,profileInputs.email,profileInputs.password),"signing in",45000);
	    currentUser=result.user;
      clearManualPoolOpen();
      clearStaleActiveProfile(currentUser);
	    trackCreatorEvent("login",{uid:currentUser.uid,email:currentUser.email||profileInputs.email,poolId:currentPoolId});
	    await hydrateProfileFromAccount(currentUser);
    syncInvitedPoolAccessAfterLogin();
    if(!currentUser.emailVerified){
      await requireVerifiedEmailForPath();
      return;
    }
    if(!profileHasJoinIdentity(currentMember)){
      promptForMissingProfileName("Signed in. Add the name friends should see, then tap Save Profile.");
      setMemberMessage("Finish your profile by adding the name friends should see.");
      return;
    }
    if(isCommunityJoinFlowActive()){
      keepCommunityJoinReady("Signed in. Tap Join Freedom 250 Pool to enter the community pool.");
      setMemberMessage("Signed in. Tap Join Freedom 250 Pool to enter the community pool.");
      return;
    }
    routePostLoginToMyPools("Signed in. Choose a pool to enter, join a pool, or start a pool.");
    setMemberMessage("Signed in. Loading your pools.");
  }catch(e){
    setSetupMessage(authFriendlyError(e),true);
    setMemberMessage(authFriendlyError(e),true);
  }finally{
    clearTimeout(stillTryingTimer);
    setSignInBusy(false);
  }
};
window.signOutAccount=async function(){
  signedOutOnPurpose=true;
  signInPromptShown=false;
  clearManualPoolOpen();
  if(!localDemoMode)await signOut(auth);
  currentUser=null;currentMember=null;currentMemberId=null;currentAdminKey="";adminKeyUnlocked=false;currentAccountData={};accountNeedsPoolChoice=true;myDocId=null;myEntry=null;
  try{localStorage.removeItem(memberStorageKey("profile"));localStorage.removeItem(memberStorageKey("id"));localStorage.removeItem(globalProfileKey());localStorage.removeItem(poolStorageKey("myDocId"));}catch(e){}
  setSetupMessage("Signed out.");
  setMemberMessage("Signed out.");
  renderMemberGate();
  routeSignedOutToStart("Signed out.");
};
