    var email=(currentUser&&currentUser.email)||(currentMember&&currentMember.email)||"";
    var docIds=[uid,myDocId,currentMember&&currentMember.memberId,currentMember&&currentMember.authUid].filter(Boolean).map(String);
    await removeCurrentUserFromPool(currentPoolId);
    myDocId=null;myEntry=null;allEntries=allEntries.filter(function(e){return docIds.indexOf(String(e.docId||""))<0&&String(e.email||"").toLowerCase()!==String(email||"").toLowerCase();});
    try{localStorage.removeItem(poolStorageKey("myDocId"));localStorage.removeItem(memberStorageKey("profile"));localStorage.removeItem(memberStorageKey("id"));}catch(e){}
    currentMember=null;currentMemberId=null;adminKeyUnlocked=false;currentAdminKey="";accountNeedsPoolChoice=true;
