window.createAccountOnly=async function(){
  if(localDemoMode){setSetupMessage("Demo mode uses local sample data. Firebase account creation is disabled.",true);return;}
  if(accountCreateBusy)return;
  signedOutOnPurpose=false;
  forceNewProfileResetPending=false;
  publicLandingAuthIntent=true;
  if(isFilePreview()){
    accountNeedsPoolChoice=true;
    renderMemberGate();
    setSetupMessage("Account creation only works from the local preview. Open "+localPreviewUrl()+" and create your account there.",true);
    return;
  }
  var profileInputs=getProfileInputs();
  if(!validateCreateAccountFields(profileInputs,setSetupMessage)){
    accountNeedsPoolChoice=true;
    markSetupPathReady(false);
    renderMemberGate();
    return;
  }
  if(currentUser&&profileHasFullName(currentMember)){
    setSetupMessage("You're already signed in as "+(currentUser.email||"this account")+". Sign out before creating a different account.",true);
    setMemberMessage("Sign out before creating a different account.",true);
    return;
  }
  if(currentUser&&currentUser.email&&currentUser.email.toLowerCase()!==profileInputs.email.toLowerCase()){
    setSetupMessage("You're already signed in as "+currentUser.email+". Use Sign Out first if you want to create a different account.",true);
    setMemberMessage("Use Sign Out first before creating a different account.",true);
    return;
  }
  accountNeedsPoolChoice=true;
  setCreateAccountBusy(true);
  setSetupMessage("Creating account...");
  try{
    var profile=await saveAccountProfile(profileInputs,setSetupMessage,{joinPool:false});
    if(!profile){
      accountNeedsPoolChoice=true;
      markSetupPathReady(false);
      renderMemberGate();
      return;
    }
    if(currentUser&&!currentUser.emailVerified){
      try{await sendAccountVerificationEmail(false);}catch(e){console.warn("Could not send verification email",e);}
      markSetupPathReady(false);
      setEmailVerifyPanel(true,currentUser.email||profileInputs.email);
      setSetupMessage(emailVerificationSetupMessage(currentUser.email||profileInputs.email));
      setMemberMessage("Verify your email to finish choosing a pool.");
      renderMemberGate();
      return;
    }
    markSetupPathReady(true);
    setEmailVerifyPanel(false);
    if(isCommunityJoinFlowActive()){
      keepCommunityJoinReady(accountSyncPending?localAccountCreatedMessage():accountCreatedMessage());
      return;
    }
    setSetupMessage(accountSyncPending?localAccountCreatedMessage():accountCreatedMessage());
    renderMemberGate();
    if(typeof showMyPoolsView==="function")showMyPoolsView();
  }finally{
    setCreateAccountBusy(false);
  }
};
