window.saveProfileEdits=async function(options){
  options=options||{};
  var msg=document.getElementById("profileMsg");
  clearTimeout(msg&&msg.__flClearTimer);
  if(msg)msg.classList.remove("good");
  if(!currentMember){if(msg)msg.textContent="Create or sign in to your account first.";return;}
  if(localDemoMode){showTemporaryMessage(msg,"Demo mode: profile edits preview locally only. Firebase save disabled.",true,180000);return;}
  var first=cleanUsername(document.getElementById("profileFirstNameInput")&&document.getElementById("profileFirstNameInput").value);
  var last=currentMember&&currentMember.lastName||"";
  var profileUsernameRaw=document.getElementById("profileUsernameInput")&&document.getElementById("profileUsernameInput").value;
  var username=cleanUsernameHandle(profileUsernameRaw);
  var email=(preferredProfileEmail(currentMember)||(document.getElementById("profileEmailInput")&&document.getElementById("profileEmailInput").value)||"").trim().toLowerCase();
  var profileEmailInput=document.getElementById("profileEmailInput");
  if(profileEmailInput)profileEmailInput.value=email;
  if(usernameHasInvalidSpacing(profileUsernameRaw)){if(msg)msg.textContent="Username cannot include spaces.";return;}
  if(username.length<2){if(msg)msg.textContent="Username needs at least 2 characters.";return;}
  if(!validEmail(email)){if(msg)msg.textContent="Enter a real email address.";return;}
  var oldUsername=currentMember.username||currentMember.name||"";
  var usernameChanged=usernameKey(username)!==usernameKey(oldUsername);
  if(usernameChanged){
    if(!shouldUseLocalFightLocksPreviewProfile()&&!(await usernameAvailableOrMessage(username,(currentUser&&currentUser.uid)||(currentMember&&currentMember.authUid)||(currentMember&&currentMember.memberId),function(text,bad){if(msg){msg.classList.toggle("good",!bad);msg.textContent=text;}})))return;
    if(!options.confirmedUsername||usernameKey(options.confirmedUsernameValue||"")!==usernameKey(username)){
      window.__pendingProfileUsernameChange=username;
      setProfileUsernameConfirm(true,oldUsername,username);
      if(msg){msg.classList.remove("good");msg.textContent="Confirm this username change before it is saved.";}
      return;
    }
  }
  setProfileUsernameConfirm(false);
  var now=new Date().toISOString();
  var fullName=cleanFullName((first||currentMember.firstName||"")+" "+(last||""))||currentMember.fullName||username;
  var profile=Object.assign({},currentMember,{firstName:first,lastName:last,fullName:fullName,username:username,usernameKey:usernameKey(username),name:username,email:email,updatedAt:now});
  var stamp=new Date().toLocaleTimeString([], {hour:"numeric",minute:"2-digit"});
  try{
    await persistAccountProfile(profile,{joinPool:currentPoolMemberApproved||isPoolAdmin()});
    storeMemberProfile(profile);
    applyMemberProfileToPage();
    if(myEntry&&myDocId){
      myEntry=Object.assign({},myEntry,{name:username,email:email,updatedAt:now});
      await setDoc(poolDoc("entries",myDocId),myEntry,{merge:true});
    }
    showTemporaryMessage(msg,"Profile updated at "+stamp+".",true,180000);
    renderLeaderboard();renderAllPicks();renderMySummary();updateChatIdentity();
  }catch(e){console.error(e);showTemporaryMessage(msg,authFriendlyError(e)||"Could not save that username. Try another one.",false,180000);}
};
window.changeMyPassword=async function(){
	  var msg=document.getElementById("passwordMsg");
	  if(localDemoMode){if(msg)msg.textContent="Demo mode: Firebase password changes are disabled.";return;}
	  if(msg)msg.classList.remove("good");
	  var current=removeCredentialSpaces(document.getElementById("profileCurrentPasswordInput")&&document.getElementById("profileCurrentPasswordInput").value);
	  var next=removeCredentialSpaces(document.getElementById("profileNewPasswordInput")&&document.getElementById("profileNewPasswordInput").value);
	  var confirm=removeCredentialSpaces(document.getElementById("profileConfirmPasswordInput")&&document.getElementById("profileConfirmPasswordInput").value);
	  if(!current){if(msg)msg.textContent="Enter your current password first.";return;}
	  var accountPasswordReason=validAccountPasswordReason(next);
	  if(accountPasswordReason){if(msg)msg.textContent=accountPasswordReason;return;}
	  if(next!==confirm){if(msg)msg.textContent="New passwords do not match.";return;}
	  var email=(currentUser&&currentUser.email)||(document.getElementById("profileEmailInput")&&document.getElementById("profileEmailInput").value)||(currentMember&&currentMember.email)||"";
	  email=String(email||"").trim().toLowerCase();
	  if(!validEmail(email)){if(msg)msg.textContent="Add your account email in My Profile first.";return;}
	  if(msg)msg.textContent="Updating password...";
	  try{
	    if(!currentUser||!currentUser.email){
	      var signedIn=await signInWithEmailAndPassword(auth,email,current);
	      currentUser=signedIn.user;
	      await hydrateProfileFromAccount(currentUser);
	    }
	    var credential=EmailAuthProvider.credential(email,current);
	    await reauthenticateWithCredential(currentUser,credential);
	    await updatePassword(currentUser,next);
	    ["profileCurrentPasswordInput","profileNewPasswordInput","profileConfirmPasswordInput"].forEach(function(id){var el=document.getElementById(id);if(el)el.value="";});
	    var stamp=new Date().toLocaleTimeString([], {hour:"numeric",minute:"2-digit"});
	    showTemporaryMessage(msg,"Password updated at "+stamp+".",true,180000);
	    setMemberMessage("Password updated.");
	  }catch(e){
    console.error(e);
    var code=e&&e.code?e.code:"";
    if(!msg)return;
    if(code==="auth/wrong-password"||code==="auth/invalid-credential")msg.textContent="Current password is not correct.";
    else if(code==="auth/weak-password")msg.textContent="New password needs at least 8 characters.";
	    else if(code==="auth/requires-recent-login")msg.textContent="For security, enter your current password again and tap Update Password.";
    else if(code==="auth/network-request-failed")msg.textContent="Could not reach Firebase right now. Check the connection and try again.";
    else msg.textContent="Password could not be updated. Try signing in again first.";
  }
};
async function saveAccountProfile(profileInputs,messageFn,options){
  var fullName=profileInputs.fullName;
  var username=profileInputs.username;
  var email=profileInputs.email;
  options=options||{};
  messageFn=messageFn||setSetupMessage;
  if(!profileInputs.firstName){messageFn("Add your first name.",true);return null;}
  if(!profileInputs.lastName){messageFn("Add your last name.",true);return null;}
  if(username.length<2){messageFn("Add the username friends should see.",true);return null;}
  if(!validEmail(email)){messageFn("Add a real email address.",true);return null;}
  var activeUid=(currentUser&&currentUser.uid)||(currentMember&&currentMember.authUid)||(currentMember&&currentMember.memberId);
  if(!(await usernameAvailableOrMessage(username,activeUid,messageFn)))return null;
  var user=await ensureAuthAccount(username,email,profileInputs.password);
  if(!user){
    if(isFirebaseReachabilityError(lastAuthError)){
      var localProfile=makeLocalAccountProfile(profileInputs);
      accountSyncPending=true;
      storeMemberProfile(localProfile);
      applyMemberProfileToPage();
      setMemberMessage("Profile saved on this device. Firebase sync is pending.");
      return localProfile;
    }
    return null;
  }
  accountSyncPending=false;
  var existing=user.uid;
  if(!existing){try{existing=localStorage.getItem(memberStorageKey("id"))||null;}catch(e){}}
  var now=new Date().toISOString();
  var profile={memberId:existing||makeMemberId(email),authUid:user.uid,poolId:currentPoolId,firstName:profileInputs.firstName,lastName:profileInputs.lastName,fullName:fullName,username:username,usernameKey:usernameKey(username),name:username,email:email,updatedAt:now};
  if(profileInputs.termsAccepted){
    profile.acceptedTermsAt=now;
    profile.acceptedTermsVersion=FIGHT_LOCKS_TERMS_VERSION;
    profile.acknowledgedNoBetting=true;
  }
  if(!(currentMember&&currentMember.createdAt))profile.createdAt=now;else profile.createdAt=currentMember.createdAt;
  try{
    await persistAccountProfile(profile,options);
    storeMemberProfile(profile);
    applyMemberProfileToPage();
  }catch(e){
    if(isFirebaseReachabilityError(e)){
      console.warn("Member profile saved locally; Firebase sync pending",e);
      profile.localOnly=true;
      profile.syncPending=true;
      accountSyncPending=true;
      storeMemberProfile(profile);
      applyMemberProfileToPage();
      setMemberMessage("Profile saved on this device. Firebase sync is pending.");
      return profile;
    }
    console.warn("Member profile was not saved",e);
    messageFn(profileSaveFriendlyError(e),true);
    setMemberMessage(profileSaveFriendlyError(e),true);
    return null;
  }
  return profile;
}
async function saveSetupProfileOnly(){
  var profileInputs=getProfileInputs();
  return saveAccountProfile(profileInputs,setSetupMessage,{joinPool:false});
}
window.completeProfileSetup=async function(action){
  if(localDemoMode){
    setSetupMessage("Demo mode uses local sample pool data. Firebase create and join actions are disabled.",true);
    setMemberMessage("Demo mode uses local sample pool data. Firebase create and join actions are disabled.",true);
    renderLocalDemoModeLabel();
    return;
  }
  if(!currentUser&&!currentMember){
    markSetupPathReady(false);
    requireSignInOrAccountForPath();
    return;
  }
  if(currentUser&&!(await requireVerifiedEmailForPath()))return;
  var hasSavedProfile=action==="create"
    ? !!(currentMember&&currentMember.name&&currentMember.email&&profileHasFullName(currentMember))
    : !!(currentUser&&profileHasJoinIdentity(profileForSignedInJoin()))||!!(currentMember&&profileHasJoinIdentity(currentMember));
  setSetupMessage(hasSavedProfile?"Checking pool access...":"Saving profile...");
  var profile=hasSavedProfile?(action==="create"?currentMember:profileForSignedInJoin()):await saveSetupProfileOnly();
  if(!profile)return;
  if(action==="create"&&!profileHasFullName(profile)){
    promptForMissingProfileName("Add your first and last name before choosing a pool.");
    return;
  }
  if(action==="create"){
    if(!currentUser){
      setSetupMessage("Firebase needs to be connected before you can host a new pool as admin. You can still join the invited pool now.",true);
      markSetupPathReady(true);
      return;
    }
    var planType=normalizeStartPoolPlan(window.selectedStartPoolPlan);
    if(!planType){
      setSetupMessage("Choose a pool type before continuing.",true);
      if(typeof continueStartPoolPlan==="function")continueStartPoolPlan();
      return;
    }
    accountNeedsPoolChoice=false;
    markSetupPathReady(false);
    if(isPaidStartPoolPlan(planType)){
      if(!selectedStartPoolEventIds(planType==="single_event").length){
        setSetupMessage("Choose an event with fighters loaded before checkout.",true);
        return;
      }
      var poolName=document.getElementById("setupNewPoolName");
      var codeInput=document.getElementById("setupNewPoolCode");
      var typedName=(poolName&&poolName.value||"").trim();
      if(!typedName){setSetupMessage("Name your pool first.",true);return;}
      var requestedCode=poolPasscode(codeInput&&codeInput.value);
      var passcodeReason=weakPoolPasscodeReason(requestedCode);
      if(passcodeReason){setSetupMessage(passcodeReason,true);return;}
      showStartPoolCheckoutReview(typedName,requestedCode);
      setSetupMessage("Review checkout details before payment. Your pool will be created after checkout succeeds.");
      return;
    }
    await createStartPoolFromSetup(profile,planType);
    return;
  }
		  if(action==="code"){
		    var codeEl=document.getElementById("setupJoinPoolCode");
		    var passEl=document.getElementById("setupJoinPoolPasscode");
		    var lockedCommunityJoin=!!(codeEl&&passEl&&codeEl.readOnly&&passEl.readOnly&&codeEl.classList.contains("community-join-locked")&&passEl.classList.contains("community-join-locked"));
		    var code=(lockedCommunityJoin||isCommunityJoinFlowActive())?await resolveFreedom250CommunityPoolId():await resolvePoolCode(codeEl&&codeEl.value,passEl&&passEl.value);
		    if(!code){
		      accountNeedsPoolChoice=true;
		      markSetupPathReady(true);
		      setSetupMessage("Pool name code or passcode does not match. Check both and try again.",true);
		      return;
		    }
		    setSetupMessage("Joining pool...");
		    try{
		      if(!(await requestJoinApproval(code,profile,"code")))return;
		    }catch(e){console.error(e);setSetupMessage("Could not join that pool. Try again.",true);return;}
	    trackCreatorEvent("pool_joined_by_code",{poolId:code,poolName:displayPoolName(code),uid:currentUser&&currentUser.uid,email:currentMember&&currentMember.email,name:currentMember&&currentMember.name});
	    setSetupMessage("You're in. Make your picks when you're ready.");
	    if(code!==currentPoolId){window.location.href=poolInviteUrl(code).replace(/#.*/,"")+"#picks";return;}
	    openJoinedPoolAfterJoin(code);
	    return;
	  }
  setSetupMessage("Joining pool...");
  if(!invitedPoolId){setSetupMessage("Choose or create a pool first.",true);return;}
		  try{
		    if(!(await requestJoinApproval(currentPoolId,profile,"invite")))return;
		  }catch(e){console.error(e);setSetupMessage("Could not join that pool. Try again.",true);return;}
	  trackCreatorEvent("pool_joined_from_invite",{poolId:currentPoolId,poolName:displayPoolName(currentPoolId),uid:currentUser&&currentUser.uid,email:currentMember&&currentMember.email,name:currentMember&&currentMember.name});
	  setSetupMessage("You're in. Make your picks when you're ready.");
	  openJoinedPoolAfterJoin(currentPoolId);
};
async function ensurePoolMeta(){
  if(godModeRequested)return;
  if(cleanFirstVisit)return;
  function metadataPatchFor(existing,intended){
    var patch={};
    Object.keys(intended||{}).forEach(function(key){
      var next=intended[key];
      if(next===undefined)return;
      var prev=existing&&existing[key];
      if(String(prev==null?"":prev)!==String(next==null?"":next))patch[key]=next;
    });
    return patch;
  }
  function hasMetadataPatch(patch){return Object.keys(patch||{}).length>0;}
  try{
    var deleted=await getDoc(doc(db,"deletedPools",currentPoolId));
    if(deleted.exists()){handleDeletedPool(deleted.data()||{});return;}
  }catch(e){console.warn("Could not check deleted pool marker",e);}
  try{
    var poolSnap=await getDoc(poolRootDoc());
    if(invitedPoolId&&!poolSnap.exists()){
      currentPoolExists=false;
      currentPoolChecked=true;
      currentPoolMeta={};
      adminKeyUnlocked=false;
      currentAdminKey="";
      accountNeedsPoolChoice=true;
      markSetupPathReady(true);
      setSetupMessage(missingPoolMessage(),true);
      routeDebugState({functionName:"ensurePoolMeta",reason:"invited-pool-missing"});
      renderMemberGate();
      return;
    }
    currentPoolExists=poolSnap.exists();
    currentPoolChecked=true;
    var poolData=poolSnap.exists()?poolSnap.data()||{}:{};
    if(shouldUseLocalHostedPreviewProfile()&&!getPoolPlanType(poolData))poolData=Object.assign({},localHostedPreviewPoolMeta(),poolData);
    currentPoolMeta=Object.assign({},currentPoolMeta,poolData);
    if(poolData.entryFee!==undefined){
      var poolEntryFee=parseInt(poolData.entryFee);
      if(!isNaN(poolEntryFee)&&poolEntryFee>=0)applyEntryFee(poolEntryFee,false);
    }
    var savedPoolCode=normalizePoolCode(poolData.poolCode);
    var currentIdCode=normalizePoolCode(currentPoolId);
    var poolCode=isPoolNameCode(currentIdCode)?currentIdCode:(isPoolNameCode(savedPoolCode)?savedPoolCode:await uniquePoolCode(poolData.poolName||displayPoolName(currentPoolId)||currentPoolId));
    var existingKey=activeAdminKey();
    var rawExistingCode=poolPasscode(poolData.joinCode);
    var existingCode=joinPasscodeLooksGenerated(rawExistingCode,poolCode,currentPoolId)?"":rawExistingCode;
    var event=getCurrentPoolEvent(poolData);
    var meta={poolId:currentPoolId,poolCode:poolCode,eventId:event.eventId,eventName:event.eventName,eventLabel:event.eventLabel,eventStatus:event.eventStatus,poolName:displayPoolName(currentPoolId),inviteUrl:poolJoinUrl(currentPoolId,true)};
    if(existingCode)meta.joinCode=existingCode;
    if(existingKey)meta.adminKey=existingKey;
    var now=new Date().toISOString();
    var rootPatch=metadataPatchFor(poolData,meta);
    if(hasMetadataPatch(rootPatch)){
      rootPatch.updatedAt=now;
      await setDoc(poolRootDoc(),rootPatch,{merge:true});
    }
    try{
      var legacyMetaSnap=await getDoc(poolDoc("_meta","info"));
      var legacyMetaData=legacyMetaSnap.exists()?legacyMetaSnap.data()||{}:{};
      var legacyPatch=metadataPatchFor(legacyMetaData,meta);
      if(hasMetadataPatch(legacyPatch)){
        legacyPatch.updatedAt=now;
        await setDoc(poolDoc("_meta","info"),legacyPatch,{merge:true});
      }
    }catch(metaErr){console.warn("Could not repair pool metadata mirror",metaErr);}
    try{
      var codeRef=doc(db,"poolCodes",poolCode);
      var codeSnap=await getDoc(codeRef);
      var codeData=codeSnap.exists()?codeSnap.data()||{}:{};
      var codePatch=metadataPatchFor(codeData,{code:poolCode,poolId:currentPoolId,poolName:meta.poolName});
      if(hasMetadataPatch(codePatch)){
        codePatch.updatedAt=now;
        await setDoc(codeRef,codePatch,{merge:true});
      }
    }catch(codeErr){console.warn("Could not repair pool code metadata",codeErr);}
    [savedPoolCode].filter(Boolean).forEach(function(oldCode){
      oldCode=normalizePoolCode(oldCode);
      if(oldCode&&oldCode!==poolCode&&!isReservedPoolCodeAlias(oldCode))deleteDoc(doc(db,"poolCodes",oldCode)).catch(function(){});
    });
    currentPoolMeta=Object.assign({},currentPoolMeta,meta);
    routeDebugState({functionName:"ensurePoolMeta",reason:"pool-meta-loaded"});
    renderPoolShell();
  }catch(e){console.warn("Pool meta not saved",e);}
}
