window.sharePoolInvite=async function(){
  var msg=document.getElementById(arguments[0]||"poolMsg");
  var url=isFreedom250CommunityPool()?communityPoolInviteUrl(currentPoolId,true):poolJoinUrl(currentPoolCode(),true);
  var title=displayPoolName(currentPoolId)+" Fight Locks pool";
  var text=inviteShareText();
  if(navigator.share){
    try{
      await navigator.share({title:title,text:text,url:url});
      showTemporaryMessage(msg,"Invite ready to send.",true,180000);
      return;
    }catch(e){
      if(e&&e.name==="AbortError"){if(msg)msg.textContent="Share canceled. Your invite link is still ready.";return;}
    }
  }
  try{
    await navigator.clipboard.writeText(text+" "+url);
    showTemporaryMessage(msg,"Share is not available in this browser, so the invite was copied. Paste it into a text or iMessage.",true,180000);
  }catch(e){
    if(msg)msg.textContent=text+" "+url;
  }
};
window.sendPoolInviteEmail=async function(){
  var input=document.getElementById(arguments[0]||"poolInviteEmail"), msg=document.getElementById(arguments[1]||"poolMsg");
  var email=(input&&input.value||"").trim().toLowerCase();
  var url=isFreedom250CommunityPool()?communityPoolInviteUrl(currentPoolId,true):poolJoinUrl(currentPoolCode(),true);
  if(!validEmail(email)){if(msg)msg.textContent="Enter your friend's email first.";return;}
  var payload={to:email,poolName:displayPoolName(currentPoolId),inviteUrl:url,hostName:(currentMember&&currentMember.name)||"A Fight Locks host"};
  if(msg)msg.textContent="Sending invite...";
  try{
    var res=await fetch("/.netlify/functions/send-invite",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});
    if(!res.ok)throw new Error(await res.text()||"Invite function unavailable");
    var stamp=new Date().toLocaleTimeString([], {hour:"numeric",minute:"2-digit"});
    showTemporaryMessage(msg,"Invite email sent to "+email+" at "+stamp+".",true,180000);
    if(input)input.value="";
  }catch(e){
    console.warn("Invite email was not sent automatically",e);
    var subject="Join my Fight Locks pool";
    var body=inviteShareText()+"\n\n"+url;
    try{await navigator.clipboard.writeText(body);}catch(err){}
    try{window.location.href="mailto:"+encodeURIComponent(email)+"?subject="+encodeURIComponent(subject)+"&body="+encodeURIComponent(body);}catch(err2){}
    if(location.hostname==="127.0.0.1"||location.hostname==="localhost"){
      if(msg)msg.textContent="Invite email could not be sent from this preview. The invite link was copied, and your email app was opened with the message ready.";
    }else{
      if(msg)msg.textContent="Invite email did not send. The invite link was copied so you can still send it.";
    }
  }
};
