async function updateSavedPoolMetadataForEveryone(poolName,joinCode,poolCode){
  try{
    var snap=await getDocs(collection(db,"users"));
    await Promise.all(snap.docs.map(function(d){
      var data=d.data()||{}, patch={updatedAt:new Date().toISOString()};
      var changed=false;
      if(data.joinedPools&&data.joinedPools[currentPoolId]){
        patch["joinedPools."+currentPoolId+".poolName"]=poolName;
        patch["joinedPools."+currentPoolId+".joinCode"]=joinCode;
        patch["joinedPools."+currentPoolId+".poolCode"]=poolCode;
        changed=true;
      }
      if(data.hostedPools&&data.hostedPools[currentPoolId]){
        patch["hostedPools."+currentPoolId+".poolName"]=poolName;
        patch["hostedPools."+currentPoolId+".joinCode"]=joinCode;
        patch["hostedPools."+currentPoolId+".poolCode"]=poolCode;
        changed=true;
      }
      if(data.lastPoolAction&&data.lastPoolAction.poolId===currentPoolId){
        patch["lastPoolAction.poolName"]=poolName;
        patch["lastPoolAction.joinCode"]=joinCode;
        patch["lastPoolAction.poolCode"]=poolCode;
        changed=true;
      }
      return changed?updateDoc(d.ref,patch).catch(function(e){console.warn("Could not update saved pool name",e);}):Promise.resolve();
    }));
  }catch(e){console.warn("Could not update saved pool names",e);}
}
async function updateSavedPoolNamesForEveryone(poolName){
  return updateSavedPoolMetadataForEveryone(poolName,currentJoinCode(),currentPoolCode());
}
async function updateSavedPoolEventForEveryone(event,statusLabel){
  try{
    var eventName=(event&&((event.eventName||event.eventLabel)))||"";
    var status=statusLabel||eventStatusDisplay((event&&event.eventStatus)||"open_for_picks");
    var now=new Date().toISOString();
    var snap=await getDocs(collection(db,"users"));
    await Promise.all(snap.docs.map(function(d){
      var data=d.data()||{}, patch={updatedAt:now}, changed=false;
      if(data.joinedPools&&data.joinedPools[currentPoolId]){
        patch["joinedPools."+currentPoolId+".eventId"]=event.eventId||"";
        patch["joinedPools."+currentPoolId+".eventName"]=eventName;
        patch["joinedPools."+currentPoolId+".poolEventStatus"]=status;
        patch["joinedPools."+currentPoolId+".updatedAt"]=now;
        changed=true;
      }
      if(data.hostedPools&&data.hostedPools[currentPoolId]){
        patch["hostedPools."+currentPoolId+".eventId"]=event.eventId||"";
        patch["hostedPools."+currentPoolId+".eventName"]=eventName;
        patch["hostedPools."+currentPoolId+".poolEventStatus"]=status;
        patch["hostedPools."+currentPoolId+".updatedAt"]=now;
        changed=true;
      }
      if(data.lastPoolAction&&data.lastPoolAction.poolId===currentPoolId){
        patch["lastPoolAction.eventId"]=event.eventId||"";
        patch["lastPoolAction.eventName"]=eventName;
        patch["lastPoolAction.poolEventStatus"]=status;
        changed=true;
      }
      return changed?updateDoc(d.ref,patch).catch(function(e){console.warn("Could not update saved pool event",e);}):Promise.resolve();
    }));
  }catch(e){console.warn("Could not update saved pool event metadata",e);}
}
window.savePoolName=async function(msgId){
  var msg=document.getElementById(msgId);
  var btn=msgId==="adminPoolNameMsg"?document.querySelector("button[onclick=\"savePoolName('adminPoolNameMsg')\"]"):document.querySelector("button[onclick=\"savePoolName('profilePoolNameMsg')\"]");
  if(localDemoMode){if(msg){msg.classList.remove("good");msg.textContent="Demo mode keeps Firebase disabled. Pool settings are local preview only.";}return;}
  if(msg){msg.classList.remove("good");msg.textContent="Saving pool settings...";}
  if(btn){btn.disabled=true;btn.dataset.originalText=btn.textContent;btn.textContent="Saving...";}
  function restorePoolSettingsButton(){if(btn){btn.disabled=false;btn.textContent=btn.dataset.originalText||"Save Pool Settings";}}
  if(!isPoolAdmin()){if(msg)msg.textContent="Only this pool's admin can rename it.";restorePoolSettingsButton();return;}
  var adminSide=msgId==="adminPoolNameMsg";
  var input=document.getElementById(adminSide?"adminPoolNameInput":"profilePoolNameInput");
  var passInput=document.getElementById(adminSide?"adminPoolPasscodeInput":"profilePoolPasscodeInput");
  var name=cleanFullName(input&&input.value);
  var passcode=poolPasscode(passInput&&passInput.value);
  if(!name){if(msg)msg.textContent="Enter a pool name first.";restorePoolSettingsButton();return;}
  var passcodeReason=weakPoolPasscodeReason(passcode);
  if(passcodeReason){if(msg)msg.textContent=passcodeReason;restorePoolSettingsButton();return;}
  var oldPoolCode=currentPoolCode();
  if(joinPasscodeLooksGenerated(passcode,oldPoolCode,currentPoolId)){if(msg)msg.textContent="Join passcode should be different from the generated Pool Name Code.";restorePoolSettingsButton();return;}
  var oldJoinCode=currentJoinCode();
  var poolCode=oldPoolCode||poolNameCodeFromName(name,currentPoolId);
  var now=new Date().toISOString();
  if(shouldUseLocalFightLocksPreviewProfile()){
    currentPoolMeta=Object.assign({},currentPoolMeta,localFightLocksPreviewPoolMeta(),{poolName:name,poolCode:poolCode,joinCode:passcode,updatedAt:now});
    try{localStorage.setItem(poolStorageKey("localPoolMeta"),JSON.stringify(currentPoolMeta));}catch(e){}
    if(currentAccountData.joinedPools&&currentAccountData.joinedPools[currentPoolId])currentAccountData.joinedPools[currentPoolId]=Object.assign({},currentAccountData.joinedPools[currentPoolId],{poolName:name,poolCode:poolCode,joinCode:passcode,updatedAt:now});
    if(currentAccountData.hostedPools&&currentAccountData.hostedPools[currentPoolId])currentAccountData.hostedPools[currentPoolId]=Object.assign({},currentAccountData.hostedPools[currentPoolId],{poolName:name,poolCode:poolCode,joinCode:passcode,updatedAt:now});
    renderPoolShell();
    renderMemberGate();
    renderKnownPools();
    syncPoolNameInputs();
    renderMyPoolsView();
    showTemporaryMessage(msg,"Pool settings saved.",true,180000);
    restorePoolSettingsButton();
    return;
  }
  try{
    await setDoc(poolRootDoc(),{poolName:name,poolCode:poolCode,joinCode:passcode,updatedAt:now},{merge:true});
    await setDoc(poolDoc("_meta","info"),{poolName:name,poolCode:poolCode,joinCode:passcode,updatedAt:now},{merge:true});
    await setDoc(doc(db,"poolCodes",poolCode),{code:poolCode,poolId:currentPoolId,poolName:name,updatedAt:now},{merge:true});
    if(oldPoolCode&&oldPoolCode!==poolCode)deleteDoc(doc(db,"poolCodes",normalizePoolCode(oldPoolCode))).catch(function(){});
    if(oldJoinCode&&oldJoinCode!==passcode)deleteDoc(doc(db,"poolCodes",normalizePoolCode(oldJoinCode))).catch(function(){});
    currentPoolMeta=Object.assign({},currentPoolMeta,{poolName:name,poolCode:poolCode,joinCode:passcode,updatedAt:now});
    await updateSavedPoolMetadataForEveryone(name,passcode,poolCode);
    if(currentAccountData.joinedPools&&currentAccountData.joinedPools[currentPoolId])currentAccountData.joinedPools[currentPoolId]=Object.assign({},currentAccountData.joinedPools[currentPoolId],{poolName:name,poolCode:poolCode,joinCode:passcode,updatedAt:now});
    if(currentAccountData.hostedPools&&currentAccountData.hostedPools[currentPoolId])currentAccountData.hostedPools[currentPoolId]=Object.assign({},currentAccountData.hostedPools[currentPoolId],{poolName:name,poolCode:poolCode,joinCode:passcode,updatedAt:now});
    renderPoolShell();
    renderMemberGate();
    renderKnownPools();
    renderMyPoolsView();
    trackCreatorEvent("pool_settings_updated",{poolId:currentPoolId,poolName:name,joinCode:passcode});
    showTemporaryMessage(msg,"Pool settings saved.",true,180000);
  }catch(e){
    console.error(e);
    if(msg)msg.textContent="Could not save pool settings. Please try again.";
  }finally{
    restorePoolSettingsButton();
  }
};
