function globalLineLabel(line){
  if(!line)return "No line";
  var parts=[];
  if(line.o1!==undefined)parts.push(fmt(parseInt(line.o1)));
  if(line.o2!==undefined)parts.push(fmt(parseInt(line.o2)));
  return parts.join(" / ")||"No line";
}
