  var payload=Object.assign({},details,{
    type:type,
    createdAt:now,
    currentPoolId:currentPoolId,
    actorUid:(currentUser&&currentUser.uid)||(currentMember&&currentMember.authUid)||(currentMember&&currentMember.memberId)||"",
    actorEmail:(currentUser&&currentUser.email)||(currentMember&&currentMember.email)||"",
    actorName:(currentMember&&currentMember.name)||(currentUser&&currentUser.displayName)||""
  });
  try{
    setDoc(doc(db,"creatorAudit",creatorAuditDocId()),payload).catch(function(e){console.warn("Creator audit event not saved",e);});
  }catch(e){console.warn("Creator audit event not saved",e);}
