window.refreshGodFighterLines=async function(){
  if(!godModeRequested||!hasCreatorAccess()){setGodStatus("Creator access is required.",true);setGodOddsStatus("Creator access is required.",true);return;}
  if(!currentUser){setGodStatus("Sign in with your creator email first before refreshing fighter lines.",true);setGodOddsStatus("Sign in with your creator email first.",true);return;}
  setGodStatus("Refreshing fighter lines...");
  setGodOddsStatus("Refreshing fighter lines from The Odds API...");
  try{
    var oddsEvent=godOddsRefreshEvent();
    var oddsFights=godOddsRefreshFights().map(function(f){return {id:f.id,f1:f.f1,f2:f.f2};});
    var res=await fetch("/.netlify/functions/refresh-fighter-lines",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({eventId:oddsEvent.eventId||DEFAULT_EVENT_ID,fights:oddsFights})});
    var text=await res.text(), payload={};
    try{payload=JSON.parse(text||"{}");}catch(e){payload={error:text};}
    if(!res.ok)throw new Error(payload.error||"Could not refresh fighter lines");
    var data=normalizeOddsPayload(payload);
    await setDoc(globalFighterLinesDoc(),Object.assign({},data,{updatedBy:currentUser.uid,updatedByEmail:currentUser.email||""}),{merge:true});
    globalFighterLines=data;
    applyGlobalLinesRefresh();
    renderGodOddsPanel();
    trackCreatorEvent("god_fighter_lines_refreshed",{poolId:"all-pools",poolName:"All Pools",matchedCount:Object.keys(data.fights||{}).length,oddsUpdatedAt:data.updatedAt});
    setGodStatus("Fighter lines refreshed at "+pickSaveStamp(data.updatedAt)+".");
    setGodOddsStatus("Fighter lines refreshed successfully at "+pickSaveStamp(data.updatedAt)+". Matched "+Object.keys(data.fights||{}).length+" fight"+(Object.keys(data.fights||{}).length===1?"":"s")+".");
  }catch(e){
    console.error(e);
    var msg=oddsRefreshErrorMessage(e);
    setGodStatus(msg,true);
    setGodOddsStatus(msg,true);
  }
};
window.applyGodFighterLinesToAllPools=async function(){
  if(!godModeRequested||!hasCreatorAccess()){setGodStatus("Creator access is required.",true);setGodOddsStatus("Creator access is required.",true);return;}
  if(!currentUser){setGodStatus("Sign in with your creator email first before applying lines to pools.",true);setGodOddsStatus("Sign in with your creator email first.",true);return;}
  var lines=globalFighterLines&&globalFighterLines.fights?globalFighterLines.fights:{};
  if(!Object.keys(lines).length){setGodOddsStatus("Refresh fighter lines first, then apply them.",true);return;}
  if(!confirm("Apply these fighter lines to every pool that has Auto Fighter Lines turned on? Locked pools will keep their locked lines."))return;
  setGodStatus("Applying fighter lines to every pool...");
  setGodOddsStatus("Applying fighter lines to every pool...");
  try{
    var pools=await loadGodCollection("pools");
    if(!pools.ok)throw pools.error||new Error("Could not load pools");
    var now=new Date().toISOString(), applied=0;
    await Promise.all(pools.items.map(async function(p){
      var id=poolSlug(p.poolId||p.docId);
      if(!id)return;
      var scoringRef=doc(db,"pools",id,"settings","scoring");
      var scoringSnap=await getDoc(scoringRef).catch(function(){return null;});
      if(eventLockHasStarted(p))return;
      var saved=scoringSnap&&scoringSnap.exists()?scoringSnap.data().fights||{}:{};
      var card=Object.assign({},defaultCardScoring,saved.card||{});
      if(card.autoFighterLines===false)return;
      var threshold=parseInt(card.heavyUnderdogLine);if(isNaN(threshold)||threshold<100)threshold=300;
      var next=Object.assign({},saved,{card:card});
      fights.forEach(function(f){
        var line=lines[f.id];
        if(!line)return;
        var row=Object.assign({},next[f.id]||{});
        var o1=parseInt(line.o1), o2=parseInt(line.o2);
        if(!isNaN(o1)){row.o1=o1;row.winPts1=autoWinnerPts(o1,threshold);}
        if(!isNaN(o2)){row.o2=o2;row.winPts2=autoWinnerPts(o2,threshold);}
        next[f.id]=row;
      });
      await setDoc(scoringRef,{fights:next,autoLinesUpdatedAt:now,updatedAt:now},{merge:true});
      try{await setDoc(doc(db,"pools",id,"adminNotifications","fighter_lines_"+Date.now()),{type:"fighter_lines_applied",poolId:id,poolName:p.poolName||displayPoolName(id),message:"Official fighter lines were updated for this pool.",createdAt:now,actorUid:currentUser.uid,actorEmail:currentUser.email||"",actorName:"Site Creator"});}catch(e){}
      applied++;
    }));
    trackCreatorEvent("god_fighter_lines_applied",{poolId:"all-pools",poolName:"All Pools",poolCount:applied,oddsUpdatedAt:now});
    setGodStatus("Fighter lines applied to "+applied+" pool"+(applied===1?"":"s")+" at "+pickSaveStamp(now)+".");
    setGodOddsStatus("Fighter lines applied successfully to "+applied+" pool"+(applied===1?"":"s")+" at "+pickSaveStamp(now)+".");
    await renderGodDashboard();
  }catch(e){
    console.error(e);
    setGodStatus("Could not apply fighter lines to every pool yet. Firebase rules may need creator write access.",true);
    setGodOddsStatus("Could not apply fighter lines to every pool. Try again.",true);
  }
};
window.clearGodFighterLines=async function(){
  if(!godModeRequested||!hasCreatorAccess()){setGodStatus("Creator access is required.",true);setGodOddsStatus("Creator access is required.",true);return;}
  if(!currentUser){setGodStatus("Sign in with your creator email first before clearing fighter lines.",true);setGodOddsStatus("Sign in with your creator email first.",true);return;}
  if(!confirm("Clear the saved global fighter lines? Pools will fall back to their saved/manual lines."))return;
  try{
    var now=new Date().toISOString();
    globalFighterLines={eventId:DEFAULT_EVENT_ID,fights:{},updatedAt:now,clearedAt:now};
    await setDoc(globalFighterLinesDoc(),globalFighterLines,{merge:true});
    renderGodOddsPanel();
    setGodOddsStatus("Global fighter lines cleared at "+pickSaveStamp(now)+".");
    setGodStatus("Global fighter lines cleared.");
  }catch(e){
    console.error(e);
    setGodOddsStatus("Could not clear fighter lines.",true);
  }
};
function suppressGodModePoolSurfaces(){
  if(!godModeRequested||!document.body)return;
  document.body.classList.add("god-mode");
  document.body.classList.remove("app-profile-locked","landing-route-active","pool-route-boot","auth-boot-pending");
  [".header",".deadline-banner",".tabs",".view",".setup-home",".pool-shell","#memberGate","#setupHome"].forEach(function(selector){
    document.querySelectorAll(selector).forEach(function(el){
      if(el&&el.id!=="godModeView")el.style.setProperty("display","none","important");
    });
  });
  var god=document.getElementById("godModeView");
  if(god)god.style.setProperty("display","block","important");
  try{window.scrollTo(0,0);}catch(e){}
  if(god)try{god.scrollTop=0;}catch(e){}
}
function currentGodSection(){
  try{return localStorage.getItem("fightLocksCreatorSection")||"fight-night";}catch(e){return "fight-night";}
}
window.showGodSection=function(section){
  section=String(section||"fight-night");
  var sections=[].slice.call(document.querySelectorAll("[data-god-section]"));
  var hasSection=sections.some(function(el){return el.classList&&el.classList.contains("god-section")&&el.getAttribute("data-god-section")===section;});
  if(!hasSection)section="fight-night";
  document.querySelectorAll(".god-section").forEach(function(el){
    el.classList.toggle("active",el.getAttribute("data-god-section")===section);
  });
  document.querySelectorAll(".god-section-tab").forEach(function(el){
    el.classList.toggle("active",el.getAttribute("data-god-section")===section);
  });
  try{localStorage.setItem("fightLocksCreatorSection",section);}catch(e){}
};
function syncGodSectionNav(){
  if(!godModeRequested)return;
  window.showGodSection(currentGodSection());
}
async function renderGodDashboard(){
  suppressGodModePoolSurfaces();
  var loginPanel=document.getElementById("godLoginPanel");
  var dashboard=document.getElementById("godDashboard");
  var openSite=document.getElementById("godOpenSiteLink");
  if(openSite){
    openSite.hidden=true;
    openSite.setAttribute("aria-hidden","true");
    openSite.setAttribute("tabindex","-1");
    openSite.style.display="none";
  }
  if(!godModeRequested||!hasCreatorAccess()){
    if(loginPanel)loginPanel.style.display="block";
    if(dashboard)dashboard.style.display="none";
    setGodStatus("Sign in with the creator account to view Creator Tools.");
    return;
  }
  if(loginPanel)loginPanel.style.display=devAdminPreview?"none":"block";
  if(dashboard)dashboard.style.display="block";
  startGlobalFighterLinesListener();
  setGodStatus(devAdminPreview?"Local creator preview unlocked.":"Creator account unlocked.");
  var cards=document.getElementById("godCards");
  if(cards)cards.innerHTML=godCard("Loading","...");
  var results=await Promise.all([loadGodCollection("pools"),loadGodCollection("users"),loadGodCollection("creatorAudit")]);
  var pools=results[0].items.sort(function(a,b){return String(b.createdAt||b.updatedAt||"").localeCompare(String(a.createdAt||a.updatedAt||""));});
  var users=results[1].items.sort(function(a,b){return String(b.createdAt||b.updatedAt||"").localeCompare(String(a.createdAt||a.updatedAt||""));});
  var activity=results[2].items.sort(function(a,b){return String(b.createdAt||"").localeCompare(String(a.createdAt||""));}).slice(0,100);
  if(cards){
    cards.innerHTML=[
      godCard("Pools",results[0].ok?pools.length:"--"),
      godCard("Signups",results[1].ok?users.length:"--"),
      godCard("Events",godEventList().length),
      godCard("Tracked Activity",results[2].ok?activity.length:"--"),
      godCard("Access",devAdminPreview?"Local":"Creator")
    ].join("");
  }
  renderGodEventManager();
  renderGodList(document.getElementById("godPoolsList"),document.getElementById("godPoolsCount"),pools,"pools",results[0]);
  renderGodList(document.getElementById("godUsersList"),document.getElementById("godUsersCount"),users,"users",results[1]);
  renderGodList(document.getElementById("godActivityList"),document.getElementById("godActivityCount"),activity,"activity",results[2]);
  await loadGodGlobalResults();
  renderGodLaunchChecklist(results[0],results[1],results[2]);
  renderGodPoolHealth(pools,results[0]);
  renderGodResultsPanel();
  renderGodFinalizePreviewLoading("Preview not loaded yet. Use Refresh Preview when you are ready to run the read-only launch check.");
  renderGodOddsPanel();
  syncGodSectionNav();
  if(devAdminPreview){
    var applyBtn=document.querySelector('button[onclick="applyGodResultsToAllPools()"]');
    var clearBtn=document.querySelector('button[onclick="clearGodResultsFromAllPools()"]');
    if(applyBtn)applyBtn.textContent="Apply To Every Pool";
    if(clearBtn)clearBtn.textContent="Remove Results From Every Pool";
  }
}
window.signInGodMode=async function(){
  if(localDemoMode){setGodStatus("Demo mode keeps Firebase disabled. Open the live Creator Tools URL to sign in.",true);return;}
  var email=(document.getElementById("godEmailInput")&&document.getElementById("godEmailInput").value||"").trim().toLowerCase();
  var password=(document.getElementById("godPasswordInput")&&document.getElementById("godPasswordInput").value||"").trim();
  if(!validEmail(email)){setGodStatus("Enter the creator account email.",true);return;}
  if(!password){setGodStatus("Enter the creator account password.",true);return;}
  if(!creatorEmailAllowed(email)){setGodStatus("That email is not on the creator access list yet.",true);return;}
  setGodStatus("Unlocking Creator Tools...");
  publicLandingAuthIntent=true;
  signedOutOnPurpose=false;
  try{
    await setPersistence(auth,browserLocalPersistence);
    var result=await signInWithEmailAndPassword(auth,email,password);
    currentUser=result.user;
    trackCreatorEvent("creator_god_mode_login",{uid:currentUser.uid,email:currentUser.email});
    await renderGodDashboard();
  }catch(e){
    console.error(e);
    setGodStatus(authFriendlyError(e),true);
  }
};
function initGodMode(){
  if(!godModeRequested)return false;
  suppressGodModePoolSurfaces();
  renderGodDashboard();
  setTimeout(suppressGodModePoolSurfaces,250);
  setTimeout(suppressGodModePoolSurfaces,1000);
  return true;
}

