function embeddedUfc328FightDefaults(f){
  f=Object.assign({},f);
  f.glovesEnabled=false;
  f.glovePts={yes:0,no:0};
  f.timingEnabled=true;
  f.rounds=f.title?5:3;
  f.timingPts=Object.assign({},defaultScoringRules.timingPts);
  f.timingLines=f.title?{r1:"",r2:"",r3:"",r4:"",r5:"",distance:""}:{r1:"",r2:"",r3:"",distance:""};
  f.overUnderEnabled=true;
  f.overUnderLine=f.title?2.5:1.5;
  f.overUnderPts={over:defaultScoringRules.overUnderPts,under:defaultScoringRules.overUnderPts};
  f.winPts1=scoringWinnerPts(f.o1,defaultScoringRules);
  f.winPts2=scoringWinnerPts(f.o2,defaultScoringRules);
  f.bonusPts=Math.max(defaultScoringRules.methodPts.ko,defaultScoringRules.methodPts.sub,defaultScoringRules.methodPts.dec);
  f.methodPts=sideMethodMap(Object.assign({},defaultScoringRules.methodPts));
  f.methodLines=sideMethodMap({ko:"",sub:"",dec:""});
  f.pickEnabled=true;
  f.methodEnabled=true;
  return f;
}
