window.saveMakePickInlineUpdate=async function(fid){
  var msg=document.getElementById("makePickInlineSaveMsg_"+fid);
  var btn=msg&&msg.parentElement?msg.parentElement.querySelector("button"):null;
  var missing=typeof missingPickMessage==="function"?missingPickMessage({allowMissingLock:true}):"";
  if(missing){
    if(msg)msg.textContent=missing;
    return;
  }
  if(btn){btn.disabled=true;btn.textContent="Updating...";}
  if(msg){msg.textContent="";msg.classList.remove("saved");}
  var lockWillClear=cardScoring.lockEnabled&&currentPoolFeatureEnabled("allowLockOfTheNight")&&normalizeLockValue(lockPick)&&!lockEligibility(lockPick).valid;
  var before=window.__lastPickSaveAt||0;
  await window.submitPicks({allowMissingLock:true});
  var after=window.__lastPickSaveAt||0;
  if(after&&after!==before){
    clearMakePickFightDirty();
    renderMakePickInlineSaveButtons();
    var lockNeedsPick=!!lockWillClear;
    if(lockNeedsPick){
      lockPick="";
      clearLockEligibilityMessage();
      setMakePickFightNotice(fid,"Pick updated. Your Lock of the Night was cleared, so choose a new Lock of the Night before picks close.");
      renderLockPick();
      renderMakePickFightNotices();
    }
    var card=findMakePickFightCard(fid);
    if(card){
      var saved=document.createElement("div");
      saved.className="inline-fight-save-msg saved make-pick-inline-saved-msg";
      saved.textContent=lockNeedsPick?"Your pick has been updated. You need to change your Lock of the Night.":"Picks updated.";
      card.appendChild(saved);
      setTimeout(function(){if(saved&&saved.parentElement)saved.remove();},2600);
    }
  }else if(btn){
    btn.disabled=false;
    btn.textContent="Update Picks";
  }
};
