function setFightScoringFromConfig(cfg){
  if(!cfg)cfg={};
  cfg=upgradedFreedom250TitleScoring(cfg);
  cardScoring=Object.assign({},defaultCardScoring,cfg.card||{});
  cardScoring.lockLossPts=0;
  cardScoring.lockWinPts=parseInt(cardScoring.lockWinPts||cardScoring.lockWinPts===0?cardScoring.lockWinPts:cardScoring.lockWinPts);
  if(isNaN(cardScoring.lockWinPts))cardScoring.lockWinPts=defaultScoringRules.lockWinPts;
  if(cfg.card&&cfg.card.showBettingLines===false){
    if(cfg.card.showFighterBettingLines===undefined)cardScoring.showFighterBettingLines=false;
    if(cfg.card.showMethodBettingLines===undefined)cardScoring.showMethodBettingLines=false;
  }
  activeFights().forEach(function(f){
    var c=cfg[f.id]||{},def=defaultFightScoring[f.id]||{};
    if(c.o1!==undefined&&!isNaN(parseInt(c.o1)))f.o1=parseInt(c.o1);else f.o1=def.o1;
    if(c.o2!==undefined&&!isNaN(parseInt(c.o2)))f.o2=parseInt(c.o2);else f.o2=def.o2;
    f.pickEnabled=c.pickEnabled!==undefined?!!c.pickEnabled:(def.pickEnabled!==undefined?!!def.pickEnabled:true);
    f.methodEnabled=c.methodEnabled!==undefined?!!c.methodEnabled:(def.methodEnabled!==undefined?!!def.methodEnabled:true);
    f.methodLines=normalizeSideMethodMap(c.methodLines,def.methodLines);
    f.glovesEnabled=false;
    f.glovePts=Object.assign({},def.glovePts);
    f.timingEnabled=c.timingEnabled!==undefined?!!c.timingEnabled:def.timingEnabled;
    f.timingLines=Object.assign({},def.timingLines,c.timingLines||{});
    f.overUnderEnabled=c.overUnderEnabled!==undefined?!!c.overUnderEnabled:def.overUnderEnabled;
    f.overUnderLine=c.overUnderLine!==undefined&&!isNaN(parseFloat(c.overUnderLine))?parseFloat(c.overUnderLine):def.overUnderLine;
    f.rounds=def.rounds;
    applyCentralScoringToFight(f,cardScoring);
  });
  applyGlobalFighterLinesToFights();
}
function currentScoringConfig(){var cfg={card:Object.assign({},cardScoring,{methodPts:Object.assign({},cardScoring.methodPts||{}),timingPts:Object.assign({},cardScoring.timingPts||{})})};fights.forEach(function(f){cfg[f.id]={o1:parseInt(f.o1),o2:parseInt(f.o2),pickEnabled:fightEnabled(f),methodEnabled:f.methodEnabled!==false,methodLines:normalizeSideMethodMap(f.methodLines,defaultFightScoring[f.id].methodLines),glovesEnabled:false,glovePts:{yes:0,no:0},timingEnabled:!!f.timingEnabled,overUnderEnabled:!!f.overUnderEnabled,overUnderLine:getOverUnderLine(f)}});return cfg;}
function lockedScoringNotice(){return "Picks are locked. Saving scoring now will update the locked scoring sheet for this pool. Continue?";}
async function freezeScoringSnapshot(reason){
  var cfg=currentScoringConfig(), now=new Date().toISOString();
  cfg.card=Object.assign({},cfg.card,{scoringFrozen:true,scoringFrozenAt:now,scoringFrozenReason:reason||"picks_locked"});
  cardScoring=Object.assign({},cardScoring,cfg.card);
  await setDoc(poolDoc("settings","scoring"),{fights:cfg,scoringFrozen:true,scoringFrozenAt:now,updatedAt:now},{merge:true});
  return cfg;
}
function scoringKeyPointSet(values,withPlus){
  var seen={}, nums=[];
  (values||[]).forEach(function(v){var n=parseFloat(v);if(isNaN(n))return;var k=String(n);if(!seen[k]){seen[k]=true;nums.push(n);}});
  nums.sort(function(a,b){return a-b;});
  if(!nums.length)return withPlus?"+0 PTS":"0 PTS";
  function label(n){
    var txt=fmtPtsValue(n)+" PT"+(Math.abs(n)===1?"":"S");
    return withPlus?(n>=0?"+":"")+txt:txt;
  }
  if(nums.length===1)return label(nums[0]);
  var lo=nums[0], hi=nums[nums.length-1], unit=Math.abs(hi)===1?"PT":"PTS";
  return (withPlus&&lo>=0?"+":"")+fmtPtsValue(lo)+"-"+fmtPtsValue(hi)+" "+unit;
}
function scoringKeyWinPoints(kind){
  var rules=scoringRulesFromCard(cardScoring), vals=[];
  if(winnerScoringMode(rules)==="straight")return scoringKeyPointSet([rules.straightWinnerPts],false);
  activeFights().forEach(function(f){[1,2].forEach(function(side){var odds=side===1?f.o1:f.o2, n=parseInt(odds), match=false;if(kind==="normalFav")match=n<0&&n>rules.heavyFavoriteLine;else if(kind==="heavyFav")match=n<=rules.heavyFavoriteLine;else if(kind==="smallDog")match=n>=rules.smallUnderdogMin&&n<=rules.smallUnderdogMax;else if(kind==="bigDog")match=n>=rules.bigUnderdogMin&&n<=rules.bigUnderdogMax;else if(kind==="majorDog")match=n>=rules.majorUnderdogMin;if(match)vals.push(getWinPts(f,side));});});
  if(!vals.length)vals=[kind==="heavyFav"?rules.heavyFavoritePts:kind==="normalFav"?rules.normalFavoritePts:(kind==="smallDog"?rules.smallUnderdogPts:kind==="bigDog"?rules.bigUnderdogPts:rules.majorUnderdogPts)];
  return scoringKeyPointSet(vals,false);
}
function scoringKeyMethodPoints(method){
  var vals=[];
  activeFights().forEach(function(f){if(!methodEnabledForFight(f))return;[1,2].forEach(function(side){vals.push(getMethodPts(f,method,side));});});
  if(!vals.length)vals=[method==="dec"?1:2];
  return scoringKeyPointSet(vals,true);
}
function scoringKeyTimingPoints(){
  var vals=[];
  activeFights().forEach(function(f){if(!f.timingEnabled)return;timingOptionsForFight(f).forEach(function(v){vals.push(getTimingPts(f,v));});});
  return scoringKeyPointSet(vals.length?vals:[1],true);
}
function scoringKeyOverUnderPoints(){
  var vals=[];
  activeFights().forEach(function(f){if(!f.overUnderEnabled)return;vals.push(getOverUnderPts(f,"over"));vals.push(getOverUnderPts(f,"under"));});
  return scoringKeyPointSet(vals.length?vals:[1],true);
}
function scoringKeyGlovePoints(){
  var vals=[];
  fights.forEach(function(f){if(!f.glovesEnabled)return;vals.push(getGlovePts(f,"yes"));vals.push(getGlovePts(f,"no"));});
  return scoringKeyPointSet(vals.length?vals:[1],true);
}
function scoringKeyPillClassForValue(v){
  var n=parseFloat(v);
  if(isNaN(n))return "fav";
  if(n>=4)return "big";
  if(n>=3)return "dog";
  return "fav";
}
function scoringKeyPointPill(v,extraClass){
  var display=String(v);
  var nums=display.match(/-?\d+(?:\.\d+)?/g)||[];
  var maxVal=nums.length?Math.max.apply(null,nums.map(function(n){return parseFloat(n);})):parseFloat(v);
  if(display.toUpperCase().indexOf("PT")<0)display=ptText(v);
  return '<span class="scoring-key-pill '+(extraClass||scoringKeyPillClassForValue(maxVal))+'">'+escapeHtml(display)+'</span>';
}
function scoringKeyChip(label,value,extraClass){
  return '<span class="scoring-key-chip">'+escapeHtml(label)+' '+scoringKeyPointPill(value,extraClass)+'</span>';
}
function scoringKeyValueSetForTiming(option){
  var vals=[];
  activeFights().forEach(function(f){if(f.timingEnabled&&currentPoolFeatureEnabled("allowRoundPicks")&&timingOptionsForFight(f).indexOf(option)>-1)vals.push(getTimingPts(f,option));});
  return vals;
}
function scoringKeyTimingChips(){
  var opts=["r1","r2","r3","r4","r5","distance"], chips=[];
  opts.forEach(function(o){
    var vals=scoringKeyValueSetForTiming(o);
    if(!vals.length)return;
    var max=Math.max.apply(null,vals.map(function(v){return parseFloat(v)||0;}));
    chips.push(scoringKeyChip(o==="distance"?"Distance":o.toUpperCase(),max));
  });
  return chips.join("");
}
