function quickSetupSetStep(step){
  var count=quickSetupStepCount();
  step=parseInt(step);
  if(isNaN(step))step=0;
  step=Math.max(0,Math.min(count-1,step));
  quickSetupCurrentStep=step;
  var activeCardStep=quickSetupActiveCardStep(step);
  var shell=document.querySelector("#view-quicksetup .quick-setup-shell");
  if(shell){
    shell.classList.add("quick-wizard-ready");
    shell.classList.toggle("quick-step-first",step===0);
    shell.classList.toggle("quick-step-last",step===count-1);
    shell.classList.toggle("quick-money-entry-step",step===0);
    shell.classList.toggle("quick-money-payment-step",step===1);
    shell.classList.toggle("quick-money-payout-step",step===2);
  }
  var moneyCard=document.querySelector("#view-quicksetup .quick-money-step");
  if(moneyCard){
    var title=moneyCard.querySelector("h3");
    var copy=moneyCard.querySelector(".quick-setup-copy");
    if(title)title.textContent=step===2?"Prize Format":(step===1?"Payment Note":"Is there an entry fee?");
    if(copy)copy.textContent=step===2?"Choose who gets paid and preview the projected prize amounts before players join.":(step===1?"Tell players exactly how to pay your group host. Keep it short so it looks clean on the leaderboard.":"Choose Paid Pool or Free Pool first. Then this setup will move you to the next detail.");
  }
  document.querySelectorAll("#view-quicksetup .quick-setup-card[data-quick-step]").forEach(function(card){
    card.classList.toggle("quick-step-active",parseInt(card.getAttribute("data-quick-step"))===activeCardStep);
  });
  document.querySelectorAll("#view-quicksetup [data-quick-step-nav]").forEach(function(nav){
    var navStep=parseInt(nav.getAttribute("data-quick-step-nav"));
    nav.classList.toggle("quick-step-active",navStep===step);
    nav.classList.toggle("quick-step-complete",navStep<step);
    nav.setAttribute("aria-current",navStep===step?"step":"false");
  });
  var next=document.getElementById("quickSetupNextBtn");
  if(next)next.textContent="Next";
  if(step===0)quickEntrySetStage(quickEntryCurrentStage);
  renderQuickSetupReview();
  if(shell)try{shell.scrollIntoView({block:"start",behavior:"smooth"});}catch(e){}
}
function quickSetupGoStep(delta){
  delta=parseInt(delta)||0;
  if(quickSetupCurrentStep===0&&delta>0&&quickEntryCurrentStage<1){
    quickEntrySetStage(quickEntryCurrentStage+1);
    return;
  }
  if(quickSetupCurrentStep===0&&delta<0&&quickEntryCurrentStage>0){
    quickEntrySetStage(quickEntryCurrentStage-1);
    return;
  }
  quickSetupSetStep(quickSetupCurrentStep+delta);
}
