async function applyFreePoolLaunchCode(code,msg,statusFn){
  code=String(code||"").trim().toUpperCase().replace(/\s+/g,"");
  if(msg){msg.classList.remove("bad");msg.textContent="";}
  if(!isFreeStarterPool()){
    if(msg){msg.classList.add("bad");msg.textContent="This code is only needed for Free Pools.";}
    return false;
  }
  if(code!==FREE_POOL_LAUNCH_UNLOCK_CODE){
    if(msg){msg.classList.add("bad");msg.textContent="That code did not match. Try GSPGOAT.";}
    return false;
  }
  var now=new Date().toISOString();
  var patch={freePoolUnlimitedPlayers:true,launchCodeUnlimitedPlayers:true,launchUnlockCodeApplied:true,launchUnlockCode:"GSPGOAT",launchUnlockCodeAppliedAt:now,updatedAt:now};
  currentPoolMeta=Object.assign({},currentPoolMeta||{},patch);
  try{
    await setDoc(poolRootDoc(),patch,{merge:true});
    await setDoc(poolDoc("_meta","info"),patch,{merge:true});
    if(currentAccountData&&currentAccountData.hostedPools&&currentAccountData.hostedPools[currentPoolId])currentAccountData.hostedPools[currentPoolId]=Object.assign({},currentAccountData.hostedPools[currentPoolId],patch);
    if(currentAccountData&&currentAccountData.joinedPools&&currentAccountData.joinedPools[currentPoolId])currentAccountData.joinedPools[currentPoolId]=Object.assign({},currentAccountData.joinedPools[currentPoolId],patch);
    if(statusFn)statusFn("Launch promo active. Unlimited players unlocked through UFC 329.");
  }catch(e){
    console.error(e);
    if(statusFn)statusFn("Launch promo unlocked this preview, but it could not save online yet.",true);
  }
  syncQuickLaunchCodePanel();
  syncAdminLaunchCodePanel();
  updateQuickSetupPreview();
  syncPayoutInputs();
  renderPoolShell();
  renderBillingPlanPanels();
  return true;
}
