function quickSetupDefaultSplits(places){
  places=parseInt(places)||1;
  return places===1?[100,0,0]:(places===2?[70,30,0]:[60,30,10]);
}
function quickSetupPayoutInputValues(){
  return [
    parseFloat((document.getElementById("quickPayoutFirst")||{}).value)||0,
    parseFloat((document.getElementById("quickPayoutSecond")||{}).value)||0,
    parseFloat((document.getElementById("quickPayoutThird")||{}).value)||0
  ].map(function(v){return Math.max(0,Math.min(100,v));});
}
function quickSetupPayoutSettingsFromInputs(){
  var places=parseInt((document.getElementById("quickPayoutPlaces")||{}).value)||1;
  var splits=quickSetupPayoutInputValues();
  if(places===1)splits=[100,0,0];
  for(var i=places;i<3;i++)splits[i]=0;
  return sanitizePayoutSettings({places:places,splits:splits});
}
function quickSetupSetPayoutInput(index,value){
  var ids=["quickPayoutFirst","quickPayoutSecond","quickPayoutThird"];
  var input=document.getElementById(ids[index]);
  if(input)input.value=String(Math.round((parseFloat(value)||0)*10)/10);
}
window.quickSetupPayoutChanged=function(changedIndex){
  var places=parseInt((document.getElementById("quickPayoutPlaces")||{}).value)||1;
  if(places===1){
    quickSetupSetPayoutInput(0,100);
    quickSetupSetPayoutInput(1,0);
    quickSetupSetPayoutInput(2,0);
    updateQuickSetupPreview();
    return;
  }
  changedIndex=parseInt(changedIndex);
  if(isNaN(changedIndex)||changedIndex<0||changedIndex>=places)changedIndex=0;
  var splits=quickSetupPayoutInputValues();
  splits[changedIndex]=Math.max(0,Math.min(100,splits[changedIndex]));
  if(places===2){
    splits[1-changedIndex]=Math.max(0,100-splits[changedIndex]);
  }else if(changedIndex===0){
    var half=Math.max(0,(100-splits[0])/2);
    splits[1]=half;
    splits[2]=half;
  }else if(changedIndex===1){
    var maxSecond=Math.max(0,100-splits[0]);
    splits[1]=Math.min(splits[1],maxSecond);
    splits[2]=Math.max(0,100-splits[0]-splits[1]);
  }else{
    var maxThird=Math.max(0,100-splits[0]);
    splits[2]=Math.min(splits[2],maxThird);
    splits[1]=Math.max(0,100-splits[0]-splits[2]);
  }
  for(var j=places;j<3;j++)splits[j]=0;
  splits.forEach(function(value,index){quickSetupSetPayoutInput(index,value);});
  updateQuickSetupPreview();
};
function quickSetupSyncPayoutUi(){
  var places=parseInt((document.getElementById("quickPayoutPlaces")||{}).value)||1;
  if(!(places===1||places===2||places===3))places=1;
  var splits=quickSetupPayoutInputValues();
  if(places===1)splits=[100,0,0];
  var fields=[document.getElementById("quickPayoutFirstField"),document.getElementById("quickPayoutSecondField"),document.getElementById("quickPayoutThirdField")];
  var inputs=[document.getElementById("quickPayoutFirst"),document.getElementById("quickPayoutSecond"),document.getElementById("quickPayoutThird")];
  fields.forEach(function(field,i){if(field)field.style.display=i<places?"flex":"none";});
  inputs.forEach(function(input,i){
    if(!input)return;
    input.disabled=i>=places||places===1;
    input.value=String(i<places?splits[i]:0);
  });
  var totalPercent=splits.slice(0,places).reduce(function(a,b){return a+(parseFloat(b)||0);},0);
  var fee=parseInt((document.getElementById("quickEntryFeeInput")||{}).value)||0;
  var projected=quickSetupProjectedPlayerValue();
  var total=fee*projected;
  var names=["1st","2nd","3rd"];
  var lines=splits.slice(0,places).map(function(split,i){
    return '<div class="quick-payout-line"><strong>'+names[i]+'</strong><span>'+money(payoutAmountFromPercent(total,split))+' projected</span><div>'+((parseFloat(split)||0))+'% of pool</div></div>';
  }).join("");
  var preview=document.getElementById("quickPayoutPreview");
  if(preview){
    preview.innerHTML='<div class="quick-payout-lines">'+lines+'</div><div class="quick-payout-total"><strong>Projected pool:</strong> '+money(total)+' '+(fee&&projected?'('+money(fee)+' x '+projected+' players)':'')+'</div>'+(Math.abs(totalPercent-100)<0.01?'':'<div class="quick-payout-warning">Payout percentages must equal 100% before saving.</div>');
  }
  return Math.abs(totalPercent-100)<0.01;
}
window.quickSetupPayoutFormatChanged=function(){
  var places=parseInt((document.getElementById("quickPayoutPlaces")||{}).value)||1;
  var defaults=quickSetupDefaultSplits(places);
  [["quickPayoutFirst",0],["quickPayoutSecond",1],["quickPayoutThird",2]].forEach(function(pair){
    var input=document.getElementById(pair[0]);
    if(input)input.value=String(defaults[pair[1]]);
  });
  updateQuickSetupPreview();
};
