function quickSetupForcedOverUnderForTiming(timing){
  var f=quickSetupBasePreviewFight();
  if(!f||!timing)return "";
  if(timing==="distance")return "over";
  var rn=timingRoundNumber(timing);
  if(rn===null)return "";
  var line=getOverUnderLine(f);
  var targetRound=Math.floor(line)+1;
  if(rn<targetRound)return "under";
  if(rn>targetRound)return "over";
  return "";
}
