function quickSetupFormatFastestTime(value,force){
  var raw=String(value||"").trim().replace(/[^\d:]/g,"");
  if(!raw)return force?"0:00":"";
  if(/^\d+$/.test(raw)){
    if(raw.length<=2){
      if(!force&&raw.length<2)return raw;
      raw="0:"+String(parseInt(raw,10)||0).padStart(2,"0");
    }else{
      raw=String(parseInt(raw.slice(0,-2),10)||0)+":"+raw.slice(-2);
    }
  }
  var match=raw.match(/^(\d+):(\d{1,2})$/);
  if(!match)return raw.slice(0,5);
  var minutes=Math.max(0,parseInt(match[1],10)||0);
  var seconds=Math.max(0,parseInt(match[2],10)||0);
  if(seconds>59)seconds=59;
  if(minutes>5){minutes=5;seconds=0;}
  if(minutes===5&&seconds>0)seconds=0;
  return minutes+":"+String(seconds).padStart(2,"0");
}
window.setQuickSetupPreviewFastestTime=function(value,format){
  quickPreviewFastestTime=quickSetupFormatFastestTime(value,!!format||/^\d{3,}$/.test(String(value||"").trim()));
  var input=document.querySelector("#quickSpecialPreview .quick-fastest-time");
  if(input&&input.value!==quickPreviewFastestTime&&(format||/^\d{3,}$/.test(String(value||"").trim())))input.value=quickPreviewFastestTime;
};
