function preferredBannerForEntry(entry){
  var stored=readStoredProfileBanner();
  var preferredAccountBanner=[
    currentMember&&currentMember.profileBanner,
    currentMember&&currentMember.bannerKey,
    currentAccountData&&currentAccountData.profileBanner,
    currentAccountData&&currentAccountData.bannerKey
  ];
  if(stored&&stored!==defaultProfileBannerKey()&&bannerKeys().indexOf(stored)>-1)return stored;
  var candidates=preferredAccountBanner.concat([
    stored,
    entry&&entry.profileBanner,
    entry&&entry.bannerKey,
    myEntry&&myEntry.profileBanner
  ]);
  for(var i=0;i<candidates.length;i++){
    var key=candidates[i];
    if(key&&bannerKeys().indexOf(key)>-1)return key;
  }
  return "";
}

