window.findMyPicks=function(){
  var msg=document.getElementById("findPicksMsg");
  var findInput=document.getElementById("findPicksName");
  var mainInput=document.getElementById("nameInput");
  var raw=(findInput&&findInput.value)?findInput.value:(mainInput?mainInput.value:"");
  var wanted=cleanEntryName(raw);
  if(!msg)return;
  msg.className="find-picks-msg";
  if(!wanted){
    msg.className="find-picks-msg warn";
    msg.textContent="Type the same name you used when you submitted, then tap this again.";
    return;
  }
  var matches=allEntries.filter(function(e){return cleanEntryName(e.name)===wanted;});
  if(matches.length===1){
    loadMyEntry(matches[0]);
    msg.className="find-picks-msg good";
    msg.textContent="Found your picks. You can view or edit them until the lock time.";
    var mainName=document.getElementById("nameInput");
    if(mainName)mainName.value=matches[0].name||"";
    var myTab=document.getElementById("myTab");
    if(myTab){
      myTab.style.display="";
      showTab("mine",myTab);
    }
    return;
  }
  if(matches.length>1){
    msg.className="find-picks-msg warn";
    msg.textContent="More than one entry uses that name. Ask the pool admin to clean it up in Admin.";
    return;
  }
  msg.className="find-picks-msg bad";
  msg.textContent="No saved picks found for that exact name. Check the spelling or ask the pool admin.";
};

