(function(){
  var bottomPickDirty=false;
  var bottomPickSavedMsg="";
  function savedBottomLock(){
    return myEntry?normalizeLockValue(getEntryProps(myEntry).lock):"";
  }
  function canUpdateBottomPick(){
    return !!myDocId&&!isLocked();
  }
  function ensureBottomPickUpdateWrap(){
    var lockWrap=document.getElementById("lockPickWrap");
    var card=lockWrap&&lockWrap.querySelector(".lock-card");
    if(!card)return null;
    var wrap=document.getElementById("bottomPickUpdateWrap");
    if(!wrap){
      wrap=document.createElement("div");
      wrap.id="bottomPickUpdateWrap";
      wrap.className="inline-fight-save-wrap bottom-pick-update-wrap";
    }
    if(wrap.parentElement!==card)card.appendChild(wrap);
    return wrap;
  }
  function clearBottomPickUpdate(){
    bottomPickDirty=false;
    var wrap=document.getElementById("bottomPickUpdateWrap");
    if(wrap)wrap.innerHTML="";
  }
  function showBottomPickSaved(msg){
    bottomPickDirty=false;
    bottomPickSavedMsg=msg||"";
    var wrap=ensureBottomPickUpdateWrap();
    if(wrap)wrap.innerHTML='<div class="inline-fight-save-msg saved" id="bottomPickUpdateMsg">'+escapeHtml(bottomPickSavedMsg)+'</div>';
  }
  function queueBottomPickSaved(msg){
    showBottomPickSaved(msg);
    setTimeout(function(){
      if(bottomPickSavedMsg)showBottomPickSaved(bottomPickSavedMsg);
    },0);
    setTimeout(function(){
      if(bottomPickSavedMsg)showBottomPickSaved(bottomPickSavedMsg);
    },250);
  }
  function refreshBottomPickUpdate(){
    if(!canUpdateBottomPick()||normalizeLockValue(lockPick)===savedBottomLock()){
      if(bottomPickSavedMsg){
        showBottomPickSaved(bottomPickSavedMsg);
        return;
      }
      clearBottomPickUpdate();
      return;
    }
    bottomPickDirty=true;
    bottomPickSavedMsg="";
    var wrap=ensureBottomPickUpdateWrap();
    if(!wrap)return;
    wrap.innerHTML='<button type="button" class="inline-fight-save-btn dirty bottom-pick-update-btn" onclick="saveBottomPickUpdate()">Update This Pick</button><div class="inline-fight-save-msg" id="bottomPickUpdateMsg"></div>';
  }
  window.markBottomPickDirty=function(){
    refreshBottomPickUpdate();
  };
  window.saveBottomPickUpdate=async function(){
    if(!canUpdateBottomPick())return;
    if(lockPick&&!lockEligibility(lockPick).valid){showLockEligibilityMessage(lockEligibility(lockPick).message);refreshBottomPickUpdate();updateProgress();return;}
    if(normalizeLockValue(lockPick)===savedBottomLock()){clearBottomPickUpdate();return;}
    var btn=document.querySelector(".bottom-pick-update-btn"),msg=document.getElementById("bottomPickUpdateMsg");
    if(btn){btn.disabled=true;btn.textContent="Updating...";}
    if(msg){msg.textContent="";msg.classList.remove("saved");}
    try{
      var props=Object.assign({},getEntryProps(myEntry),{lock:normalizeLockValue(lockPick)||""});
      var tie=window.fastestFinishForSave&&window.fastestFinishForSave();
      if(tie)props.fastestFinish=tie;
      var updated=Object.assign({},myEntry,{props:props,updatedAt:new Date().toISOString()});
      await setDoc(poolDoc("entries",myEntry.docId),updated);
      myEntry=updated;
      loadMyEntry(updated);
      rememberPickSave(updated,"updated");
      renderLeaderboard();
      renderAllPicks();
      queueBottomPickSaved("Pick updated successfully.");
    }catch(e){
      if(btn){btn.disabled=false;btn.textContent="Update This Pick";}
      if(msg)msg.textContent="Could not update this pick. Try again.";
      console.warn("Could not update bottom pick",e);
    }
  };
  var originalPickLock=window.pickLock;
  window.pickLock=function(val){
    if(!currentPoolFeatureEnabled("allowLockOfTheNight"))return;
    bottomPickSavedMsg="";
    originalPickLock(val);
    window.markBottomPickDirty();
  };
  var originalRenderLockPick=renderLockPick;
  renderLockPick=function(){
    originalRenderLockPick();
    if(bottomPickDirty||normalizeLockValue(lockPick)===savedBottomLock())refreshBottomPickUpdate();
  };
})();

