function collectAdminScoring(){
  var cfg={card:{}};function val(id,fallback){var el=document.getElementById(id);var n=el?parseInt(el.value):fallback;return isNaN(n)?fallback:n;}function valFloat(id,fallback){var el=document.getElementById(id);var n=el?parseFloat(el.value):fallback;return isNaN(n)?fallback:n;}
  var le=document.getElementById("score_lock_enabled"),fighterLines=document.getElementById("score_fighter_lines_visible"),autoLines=document.getElementById("score_auto_fighter_lines"),winnerMode=document.getElementById("score_winner_mode");cfg.card.scoringRulesVersion=FIGHT_LOCKS_SCORING_RULES_VERSION;cfg.card.winnerScoringMode=winnerMode&&winnerMode.value==="straight"?"straight":"odds";cfg.card.straightWinnerPts=val("score_straight_winner_pts",defaultScoringRules.straightWinnerPts);cfg.card.showFighterBettingLines=fighterLines?!!fighterLines.checked:true;cfg.card.showMethodBettingLines=false;cfg.card.showBettingLines=cfg.card.showFighterBettingLines;cfg.card.autoFighterLines=autoLines?!!autoLines.checked:true;cfg.card.heavyFavoriteLine=val("score_heavy_fav_line",defaultScoringRules.heavyFavoriteLine);cfg.card.heavyFavoritePts=val("score_heavy_fav_pts",defaultScoringRules.heavyFavoritePts);cfg.card.normalFavoritePts=val("score_normal_fav_pts",defaultScoringRules.normalFavoritePts);cfg.card.smallUnderdogPts=val("score_small_dog_pts",defaultScoringRules.smallUnderdogPts);cfg.card.bigUnderdogPts=val("score_big_dog_pts",defaultScoringRules.bigUnderdogPts);cfg.card.majorUnderdogPts=val("score_major_dog_pts",defaultScoringRules.majorUnderdogPts);cfg.card.methodPts={ko:val("score_method_ko",defaultScoringRules.methodPts.ko),sub:val("score_method_sub",defaultScoringRules.methodPts.sub),dec:val("score_method_dec",defaultScoringRules.methodPts.dec)};cfg.card.timingPts={r1:val("score_time_r1",defaultScoringRules.timingPts.r1),r2:val("score_time_r2",defaultScoringRules.timingPts.r2),r3:val("score_time_r3",defaultScoringRules.timingPts.r3),r4:val("score_time_r4",defaultScoringRules.timingPts.r4),r5:val("score_time_r5",defaultScoringRules.timingPts.r5),distance:val("score_time_distance",defaultScoringRules.timingPts.distance)};cfg.card.overUnderPts=valFloat("score_ou_pts",defaultScoringRules.overUnderPts);cfg.card.lockEnabled=le?!!le.checked:true;cfg.card.lockWinPts=val("score_lock_win",defaultScoringRules.lockWinPts);cfg.card.lockLossPts=0;
  fights.forEach(function(f){var pe=document.getElementById("score_"+f.id+"_pick_enabled"),me=document.getElementById("score_"+f.id+"_method_enabled"),te=document.getElementById("score_"+f.id+"_timing_enabled"),oe=document.getElementById("score_"+f.id+"_ou_enabled");cfg[f.id]={o1:f.o1,o2:f.o2,pickEnabled:pe?!!pe.checked:true,methodEnabled:me?!!me.checked:true,methodLines:sideMethodMap({ko:"",sub:"",dec:""}),glovesEnabled:false,glovePts:{yes:0,no:0},timingEnabled:te?!!te.checked:true,overUnderEnabled:oe?!!oe.checked:true,overUnderLine:valFloat("score_"+f.id+"_ou_line",getOverUnderLine(f))};});return cfg;
}

function refreshAfterScoringChange(){
  renderScoringSummary();
  renderFights();
  refreshPickUI();
  renderLeaderboard();
  renderAllPicks();
  renderMySummary();
  renderAdminFights();
  renderAdminEntries();
  renderAdminAddEntry();
  renderAdminScoring();
  renderLockPick();
  updateProgress();
}

window.saveAdminScoring=async function(){
  if(!currentPoolFeatureEnabled("allowAdminScoringEdits")){var blocked=document.getElementById("adminScoringMsg");if(blocked)blocked.textContent=currentPlanUpgradeMessage();return;}
  if(isLocked()&&!confirm(lockedScoringNotice()))return;
  var cfg=collectAdminScoring();
  if(isLocked()){cfg.card=Object.assign({},cfg.card,{scoringFrozen:true,scoringFrozenAt:(cardScoring&&cardScoring.scoringFrozenAt)||new Date().toISOString(),scoringFrozenReason:"admin_scoring_update"});}
  setFightScoringFromConfig(cfg);
  refreshAfterScoringChange();
  updateProgress();
  var msg=document.getElementById("adminScoringMsg");
  try{
    await setDoc(poolDoc("settings","scoring"),{fights:cfg,updatedAt:new Date().toISOString()});
    if(msg){msg.classList.add("good");msg.textContent="✓ Scoring controls saved successfully at "+pickSaveStamp()+".";}
  }catch(e){
    console.error(e);
    if(msg)msg.textContent="Changed here, but could not save online.";
  }
};

window.saveAdminScoringFight=async function(fid){
  if(!currentPoolFeatureEnabled("allowAdminScoringEdits")){var blocked=document.getElementById("adminScoringMsg");if(blocked)blocked.textContent=currentPlanUpgradeMessage();return;}
  if(isLocked()&&!confirm(lockedScoringNotice()))return;
  var cfg=collectAdminScoring();
  if(isLocked()){cfg.card=Object.assign({},cfg.card,{scoringFrozen:true,scoringFrozenAt:(cardScoring&&cardScoring.scoringFrozenAt)||new Date().toISOString(),scoringFrozenReason:"admin_scoring_update"});}
  setFightScoringFromConfig(cfg);
  window.__adminScoreOpen=window.__adminScoreOpen||{};
  window.__adminScoreOpen[fid]=true;
  var stamp=new Date().toISOString();
  scoreSavedMessage(fid,stamp);
  refreshAfterScoringChange();
  updateProgress();
  var msg=document.getElementById("score_msg_"+fid);
  if(msg)msg.textContent=window.__adminScoreMsgs[fid];
  try{
    await setDoc(poolDoc("settings","scoring"),{fights:cfg,updatedAt:stamp});
    var global=document.getElementById("adminScoringMsg");
    if(global){global.classList.add("good");global.textContent="✓ Fight saved successfully at "+pickSaveStamp(stamp)+".";}
  }catch(e){
    console.error(e);
    if(msg)msg.textContent="Changed here, but could not save online.";
  }
};

window.resetAdminScoringDefaults=async function(){
  if(!currentPoolFeatureEnabled("allowAdminScoringEdits")){var blocked=document.getElementById("adminScoringMsg");if(blocked)blocked.textContent=currentPlanUpgradeMessage();return;}
  if(isLocked()&&!confirm("Picks are locked. Resetting scoring now will replace the locked scoring sheet for this pool. Continue?"))return;
  if(!confirm("Reset scoring points back to the original defaults? Fighter odds will remain system-controlled."))return;
  setFightScoringFromConfig({});
  refreshAfterScoringChange();
  updateProgress();
  var msg=document.getElementById("adminScoringMsg");
  try{
    await setDoc(poolDoc("settings","scoring"),{fights:{},updatedAt:new Date().toISOString()});
    if(msg)msg.textContent="✓ Scoring reset to defaults.";
  }catch(e){
    console.error(e);
    if(msg)msg.textContent="Reset here, but could not save online.";
  }
};


function renderAdminFights(){
  var el=document.getElementById("adminFights");if(!el)return;var html='<div class="admin-panel-tools"><button class="btn-edit" type="button" onclick="setAdminResultsOpen(true)">Open All</button><button class="btn-edit" type="button" onclick="setAdminResultsOpen(false)">Close All</button></div>';
  fights.forEach(function(f){
    var r=getEffectiveFightResult(f.id)||{},methBtns="",methodSide=r.winner||favoriteSide(f),open=adminOpenState("__adminResultOpen",f.id,false);
    r=normalizeFightResultData(f,r);
    var resultLines=fightResultDisplayLines(f,r);
    var status=r.winner?(r.winner===1?f.f1:f.f2)+" selected"+(resultLines.length?" · "+resultLines.join(" · "):""):"No result yet";
    if(f.bonus&&currentPoolFeatureEnabled("allowMethodPicks")){
      var koLine=methodLineLabel(getMethodLine(f,"ko",methodSide)),subLine=methodLineLabel(getMethodLine(f,"sub",methodSide)),decLine=methodLineLabel(getMethodLine(f,"dec",methodSide));
      methBtns='<button class="result-btn'+(r.method==="ko"?" m-active":"")+'" onclick="setResult(\''+f.id+'\',\'method\',\'ko\')">KO/TKO '+(koLine?koLine+" ":"")+'+'+getMethodPts(f,"ko",methodSide)+'</button><button class="result-btn'+(r.method==="sub"?" m-active":"")+'" onclick="setResult(\''+f.id+'\',\'method\',\'sub\')">Sub '+(subLine?subLine+" ":"")+'+'+getMethodPts(f,"sub",methodSide)+'</button><button class="result-btn'+(r.method==="dec"?" m-active":"")+'" onclick="setResult(\''+f.id+'\',\'method\',\'dec\')">Decision '+(decLine?decLine+" ":"")+'+'+getMethodPts(f,"dec",methodSide)+'</button>';
    }
    var gloveBtns="";
    var timingBtns="";
    if(f.timingEnabled&&currentPoolFeatureEnabled("allowRoundPicks")){
      var resultTimingOpts=timingOptionsForMethod(f,r.method);
      timingBtns+='<span style="font-size:11px;color:var(--muted);padding:7px 0">'+(!r.method?'Set the method before choosing round/distance. Options stay visible but locked.':(r.method==='dec'?'Decision selected; rounds are locked, use Goes Distance.':'Finish selected; choose the round, Goes Distance is locked.'))+'</span>';
      timingOptionsForFight(f).forEach(function(o){var ok=r.method&&resultTimingOpts.indexOf(o)>-1;timingBtns+='<button class="result-btn'+(r.timing===o?" m-active":"")+(ok?"":" timing-unavailable")+'" '+(ok?'onclick="setResult(\''+f.id+'\',\'timing\',\''+o+'\')"':'disabled title="Unavailable for the selected method"')+'>'+timingLabel(o)+' +'+getTimingPts(f,o)+'</button>';});
    }
    var decisionResult=r.method==="dec"||r.timing==="distance"||r.wentToDecision;
    var stoppageInput=decisionResult
      ? '<input type="text" id="result_'+f.id+'_stoppage" value="" placeholder="Not needed for decision" disabled>'
      : '<input type="text" id="result_'+f.id+'_stoppage" value="'+escapeHtml(r.stoppageMark||"")+'" placeholder="0:00" inputmode="numeric" onchange="setResult(\''+f.id+'\',\'stoppageMark\',this.value)">';
    var ouValue=r.overUnderResult?r.overUnderResult.charAt(0).toUpperCase()+r.overUnderResult.slice(1):(decisionResult?"Over":"Calculated after round and elapsed time");
    var stoppageField='<div class="admin-score-grid" style="margin-top:10px"><div class="admin-score-field"><label>Stoppage Elapsed Time</label>'+stoppageInput+'<div class="admin-score-sub">'+(decisionResult?"Decision fights went the distance, so no stoppage time is needed.":"Use elapsed time in the ending round, like 0:13 for a finish 13 seconds into the round.")+'</div></div><div class="admin-score-field"><label>O/U line</label><input type="text" value="'+escapeHtml(String(getOverUnderLine(f)))+'" disabled></div><div class="admin-score-field"><label>O/U result</label><input type="text" value="'+escapeHtml(ouValue)+'" disabled></div></div>';
    html+='<details class="result-detail" id="resultDetails_'+f.id+'" '+(open?'open':'')+' ontoggle="rememberAdminResultOpen(\''+f.id+'\',this.open)"><summary><div><div class="result-fight">'+f.w+(f.title?" · Title":f.bonus?" · Method/Props":"")+'</div><div class="result-name">'+f.f1.split(" ").pop()+" vs "+f.f2.split(" ").pop()+'</div><div class="admin-score-sub">'+escapeHtml(status)+'</div></div></summary><div class="result-detail-body"><div class="result-btns"><button class="result-btn'+(r.winner===1?" active":"")+'" onclick="setResult(\''+f.id+'\',\'winner\',1)">'+f.f1.split(" ").pop()+'</button><button class="result-btn'+(r.winner===2?" active":"")+'" onclick="setResult(\''+f.id+'\',\'winner\',2)">'+f.f2.split(" ").pop()+'</button><button class="result-btn clear" onclick="clearResult(\''+f.id+'\')">Clear</button>'+methBtns+gloveBtns+timingBtns+'</div>'+stoppageField+'</div></details>';
  });
  el.innerHTML=html;
}

window.__adminPickDrafts=window.__adminPickDrafts||{};
function adminEntryCanAssistEdit(entry){
  return !!(entry&&(entry.docId||entry.memberId||entry.authUid||entry.uid||entry.userId)&&(entry.email||entry.memberId||entry.authUid||entry.uid||entry.userId));
}
function adminEntryByDocId(docId){
  docId=String(docId||"");
  return (allEntries||[]).find(function(e){return String(e.docId||"")===docId;})||null;
}
function adminDraftKey(docId){return String(docId||"");}
function adminCloneMap(obj){return Object.assign({},obj||{});}
function adminFastestFromValue(value){
  value=value||{};
  var round=String(value.round||value.r||value.roundNumber||"").toLowerCase();
  if(/^[1-5]$/.test(round))round="r"+round;
  var mark=value.mark||value.timeMark||value.time||"";
  if(!mark&&value.seconds!=null){
    var sec=parseInt(value.seconds,10);
    if(!isNaN(sec))mark=Math.floor(sec/60)+":"+String(sec%60).padStart(2,"0");
  }
  var parsed=adminParseFastestTime(mark);
  if(!/^r[1-3]$/.test(round)||!parsed)return null;
  var roundNumber=parseInt(round.replace("r",""),10);
  return {round:round,mark:parsed.mark,time:parsed.mark,seconds:parsed.seconds,totalSeconds:(roundNumber-1)*300+parsed.seconds};
}
function adminParseFastestTime(value){
  var raw=String(value||"").trim();
  if(!raw)return null;
  if(/^\d+$/.test(raw)){
    raw=raw.length<=2?"0:"+String(parseInt(raw,10)||0).padStart(2,"0"):String(parseInt(raw.slice(0,-2),10)||0)+":"+raw.slice(-2);
  }
  var match=raw.match(/^([0-5]):([0-5]\d)$/);
  if(!match)return null;
  var minutes=parseInt(match[1],10), seconds=parseInt(match[2],10);
  if(minutes>5||(minutes===5&&seconds>0))return null;
  return {mark:minutes+":"+String(seconds).padStart(2,"0"),seconds:minutes*60+seconds};
}
function adminDraftForEntry(entry){
  if(!entry||!entry.docId)return null;
  var key=adminDraftKey(entry.docId), existing=window.__adminPickDrafts[key];
  if(existing)return existing;
  var props=typeof getEntryProps==="function"?getEntryProps(entry):(entry.props||{});
  var fastest=adminFastestFromValue(props.fastestFinish||props.fastestFinishTiebreaker||entry.fastestFinishTiebreaker||{});
  var draft={
    docId:String(entry.docId),
    open:false,
    message:"",
    error:false,
    picks:adminCloneMap(entry.picks),
    methods:adminCloneMap(entry.methods),
    timings:adminCloneMap(props.timings),
    overs:adminCloneMap(props.overs),
    lock:normalizeLockValue(props.lock||entry.lock||""),
    fastestFinish:fastest
  };
  if(draft.lock&&!lockEligibility(draft.lock,{picks:draft.picks}).valid)draft.lock="";
  window.__adminPickDrafts[key]=draft;
  return draft;
}
function adminTimingOptionsForMethod(f,method){
  return typeof timingOptionsForMethod==="function"?timingOptionsForMethod(f,method):[];
}
function adminNormalizeDraftTiming(draft,fid){
  var f=fights.find(function(x){return x.id===fid;});
  if(!f||!f.timingEnabled)return;
  var method=draft.methods[fid];
  if(method==="dec")draft.timings[fid]="distance";
  else if((method==="ko"||method==="sub")&&draft.timings[fid]==="distance")delete draft.timings[fid];
  else if(draft.timings[fid]&&adminTimingOptionsForMethod(f,method).indexOf(draft.timings[fid])<0)delete draft.timings[fid];
  adminNormalizeDraftOver(draft,fid);
}
function adminOverUnderFromDraft(f,draft){
  var timing=draft&&draft.timings&&draft.timings[f.id];
  if(timing==="distance")return "over";
  var rn=timingRoundNumber(timing);
  if(rn===null)return "";
  var line=getOverUnderLine(f),targetRound=Math.floor(line)+1;
  if(rn>targetRound)return "over";
  if(rn<targetRound)return "under";
  return "";
}
function adminOverValidForDraft(f,val,draft){
  if(!val)return true;
  var forced=adminOverUnderFromDraft(f,draft);
  return !forced||forced===val;
}
function adminNormalizeDraftOver(draft,fid){
  var f=fights.find(function(x){return x.id===fid;});
  if(!f||!f.overUnderEnabled)return;
  if(draft.overs[fid]&&!adminOverValidForDraft(f,draft.overs[fid],draft))delete draft.overs[fid];
}
function adminDraftCompleteProblems(draft){
  var problems=[];
  activeFights().forEach(function(f){
    if(!draft.picks[f.id])problems.push(f.f1.split(" ").pop()+" vs "+f.f2.split(" ").pop()+": winner");
    if(methodEnabledForFight(f)&&!draft.methods[f.id])problems.push(f.f1.split(" ").pop()+" vs "+f.f2.split(" ").pop()+": method");
    if(f.timingEnabled&&currentPoolFeatureEnabled("allowRoundPicks")&&!draft.timings[f.id])problems.push(f.f1.split(" ").pop()+" vs "+f.f2.split(" ").pop()+": round/distance");
    if(f.overUnderEnabled&&currentPoolFeatureEnabled("allowOverUnder")&&!draft.overs[f.id])problems.push(f.f1.split(" ").pop()+" vs "+f.f2.split(" ").pop()+": O/U");
  });
  if(cardScoring.lockEnabled&&currentPoolFeatureEnabled("allowLockOfTheNight")&&(!draft.lock||!lockEligibility(draft.lock,{picks:draft.picks}).valid))problems.push("valid Lock of the Night");
  if(currentPoolFeatureEnabled("allowFastestFinishTiebreaker")&&!draft.fastestFinish)problems.push("Fastest Finish Tiebreaker");
  return problems;
}
function adminAssistButton(id,label,active,disabled,onclick){
  return '<button type="button" class="admin-assist-btn'+(active?' active':'')+'" '+(disabled?'disabled aria-disabled="true"':'onclick="'+onclick+'"')+'>'+escapeHtml(label)+'</button>';
}
function adminPickEditorHtml(entry){
  if(!adminEntryCanAssistEdit(entry))return "";
  var draft=adminDraftForEntry(entry);
  if(!draft||!draft.open)return "";
  if(isLocked())return '<div class="admin-assist-editor"><div class="admin-assist-msg error">Picks are locked. Admin-assisted editing is closed for this pool.</div></div>';
  var html='<div class="admin-assist-editor" id="adminPickEditor_'+escapeHtml(entry.docId)+'"><div class="admin-assist-head"><div><div class="admin-assist-title">Editing picks for '+escapeHtml(entry.name||"Player")+'</div><div class="admin-assist-sub">Admin-assisted pick edit. Only update this if the player asked you to help with their picks.</div></div><button type="button" class="btn-edit" onclick="cancelAdminPickEditor(\''+encodeURIComponent(String(entry.docId||""))+'\')">Close</button></div><div class="admin-assist-grid">';
  activeFights().forEach(function(f){
    var method=draft.methods[f.id]||"", allowed=adminTimingOptionsForMethod(f,method);
    html+='<div class="admin-assist-fight"><div class="admin-assist-fight-title">'+escapeHtml(f.f1+" vs "+f.f2)+'</div>';
    html+='<div class="admin-assist-row"><div class="admin-assist-label">Winner</div>'
      +adminAssistButton("",f.f1,draft.picks[f.id]===1,false,"adminSetDraftWinner('"+encodeURIComponent(entry.docId)+"','"+f.id+"',1)")
      +adminAssistButton("",f.f2,draft.picks[f.id]===2,false,"adminSetDraftWinner('"+encodeURIComponent(entry.docId)+"','"+f.id+"',2)")+'</div>';
    if(methodEnabledForFight(f)){
      html+='<div class="admin-assist-row"><div class="admin-assist-label">Method</div>'
        +adminAssistButton("","KO/TKO",method==="ko",false,"adminSetDraftMethod('"+encodeURIComponent(entry.docId)+"','"+f.id+"','ko')")
        +adminAssistButton("","Submission",method==="sub",false,"adminSetDraftMethod('"+encodeURIComponent(entry.docId)+"','"+f.id+"','sub')")
        +adminAssistButton("","Decision",method==="dec",false,"adminSetDraftMethod('"+encodeURIComponent(entry.docId)+"','"+f.id+"','dec')")+'</div>';
    }
    if(f.timingEnabled&&currentPoolFeatureEnabled("allowRoundPicks")){
      html+='<div class="admin-assist-row"><div class="admin-assist-label">Round / Distance</div>';
      timingOptionsForFight(f).forEach(function(t){
        var ok=!!method&&allowed.indexOf(t)>-1;
        html+=adminAssistButton("",timingLabel(t),draft.timings[f.id]===t,!ok,"adminSetDraftTiming('"+encodeURIComponent(entry.docId)+"','"+f.id+"','"+t+"')");
      });
      html+='</div>';
    }
    if(f.overUnderEnabled&&currentPoolFeatureEnabled("allowOverUnder")){
      html+='<div class="admin-assist-row"><div class="admin-assist-label">Over / Under '+getOverUnderLine(f)+'</div>';
      ["over","under"].forEach(function(v){
        var ok=adminOverValidForDraft(f,v,draft);
        html+=adminAssistButton("",v==="over"?"Over":"Under",draft.overs[f.id]===v,!ok,"adminSetDraftOver('"+encodeURIComponent(entry.docId)+"','"+f.id+"','"+v+"')");
      });
      html+='</div>';
    }
    html+='</div>';
  });
  if(cardScoring.lockEnabled&&currentPoolFeatureEnabled("allowLockOfTheNight")){
    html+='<div class="admin-assist-special"><div class="admin-assist-fight-title">Lock of the Night</div><div class="admin-assist-row">';
    activeFights().forEach(function(f){[1,2].forEach(function(side){
      var val=f.id+":"+side, info=lockEligibility(val,{picks:draft.picks}), name=side===1?f.f1:f.f2;
      html+=adminAssistButton("",name,draft.lock===val,!info.valid,"adminSetDraftLock('"+encodeURIComponent(entry.docId)+"','"+val+"')");
    });});
    html+='</div></div>';
  }
  if(currentPoolFeatureEnabled("allowFastestFinishTiebreaker")){
    var ft=draft.fastestFinish||{}, mark=ft.mark||"";
    html+='<div class="admin-assist-special"><div class="admin-assist-fight-title">Fastest Finish Tiebreaker</div><div class="admin-assist-row"><div class="admin-assist-label">Round</div>';
    ["r1","r2","r3"].forEach(function(r){html+=adminAssistButton("",r.toUpperCase(),ft.round===r,false,"adminSetDraftFastestRound('"+encodeURIComponent(entry.docId)+"','"+r+"')");});
    html+='</div><div class="admin-assist-row"><div class="admin-assist-label">Elapsed Time</div><input class="admin-assist-time" id="adminFastest_'+escapeHtml(entry.docId)+'" value="'+escapeHtml(mark)+'" placeholder="1:11" inputmode="numeric" onblur="adminSetDraftFastestMark(\''+encodeURIComponent(entry.docId)+'\',this.value,true)"><button type="button" class="btn-edit" onclick="adminSetDraftFastestMark(\''+encodeURIComponent(entry.docId)+'\',document.getElementById(\'adminFastest_'+escapeHtml(entry.docId)+'\').value,true)">Format Time</button></div></div>';
  }
  html+='</div><div class="admin-assist-actions"><button type="button" class="btn-save" onclick="saveAdminAssistedPicks(\''+encodeURIComponent(String(entry.docId||""))+'\')">Save Picks</button><button type="button" class="btn-edit" onclick="cancelAdminPickEditor(\''+encodeURIComponent(String(entry.docId||""))+'\')">Close</button></div><div class="admin-assist-msg '+(draft.error?'error':'')+'" id="adminAssistMsg_'+escapeHtml(entry.docId)+'">'+escapeHtml(draft.message||"")+'</div></div>';
  return html;
}

function renderAdminEntries(){
  var el=document.getElementById("adminEntries");if(!el)return;
  if(!allEntries.length){el.innerHTML='<div class="empty" style="padding:20px">No joined players or pool entries yet.</div>';return;}
  var html="";
  var prototypeTools=adminPrototypeToolsEnabled();
  var entriesReadOnly=!currentPoolFeatureEnabled("allowAdminScoringEdits");
  var disabledAttr=entriesReadOnly?' disabled aria-disabled="true" title="Pool entry editing is unavailable for this plan."':'';
  function entryStatusSummary(entry){
    var props=typeof getEntryProps==="function"?getEntryProps(entry):(entry.props||{});
    var picksObj=entry.picks||{};
    var methodObj=entry.methods||{};
    var timingObj=props.timings||{};
    var overObj=props.overs||{};
    var enabledFights=activeFights();
    var winners=enabledFights.filter(function(f){return picksObj[f.id];}).length;
    var bonusTotal=enabledFights.filter(methodEnabledForFight).length;
    var methodCount=enabledFights.filter(function(f){return methodEnabledForFight(f)&&methodObj[f.id];}).length;
    var timingTotal=enabledFights.filter(function(f){return f.timingEnabled&&currentPoolFeatureEnabled("allowRoundPicks");}).length;
    var timingCount=enabledFights.filter(function(f){return f.timingEnabled&&currentPoolFeatureEnabled("allowRoundPicks")&&timingObj[f.id];}).length;
    var overTotal=enabledFights.filter(function(f){return f.overUnderEnabled&&currentPoolFeatureEnabled("allowOverUnder");}).length;
    var overCount=enabledFights.filter(function(f){return f.overUnderEnabled&&currentPoolFeatureEnabled("allowOverUnder")&&overObj[f.id];}).length;
    var lockValue=props.lock||entry.lock||"";
    var lockOk=!cardScoring.lockEnabled||!currentPoolFeatureEnabled("allowLockOfTheNight")||!!(lockValue&&(typeof lockEligibility!=="function"||lockEligibility(lockValue,{picks:picksObj}).valid));
    var fastest=props.fastestFinish||props.fastestFinishTiebreaker||entry.fastestFinishTiebreaker||{};
    var fastestOk=!currentPoolFeatureEnabled("allowFastestFinishTiebreaker")||!!(fastest&&(fastest.round||fastest.r)&&(fastest.mark||fastest.timeMark||fastest.time||fastest.seconds!=null));
    var complete=winners===fights.length&&(!bonusTotal||methodCount===bonusTotal)&&(!timingTotal||timingCount===timingTotal)&&(!overTotal||overCount===overTotal)&&lockOk&&fastestOk;
    var chips=[
      '<span class="entry-status-chip '+(complete?'good':'warn')+'">'+(complete?'Picks submitted':'Entry in progress')+'</span>',
      '<span class="entry-status-chip '+(winners===fights.length?'good':'warn')+'">'+winners+'/'+fights.length+' winners</span>'
    ];
    if(bonusTotal)chips.push('<span class="entry-status-chip '+(methodCount===bonusTotal?'good':'warn')+'">'+methodCount+'/'+bonusTotal+' methods</span>');
    if(timingTotal)chips.push('<span class="entry-status-chip '+(timingCount===timingTotal?'good':'warn')+'">'+timingCount+'/'+timingTotal+' rounds</span>');
    if(overTotal)chips.push('<span class="entry-status-chip '+(overCount===overTotal?'good':'warn')+'">'+overCount+'/'+overTotal+' O/U</span>');
    if(cardScoring.lockEnabled&&currentPoolFeatureEnabled("allowLockOfTheNight"))chips.push('<span class="entry-status-chip '+(lockOk?'good':'warn')+'">'+(lockOk?'Lock selected':'Lock needed')+'</span>');
    if(currentPoolFeatureEnabled("allowFastestFinishTiebreaker"))chips.push('<span class="entry-status-chip '+(fastestOk?'good':'warn')+'">'+(fastestOk?'Tiebreaker selected':'Tiebreaker needed')+'</span>');
    return chips.join("");
  }
  if(!prototypeTools){
    html+='<div class="admin-key-note">Review joined players, check entry status, and remove entries if needed. Admin-assisted pick editing is coming soon.</div>';
  }
  allEntries.forEach(function(e){
    var mp=e.methods||{};
    var pickMap=e.picks||{};
    var bonusFights=fights.filter(function(f){return f.bonus;});
    var editGrid="";
    fights.forEach(function(f){
      editGrid+='<div class="edit-item"><div class="edit-label">'+f.f1.split(" ").pop()+" vs "+f.f2.split(" ").pop()+'</div>'
        +'<select class="edit-select" id="esel_'+e.docId+'_'+f.id+'"'+disabledAttr+'>'
        +'<option value="">—</option>'
        +'<option value="1"'+(pickMap[f.id]===1?" selected":"")+'>'+f.f1.split(" ").pop()+'</option>'
        +'<option value="2"'+(pickMap[f.id]===2?" selected":"")+'>'+f.f2.split(" ").pop()+'</option>'
        +'</select></div>';
    });
    var methEdits="";
    bonusFights.forEach(function(f){
      methEdits+='<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;flex-wrap:wrap">'
        +'<span style="font-size:11px;color:var(--muted);min-width:120px">'+pickedFighterName(e,f).split(" ").pop()+" method:</span>"
        +'<select class="edit-select" id="emeth_'+e.docId+'_'+f.id+'" style="width:auto"'+disabledAttr+'>'
        +'<option value="">—</option>'
        +'<option value="ko"'+(mp[f.id]==="ko"?" selected":"")+'>KO/TKO</option>'
        +'<option value="sub"'+(mp[f.id]==="sub"?" selected":"")+'>Sub</option>'
        +'<option value="dec"'+(mp[f.id]==="dec"?" selected":"")+'>Decision</option>'
        +'</select></div>';
    });
    html+='<div class="entry-row" id="erow_'+e.docId+'">'
      +'<div class="entry-top"><div><div class="entry-name">'+escapeHtml(e.name||"Player")+'</div><div class="entry-meta">'+escapeHtml((e.email||e.memberId||e.authUid)?"Joined player entry":"Pool entry")+'</div><div class="entry-status-grid">'+entryStatusSummary(e)+'</div></div>'
      +'<div class="entry-actions">'
      +(prototypeTools?'<button class="btn-edit" id="ebtn_'+escapeHtml(e.docId)+'" onclick="toggleEdit(\''+escapeHtml(e.docId)+'\')">✏️ Edit</button>':'')
      +(adminEntryCanAssistEdit(e)?(isLocked()?'<button class="btn-edit" disabled title="Picks are locked. Admin-assisted editing is closed for this pool.">Picks Locked</button>':'<button class="btn-edit" onclick="openAdminPickEditor(\''+encodeURIComponent(String(e.docId||""))+'\')">Edit Picks</button>'):'')
      +'<button class="btn-delete" onclick="deleteEntry(\''+escapeHtml(e.docId)+'\',\''+escapeHtml(String(e.name||"").replace(/'/g, ""))+'\')">Remove Entry</button>'
      +'</div></div>'
      +adminPickEditorHtml(e)
      +(prototypeTools?'<div class="edit-panel" id="epanel_'+escapeHtml(e.docId)+'">'
      +(entriesReadOnly?'<div class="admin-locked-inline-note">'+lockedFeatureMessage()+'</div>':'')
      +'<div style="font-size:11px;font-weight:600;color:var(--muted);margin-bottom:8px;text-transform:uppercase;letter-spacing:.06em">Fighter picks</div>'
      +'<div class="edit-grid">'+editGrid+'</div>'
      +'<div style="font-size:11px;font-weight:600;color:var(--muted);margin-bottom:8px;text-transform:uppercase;letter-spacing:.06em">Method picks</div>'
      +methEdits
      +(entriesReadOnly?'<button class="btn-save plan-locked-control" disabled aria-disabled="true" title="Pool entry editing is unavailable for this plan.">Save Changes Locked</button>':'<button class="btn-save" onclick="saveEntry(\''+e.docId+'\')">✓ Save changes</button>')
      +'</div>':'')+'</div>';
  });
  el.innerHTML=html;
  renderAdminTransferPanel();
}

window.openAdminPickEditor=function(encodedDocId){
  var docId=decodeURIComponent(String(encodedDocId||"")), entry=adminEntryByDocId(docId);
  if(!entry||!adminEntryCanAssistEdit(entry))return;
  if(isLocked()){
    var draft=adminDraftForEntry(entry);
    if(draft){draft.open=true;draft.error=true;draft.message="Picks are locked. Admin-assisted editing is closed for this pool.";}
    renderAdminEntries();
    return;
  }
  var d=adminDraftForEntry(entry);
  d.open=true;d.message="";d.error=false;
  renderAdminEntries();
};
window.cancelAdminPickEditor=function(encodedDocId){
  var docId=decodeURIComponent(String(encodedDocId||""));
  delete window.__adminPickDrafts[adminDraftKey(docId)];
  renderAdminEntries();
};
window.adminSetDraftWinner=function(encodedDocId,fid,side){
  var entry=adminEntryByDocId(decodeURIComponent(String(encodedDocId||""))), draft=adminDraftForEntry(entry);
  if(!draft||isLocked())return;
  draft.picks[fid]=parseInt(side,10);
  if(draft.lock&&normalizeLockValue(draft.lock).split(":")[0]===fid&&!lockEligibility(draft.lock,{picks:draft.picks}).valid){
    draft.lock="";
    draft.message="Lock cleared — choose a fighter this player picked to win.";
    draft.error=true;
  }else{draft.message="";draft.error=false;}
  renderAdminEntries();
};
window.adminSetDraftMethod=function(encodedDocId,fid,method){
  var entry=adminEntryByDocId(decodeURIComponent(String(encodedDocId||""))), draft=adminDraftForEntry(entry);
  if(!draft||isLocked())return;
  draft.methods[fid]=method;
  adminNormalizeDraftTiming(draft,fid);
  renderAdminEntries();
};
window.adminSetDraftTiming=function(encodedDocId,fid,timing){
  var entry=adminEntryByDocId(decodeURIComponent(String(encodedDocId||""))), draft=adminDraftForEntry(entry), f=fights.find(function(x){return x.id===fid;});
  if(!draft||!f||isLocked())return;
  if(adminTimingOptionsForMethod(f,draft.methods[fid]).indexOf(timing)<0)return;
  draft.timings[fid]=timing;
  adminNormalizeDraftOver(draft,fid);
  renderAdminEntries();
};
window.adminSetDraftOver=function(encodedDocId,fid,val){
  var entry=adminEntryByDocId(decodeURIComponent(String(encodedDocId||""))), draft=adminDraftForEntry(entry), f=fights.find(function(x){return x.id===fid;});
  if(!draft||!f||isLocked())return;
  if(!adminOverValidForDraft(f,val,draft))return;
  draft.overs[fid]=val;
  renderAdminEntries();
};
window.adminSetDraftLock=function(encodedDocId,val){
  var entry=adminEntryByDocId(decodeURIComponent(String(encodedDocId||""))), draft=adminDraftForEntry(entry);
  if(!draft||isLocked())return;
  var elig=lockEligibility(val,{picks:draft.picks});
  if(!elig.valid){draft.message=elig.message||"You can only lock a fighter this player picked to win.";draft.error=true;renderAdminEntries();return;}
  draft.lock=normalizeLockValue(val);draft.message="";draft.error=false;
  renderAdminEntries();
};
window.adminSetDraftFastestRound=function(encodedDocId,round){
  var entry=adminEntryByDocId(decodeURIComponent(String(encodedDocId||""))), draft=adminDraftForEntry(entry);
  if(!draft||isLocked())return;
  round=String(round||"").toLowerCase();
  if(!/^r[1-3]$/.test(round))return;
  var old=draft.fastestFinish||{};
  var parsed=adminParseFastestTime(old.mark||old.time||"");
  var roundNumber=parseInt(round.replace("r",""),10)||1;
  draft.fastestFinish=parsed?{round:round,mark:parsed.mark,time:parsed.mark,seconds:parsed.seconds,totalSeconds:(roundNumber-1)*300+parsed.seconds}:{round:round,mark:"",time:"",seconds:0,totalSeconds:0};
  if(!draft.fastestFinish.mark)draft.message="Choose a Fastest Finish elapsed time.";else draft.message="";
  draft.error=false;
  renderAdminEntries();
};
window.adminSetDraftFastestMark=function(encodedDocId,value,format){
  var docId=decodeURIComponent(String(encodedDocId||"")), entry=adminEntryByDocId(docId), draft=adminDraftForEntry(entry);
  if(!draft||isLocked())return;
  var parsed=adminParseFastestTime(value);
  if(!parsed){draft.fastestFinish=draft.fastestFinish||{round:"r1"};draft.message="Use a Fastest Finish elapsed time from 0:00 through 5:00.";draft.error=true;renderAdminEntries();return;}
  var round=(draft.fastestFinish&&draft.fastestFinish.round)||"r1", roundNumber=parseInt(round.replace("r",""),10)||1;
  draft.fastestFinish={round:round,mark:parsed.mark,time:parsed.mark,seconds:parsed.seconds,totalSeconds:(roundNumber-1)*300+parsed.seconds};
  draft.message="";draft.error=false;
  renderAdminEntries();
};
window.saveAdminAssistedPicks=async function(encodedDocId){
  var docId=decodeURIComponent(String(encodedDocId||"")), entry=adminEntryByDocId(docId), draft=adminDraftForEntry(entry);
  if(!entry||!draft)return;
  if(isLocked()){draft.message="Picks are locked. Admin-assisted editing is closed for this pool.";draft.error=true;renderAdminEntries();return;}
  var problems=adminDraftCompleteProblems(draft);
  if(problems.length){draft.message="Finish before saving: "+problems.slice(0,5).join(", ")+(problems.length>5?", and "+(problems.length-5)+" more":"")+".";draft.error=true;renderAdminEntries();return;}
  var now=new Date().toISOString(), props=Object.assign({},entry.props||{},getEntryProps(entry)||{});
  props.timings=adminCloneMap(draft.timings);
  props.overs=adminCloneMap(draft.overs);
  props.lock=normalizeLockValue(draft.lock)||"";
  props.fastestFinish=draft.fastestFinish?Object.assign({},draft.fastestFinish):null;
  props.fastestFinishTiebreaker=draft.fastestFinish?Object.assign({},draft.fastestFinish):null;
  var updatedEntry=Object.assign({},entry,{
    picks:adminCloneMap(draft.picks),
    methods:adminCloneMap(draft.methods),
    props:props,
    fastestFinishTiebreaker:props.fastestFinishTiebreaker,
    updatedAt:now,
    adminEdited:{at:now,byUid:(currentUser&&currentUser.uid)||"",byName:(currentMember&&currentMember.name)||"Pool Admin"}
  });
  try{
    draft.message="Saving picks for "+(entry.name||"player")+"...";
    draft.error=false;
    renderAdminEntries();
    await setDoc(poolDoc("entries",docId),updatedEntry,{merge:true});
    if(typeof rememberLocalEntryOverride==="function")rememberLocalEntryOverride(updatedEntry);
    if(typeof syncEntryToAllEntries==="function")syncEntryToAllEntries(updatedEntry);
    if(myEntry&&String(myEntry.docId||"")===String(docId)){
      myEntry=updatedEntry;
      loadMyEntry(updatedEntry);
    }
    var savedDraft=adminDraftForEntry(updatedEntry);
    savedDraft.open=true;
    savedDraft.message="Picks updated for "+(updatedEntry.name||"player")+".";
    savedDraft.error=false;
    renderAdminEntries();
    renderAllPicks();renderLeaderboard();renderMySummary();
  }catch(e){
    console.error(e);
    draft.message="Could not save picks for "+(entry.name||"player")+". Please try again.";
    draft.error=true;
    renderAdminEntries();
  }
};

window.toggleEdit=function(docId){
  var p=document.getElementById("epanel_"+docId), b=document.getElementById("ebtn_"+docId);
  if(!p)return;
  p.classList.toggle("open");
  b.textContent=p.classList.contains("open")?"✕ Close":"✏️ Edit";
};

window.saveEntry=async function(docId){
  if(!currentPoolFeatureEnabled("allowAdminScoringEdits")){
    var panel=document.getElementById("epanel_"+docId);
    var note=panel&&panel.querySelector(".admin-locked-inline-note");
    if(note)note.textContent=lockedFeatureMessage();
    return;
  }
  var entry=allEntries.find(function(e){return e.docId===docId;});
  if(!entry)return;
  var newPicks=Object.assign({},entry.picks);
  fights.forEach(function(f){
    var sel=document.getElementById("esel_"+docId+"_"+f.id);
    if(sel&&sel.value)newPicks[f.id]=parseInt(sel.value);
  });
  var newMethods=Object.assign({},(entry.methods||{}));
  fights.filter(function(f){return f.bonus;}).forEach(function(f){
    var sel=document.getElementById("emeth_"+docId+"_"+f.id);
    if(sel&&sel.value)newMethods[f.id]=sel.value;
  });
  var updatedEntry=Object.assign({},entry,{picks:newPicks,methods:newMethods});
  await setDoc(poolDoc("entries",docId),updatedEntry);
  if(docId===myDocId)loadMyEntry(updatedEntry);
  var p=document.getElementById("epanel_"+docId), b=document.getElementById("ebtn_"+docId);
  if(p)p.classList.remove("open");
  if(b)b.textContent="✏️ Edit";
};

window.deleteEntry=async function(docId,name){
  if(!confirm("Delete entry for "+name+"?"))return;
  try{
    var entry=allEntries.find(function(e){return String(e.docId||"")===String(docId);})||{};
    var ids=[docId,entry.memberId,entry.authUid,entry.uid].filter(Boolean).map(String);
    await deleteDoc(poolDoc("entries",docId));
    await Promise.all(ids.map(async function(id){
      try{await deleteDoc(poolDoc("members",id));}catch(e){}
    }));
    if(entry.memberId||entry.authUid||entry.uid){
      var uid=entry.memberId||entry.authUid||entry.uid;
      var now=new Date().toISOString();
      var patch={lastPoolAction:{type:"removed_by_admin",poolId:currentPoolId,poolName:displayPoolName(currentPoolId),at:now},updatedAt:now};
      patch["joinedPools."+currentPoolId]=deleteField();
      try{await updateDoc(userRootDoc(uid),patch);}catch(e){console.warn("Could not remove pool from user saved pools",e);}
    }
    await addPoolNotice("member_removed_by_admin",currentPoolId,{uid:entry.memberId||entry.authUid||entry.uid||docId,memberId:entry.memberId||docId,email:entry.email||"",name:name||entry.name||"",poolName:displayPoolName(currentPoolId)});
    if(docId===myDocId){
      try{localStorage.removeItem(poolStorageKey('myDocId'));}catch(e){}
      myDocId=null; myEntry=null;
      document.getElementById("myTab").style.display="none";
      renderMySummary();
    }
  }catch(e){alert("Error deleting.");console.error(e);}
};

window.setResult=async function(fid,field,val){
  if(!fightResults[fid])fightResults[fid]={};
  var f=fights.find(function(x){return x.id===fid;});
  if(field==="method"){
    fightResults[fid][field]=val;
    if(val==="dec")fightResults[fid].timing="distance";
    else if((val==="ko"||val==="sub")&&fightResults[fid].timing==="distance")delete fightResults[fid].timing;
  }else if(field==="timing"){
    var m=fightResults[fid].method;
    if(!m||!isTimingValidForMethod(f,m,val))return;
    fightResults[fid][field]=val;
  }else if(field==="stoppageMark"){
    if(fightResults[fid].method==="dec"||fightResults[fid].timing==="distance"||fightResults[fid].wentToDecision){
      delete fightResults[fid].stoppageMark;
    }else{
      var mark=formatStoppageMark(val);
      if(mark)fightResults[fid].stoppageMark=mark;
      else delete fightResults[fid].stoppageMark;
    }
  }else{
    fightResults[fid][field]=val;
  }
  fightResults[fid]=normalizeFightResultData(f,fightResults[fid]);
  await setDoc(poolDoc("results","fights"),fightResults);
  renderAdminFights(); renderLeaderboard(); renderAllPicks(); renderMySummary();
};

window.clearResult=async function(fid){
  if(fightResults[fid]){delete fightResults[fid].winner; delete fightResults[fid].method; delete fightResults[fid].gloves; delete fightResults[fid].timing; delete fightResults[fid].stoppageMark; delete fightResults[fid].wentToDecision; delete fightResults[fid].overUnderLine; delete fightResults[fid].overUnderResult; delete fightResults[fid].finalScoringResult;}
  await setDoc(poolDoc("results","fights"),fightResults);
  renderAdminFights(); renderLeaderboard(); renderAllPicks(); renderMySummary();
};

function archiveEventCompletionWarning(){
  var complete=typeof doneCount==="function"?doneCount():0, total=(fights||[]).length;
  if(total&&complete<total){
    return '<div class="admin-locked-inline-note">Some fights may still be pending. You can save a snapshot now, but final history is best saved after all results are complete.</div>';
  }
  return "";
}
function archiveEventStatusHtml(){
  var saved=window.__completedEventSnapshotLastSaved||"";
  if(!saved)return '<div class="admin-key-note" id="adminArchiveStatus">No completed event snapshot has been saved from this browser session yet.</div>';
  return '<div class="admin-key-note" id="adminArchiveStatus">Snapshot saved for this event. Last saved: '+escapeHtml(pickSaveStamp(saved))+'</div>';
}
function nextPoolRolloverEvent(){
  var active=getActivePoolEvent(currentPoolMeta)||getDefaultActiveEvent();
  var activeDate=startPoolEventDateValue(active);
  var list=Object.keys(EVENTS||{}).map(function(id){return EVENTS[id];}).filter(function(event){
    if(!event||event.eventId===active.eventId)return false;
    var status=normalizeEventStatus(event.eventStatus);
    if(["open_for_picks","live","completed","archived"].indexOf(status)>-1)return false;
    if(event.startPoolHidden)return false;
    if(!Array.isArray(event.fights)||!event.fights.length)return false;
    var d=startPoolEventDateValue(event);
    return !activeDate||!d||d.getTime()>=activeDate.getTime();
  }).sort(function(a,b){
    var ad=startPoolEventDateValue(a), bd=startPoolEventDateValue(b);
    var diff=(ad?ad.getTime():Infinity)-(bd?bd.getTime():Infinity);
    if(diff)return diff;
    return String(a&&a.eventName||"").localeCompare(String(b&&b.eventName||""));
  });
  return list[0]||null;
}
function rolloverNextEventHtml(next){
  if(!next){
    return '<div class="admin-key-note">No ready next event is loaded yet. Add fights to the next card in Creator Tools, save the card, then come back here to open it for this same pool.</div>';
  }
  var name=next.eventName||next.eventLabel||"Next Event";
  next=normalizeFreedom250EventTime(next);
  var date=next.eventDate?next.eventDate+(next.eventTime?" · "+next.eventTime+(next.eventTimeZone?" "+next.eventTimeZone:""):""):"Date pending";
  return '<div class="admin-key-note"><strong>Next ready event:</strong> '+escapeHtml(name)+'<br><span style="color:#a3a3a3">'+escapeHtml(date)+' · '+(Array.isArray(next.fights)?next.fights.length:0)+' fights loaded</span></div>'
    +'<div class="admin-key-note">This keeps the same pool and carries your pool settings forward. It clears current event picks, results, and live chat so the new card starts clean.</div>'
    +'<div class="admin-score-actions"><button class="btn-primary" id="openNextPoolEventBtn" type="button" onclick="openNextPoolEventForPicks()">Save Snapshot & Open Next Event</button></div>';
}
function renderAdminArchiveEvent(){
  var el=document.getElementById("adminArchiveEventPanel");
  if(!el)return;
  var event=getActivePoolEvent(currentPoolMeta)||getDefaultActiveEvent();
  var eventName=(event&&event.eventName)||(event&&event.eventLabel)||DEFAULT_EVENT_NAME;
  var next=nextPoolRolloverEvent();
  el.innerHTML='<div class="admin-score-card"><div class="admin-score-title"><div>Finalize / Archive Event<div class="admin-score-sub">Save a completed snapshot of this event before moving your pool to a future event. This preserves the final leaderboard, entries, results, scoring settings, and winner history.</div></div></div>'
    +'<div class="admin-key-note"><strong>Current event:</strong> '+escapeHtml(eventName)+'</div>'
    +'<div class="admin-key-note">Saving a snapshot by itself does not clear picks, entries, results, or move the pool. Opening the next event does.</div>'
    +archiveEventCompletionWarning()
    +archiveEventStatusHtml()
    +'<div class="admin-score-actions"><button class="btn-primary" id="saveCompletedEventSnapshotBtn" type="button" onclick="saveAdminCompletedEventSnapshot()">Save Completed Event Snapshot</button></div>'
    +rolloverNextEventHtml(next)
    +'<div class="admin-score-msg" id="adminArchiveMsg"></div></div>';
  if(typeof loadPoolEventHistory==="function"){
    var activeId=poolEventSnapshotId(event);
    loadPoolEventHistory().then(function(items){
      var match=(items||[]).find(function(item){return poolEventSnapshotId(item)===activeId;});
      var status=document.getElementById("adminArchiveStatus");
      if(status&&match){
        var stamp=match.updatedAt||match.archivedAt||match.completedAt||"";
        status.textContent="Snapshot saved for this event"+(stamp?". Last saved: "+pickSaveStamp(stamp):".");
      }
    }).catch(function(){});
  }
}
window.openNextPoolEventForPicks=async function(){
  var btn=document.getElementById("openNextPoolEventBtn"), msg=document.getElementById("adminArchiveMsg");
  var active=getActivePoolEvent(currentPoolMeta)||getDefaultActiveEvent();
  var next=nextPoolRolloverEvent();
  if(!next){if(msg){msg.className="admin-score-msg bad";msg.textContent="No ready next event is loaded yet.";}return;}
  if(localDemoMode){if(msg){msg.className="admin-score-msg bad";msg.textContent="Demo mode keeps Firebase disabled. Rollover needs Firebase.";}return;}
  if(!isPoolAdmin()){if(msg){msg.className="admin-score-msg bad";msg.textContent="Only this pool's admin can open the next event.";}return;}
  var activeName=(active&&active.eventName)||(active&&active.eventLabel)||"current event";
  var nextName=next.eventName||next.eventLabel||"next event";
  if(!confirm("Open "+nextName+" for this same pool? This saves "+activeName+" to history, clears current picks/results/chat, and keeps pool settings."))return;
  try{
    if(btn){btn.disabled=true;btn.textContent="Opening Next Event...";}
    if(msg){msg.className="admin-score-msg";msg.textContent="Saving current event history...";}
    var now=new Date().toISOString();
    var snapshot=buildCompletedEventSnapshot(active,{completedAt:now,archivedAt:now});
    await saveCompletedEventSnapshot(snapshot);
    window.__completedEventSnapshotLastSaved=snapshot.updatedAt||now;
    if(msg)msg.textContent="Clearing current event picks, results, and chat...";
    await Promise.all([
      deleteCollectionDocs(poolCollection("entries")),
      deleteCollectionDocs(poolCollection("results")),
      deleteCollectionDocs(poolCollection("chat")),
      deleteCollectionDocs(poolCollection("typing")),
      deleteCollectionDocs(poolCollection("presence"))
    ]);
    var activeId=poolEventSnapshotId(active), nextId=next.eventId||next.poolEventId;
    var poolEvents=Object.assign({},(currentPoolMeta&&currentPoolMeta.poolEvents)||{});
    poolEvents[activeId]=Object.assign({},poolEvents[activeId]||{},active,{
      poolEventId:activeId,
      eventId:active.eventId||activeId,
      eventName:activeName,
      eventLabel:active.eventLabel||activeName,
      eventStatus:"archived",
      poolEventStatus:"archived",
      completedAt:now,
      archivedAt:now,
      updatedAt:now
    });
    poolEvents[nextId]=Object.assign({},poolEvents[nextId]||{},next,{
      poolEventId:nextId,
      eventId:next.eventId||nextId,
      eventName:nextName,
      eventLabel:next.eventLabel||nextName,
      eventStatus:"open_for_picks",
      poolEventStatus:"open_for_picks",
      openedAt:now,
      updatedAt:now
    });
    var completed=Array.isArray(currentPoolMeta.completedPoolEventIds)?currentPoolMeta.completedPoolEventIds.slice():[];
    if(completed.indexOf(activeId)<0)completed.push(activeId);
    var rootPatch={
      eventId:next.eventId||nextId,
      eventName:nextName,
      eventLabel:next.eventLabel||nextName,
      eventStatus:"open_for_picks",
      poolEventStatus:"open_for_picks",
      activePoolEventId:nextId,
      completedPoolEventIds:completed,
      poolEvents:poolEvents,
      updatedAt:now
    };
    await setDoc(poolRootDoc(),rootPatch,{merge:true});
    await Promise.all([
      setDoc(poolDoc("settings","lock"),{picksLocked:false,picksForceOpen:false,updatedAt:now},{merge:true}),
      setDoc(poolDoc("settings","visibility"),{picksVisible:true,updatedAt:now},{merge:true})
    ]);
    if(EVENTS[active.eventId])EVENTS[active.eventId]=Object.assign({},EVENTS[active.eventId],{eventStatus:"archived",startPoolHidden:true});
    if(EVENTS[next.eventId])EVENTS[next.eventId]=Object.assign({},EVENTS[next.eventId],next,{eventStatus:"open_for_picks",startPoolHidden:false});
    setActiveEventId(next.eventId||nextId);
    currentPoolMeta=Object.assign({},currentPoolMeta||{},rootPatch);
    fights.splice.apply(fights,[0,fights.length].concat(next.fights||[]));
    allEntries=[]; myEntry=null; myDocId=null; fightResults={}; chatMessages=[]; typingUsers=[]; presenceUsers=[];
    try{localStorage.removeItem(poolStorageKey("myDocId"));localStorage.setItem(poolStorageKey("chatLastSeenAt"),String(Date.now()));}catch(e){}
    await updateSavedPoolEventForEveryone(next,"Open For Picks");
    if(msg){msg.className="admin-score-msg good";msg.textContent=nextName+" is open for picks. Same pool, clean event data, settings carried forward.";}
    renderPoolShell(); renderFights(); refreshPickUI(); updateProgress(); updateDeadline(); renderLeaderboard(); renderAllPicks(); renderMySummary(); renderChat(); renderAdminArchiveEvent(); renderUpcomingEvents();
  }catch(e){
    console.error(e);
    if(msg){msg.className="admin-score-msg bad";msg.textContent="Could not open the next event. Nothing else was deployed or pushed.";}
  }finally{
    btn=document.getElementById("openNextPoolEventBtn");
    if(btn){btn.disabled=false;btn.textContent="Save Snapshot & Open Next Event";}
  }
};
window.saveAdminCompletedEventSnapshot=async function(){
  var btn=document.getElementById("saveCompletedEventSnapshotBtn"), msg=document.getElementById("adminArchiveMsg");
  try{
    if(btn){btn.disabled=true;btn.textContent="Saving Snapshot...";}
    if(msg){msg.className="admin-score-msg";msg.textContent="Saving completed event snapshot...";}
    var snapshot=buildCompletedEventSnapshot();
    await saveCompletedEventSnapshot(snapshot);
    window.__completedEventSnapshotLastSaved=snapshot.updatedAt||new Date().toISOString();
    if(msg){msg.className="admin-score-msg good";msg.textContent="Completed event snapshot saved. Your current pool data was not cleared.";}
    renderAdminArchiveEvent();
    var success=document.getElementById("adminArchiveMsg");
    if(success){success.className="admin-score-msg good";success.textContent="Completed event snapshot saved. Your current pool data was not cleared.";}
  }catch(e){
    console.error(e);
    if(msg){msg.className="admin-score-msg bad";msg.textContent="Could not save completed event snapshot. Please try again.";}
  }finally{
    btn=document.getElementById("saveCompletedEventSnapshotBtn");
    if(btn){btn.disabled=false;btn.textContent="Save Completed Event Snapshot";}
  }
};

window.toggleAdminSection=function(id){
  var el=document.getElementById(id);
  if(!el)return;
  el.classList.toggle('open');
  try{localStorage.setItem(poolStorageKey('adminSection_'+id), el.classList.contains('open') ? '1' : '0');}catch(e){}
}
window.initAdminSections=function(){
  ['adminSectionFee','adminSectionScoring','adminSectionVisibility','adminSectionLock','adminSectionResults','adminSectionAddEntry','adminSectionChat','adminSectionEntries'].forEach(function(id){
    var el=document.getElementById(id);
    if(!el)return;
    var saved=null;
    try{saved=localStorage.getItem(poolStorageKey('adminSection_'+id));}catch(e){}
    if(saved==='1')el.classList.add('open');
    else if(saved==='0')el.classList.remove('open');
  });
}

function unlockAdminPanel(){
  var lock=document.getElementById("adminLock"),panel=document.getElementById("adminPanel");
  if(lock)lock.style.display="none";
  if(panel)panel.style.display="block";
  if(currentTab==="admin"){
    startFinancialSettingsListeners();
    startGlobalFighterLinesListener();
  }
  ensureAdminKeyForHost().then(renderAdminKeyPanel).catch(function(){renderAdminKeyPanel();});
  renderAdminFights(); renderAdminEntries(); renderAdminAddEntry(); renderAdminScoring(); renderAdminArchiveEvent(); renderChatControls(); renderAdminChatMessages(); renderAdminNotifications(); renderAdminTransferPanel();
  var toggle=document.getElementById("picksVisibleToggle");
  if(toggle)toggle.checked=picksVisible;
  var lockToggle=document.getElementById("picksLockedToggle");
  if(lockToggle)lockToggle.checked=picksLocked;
  var lockStatus=document.getElementById("lockStatus");
  if(lockStatus)lockStatus.textContent=picksLocked?"Locked by Admin — official line freeze is still "+eventLockDisplay(currentPoolMeta):"Auto-locks at "+eventLockDisplay(currentPoolMeta);
  syncPayoutInputs();
}

function lockAdminPanel(){
  var lock=document.getElementById("adminLock"),panel=document.getElementById("adminPanel");
  if(lock)lock.style.display="";
  if(panel)panel.style.display="none";
}

function syncAdminAccess(){
  renderPoolShell();
  renderAdminWelcome();
  renderJoinRequests();
  if(isPoolAdmin()||adminKeyUnlocked)unlockAdminPanel();
  else lockAdminPanel();
  if((window.location.hash||"").toLowerCase()==="#quick-setup"&&(isPoolAdmin()||adminKeyUnlocked)){
    setTimeout(function(){showQuickPoolSetup({preserveHash:true});},0);
  }
}
