function poolTabFromHash(){
  if(!invitedPoolId)return "";
  var hash=String(window.location.hash||"").replace(/^#/,"").toLowerCase();
  var aliases={"my-picks":"mine","all-picks":"allpicks","invite-friends":"pool","account":"profile","upcoming-events":"nextevent","live-chat":"chat"};
  var tab=aliases[hash]||hash;
  return document.getElementById("view-"+tab)?tab:"";
}
window.restorePoolTabFromHash=function(opts){
  var tab=poolTabFromHash();
  if(!tab)return false;
  setLandingRouteActive(false);
  markPoolExperienceActive(tab,{updateHash:false});
  if(document.body)document.body.classList.remove("landing-route-active");
  var btn=document.querySelector(".tab[onclick*=\"'"+tab+"'\"]")||document.querySelector('.tab[onclick*="\\"'+tab+'\\""]')||document.querySelector(".tab");
  if(typeof window.showTab==="function")window.showTab(tab,btn);
  else{
    document.querySelectorAll(".view").forEach(function(v){v.classList.remove("active");});
    var view=document.getElementById("view-"+tab);
    if(view)view.classList.add("active");
    document.querySelectorAll(".tab").forEach(function(b){b.classList.remove("active");});
    if(btn)btn.classList.add("active");
    currentTab=tab;
  }
  if(!opts||opts.clearBoot!==false)document.body.classList.remove("pool-route-boot");
  return true;
};
