    avgFinish:currentRank||0,
    avgPoints:currentScore||0,
    fighterCorrect:currentStats.fighterCorrect||0,
    fighterTotal:currentStats.completed||0,
    methodCorrect:currentStats.methodCorrect||0,
    methodTotal:currentStats.methodTotal||0,
    timingCorrect:currentStats.timingCorrect||0,
    timingTotal:currentStats.timingTotal||0,
    overCorrect:currentStats.overCorrect||0,
    overTotal:currentStats.overTotal||0,
    lockHits:lockHits,
    bestScore:currentScore||0,
    oneFightPts:bestFight.points,
