window.cycleProfileBanner=function(step){
  if(!currentPoolFeatureEnabled("allowEditableBanners"))return;
  var buttons=[].slice.call(document.querySelectorAll(".profile-banner-choice"));
  var visible=buttons.map(function(btn){return btn.getAttribute("data-banner-key");}).filter(Boolean);
  var keys=visible.length?visible:bannerKeys();
  if(!keys.length)return;
  var active=window.__profileBannerCycleActive||getPreferredBanner();
  var activeBtn=document.querySelector(".profile-banner-choice.active");
  if(!window.__profileBannerCycleActive&&activeBtn&&activeBtn.getAttribute("data-banner-key"))active=activeBtn.getAttribute("data-banner-key");
  var idx=keys.indexOf(active);
  if(idx<0)idx=0;
  var next=(idx+step+keys.length)%keys.length;
  var nextKey=keys[next];
  window.__profileBannerCycleActive=nextKey;
  window.__profileBannerPickerOpen=true;
  window.__profileBannerCycleTarget=nextKey;
  if(window.__profileBannerCycleTimer)clearTimeout(window.__profileBannerCycleTimer);
  window.__profileBannerWindowScroll={x:window.pageXOffset||document.documentElement.scrollLeft||0,y:window.pageYOffset||document.documentElement.scrollTop||0};
  var grid=document.getElementById("profileBannerGrid");
  if(grid)window.__profileBannerPickerScroll=grid.scrollTop;
  try{refreshProfileBannerPickerUI(nextKey);}catch(e){}
  try{localStorage.setItem(poolStorageKey('profileBanner'),nextKey);}catch(e){}
  if(myEntry){
    myEntry=Object.assign({},myEntry,{profileBanner:nextKey});
    allEntries=allEntries.map(function(e){return e.docId===myEntry.docId?Object.assign({},e,{profileBanner:nextKey}):e;});
    forceEntryBannerBackground(document.querySelector("#mineContent .my-banner"),myEntry);
    decorateMyChampionBanner();
    window.__profileBannerCycleSaveId=(window.__profileBannerCycleSaveId||0)+1;
    if(!localDemoMode)setDoc(poolDoc("entries",myEntry.docId),myEntry).catch(function(e){console.error(e);});
  }
};
