function entryIdentity(e){
  return String((e&&(e.docId||e.memberId||e.email||e.name))||"");
}
function currentEntryIdentityCandidates(){
  var ids=[];
  function add(v){if(v!==undefined&&v!==null&&String(v).trim())ids.push(String(v));}
  add(myDocId);add(currentMemberId);
  if(currentUser){add(currentUser.uid);}
  if(currentMember){
    ["memberId","authUid","uid","userId","docId"].forEach(function(k){add(currentMember[k]);});
  }
  if(currentAccountData){
    ["uid","memberId","authUid","userId"].forEach(function(k){add(currentAccountData[k]);});
  }
  if(isPoolAdmin()&&currentPoolMeta){
    ["ownerUid","adminUid","createdBy","hostId"].forEach(function(k){add(currentPoolMeta[k]);});
  }
  return ids.filter(function(v,i,a){return a.indexOf(v)===i;});
}
function entryMatchesCurrentMember(e,allowAdminFallback){
  if(!e)return false;
  var ids=currentEntryIdentityCandidates();
  var vals=[e.docId,e.memberId,e.authUid,e.uid,e.userId,e.playerId,e.ownerUid,e.adminUid,e.hostId,e.createdBy].filter(Boolean).map(String);
  if(vals.some(function(v){return ids.indexOf(v)>-1;}))return true;
  var email=((currentMember&&currentMember.email)||(currentUser&&currentUser.email)||(currentAccountData&&currentAccountData.email)||"").trim().toLowerCase();
  if(email&&String(e.email||"").trim().toLowerCase()===email)return true;
  if(allowAdminFallback&&isPoolAdmin()){
    var adminEmail=String((currentPoolMeta&&(currentPoolMeta.ownerEmail||currentPoolMeta.adminEmail))||"").trim().toLowerCase();
    if(adminEmail&&String(e.email||"").trim().toLowerCase()===adminEmail)return true;
    var adminNames=[currentPoolMeta&&currentPoolMeta.ownerName,currentPoolMeta&&currentPoolMeta.adminName,currentPoolMeta&&currentPoolMeta.ownerFullName,currentPoolMeta&&currentPoolMeta.hostName].map(cleanEntryName).filter(Boolean);
    if(adminNames.length&&adminNames.indexOf(cleanEntryName(e.name))>-1)return true;
  }
  var names=[];
  if(currentMember){
    if(currentMember.username)names.push(currentMember.username);
    if(currentMember.name)names.push(currentMember.name);
    if(currentMember.fullName)names.push(currentMember.fullName);
  }
  if(currentAccountData){
    if(currentAccountData.username)names.push(currentAccountData.username);
    if(currentAccountData.name)names.push(currentAccountData.name);
    if(currentAccountData.fullName)names.push(currentAccountData.fullName);
  }
  var cleaned=names.map(cleanEntryName).filter(Boolean);
  return !!(cleaned.length&&cleaned.indexOf(cleanEntryName(e.name))>-1);
}
function currentMemberEntry(){
  if(!allEntries||!allEntries.length)return null;
  var directHit=allEntries.find(function(e){return entryMatchesCurrentMember(e,true);});
  if(directHit)return directHit;
  if(shouldUseLocalHostedPreviewProfile()){
    var localEntries=readLocalHostedPreviewEntries();
    var localHit=localEntries.find(function(e){return entryMatchesCurrentMember(e,true);});
    if(localHit)return localHit;
    if(isPoolAdmin()&&localEntries.length===1)return localEntries[0];
  }
  return null;
}
function syncEntryToAllEntries(entry){
  if(!entry||!entry.docId)return;
  function keyList(e){
    var keys=[];
    function add(v,prefix){if(v!==undefined&&v!==null&&String(v).trim())keys.push((prefix||"")+String(v).trim().toLowerCase());}
    add(e.docId,"doc:");
    add(e.memberId,"id:");
    add(e.authUid,"id:");
    add(e.uid,"id:");
    add(e.userId,"id:");
    add(e.email,"email:");
    add(cleanEntryName(e.name),"name:");
    return keys.filter(function(v,i,a){return a.indexOf(v)===i;});
  }
  var entryKeys=keyList(entry);
  function matchesEntry(existing){
    if(!existing)return false;
    var existingKeys=keyList(existing);
    if(existingKeys.some(function(k){return entryKeys.indexOf(k)>-1;}))return true;
    try{return entryMatchesCurrentMember(existing,true)&&entryMatchesCurrentMember(entry,true);}catch(e){return false;}
  }
  var found=false;
  allEntries=(allEntries||[]).map(function(existing){
    if(matchesEntry(existing)){found=true;return Object.assign({},existing,entry,{props:Object.assign({},existing.props||{},entry.props||{})});}
    return existing;
  });
  if(!found)allEntries.push(entry);
  window.allEntries=allEntries;
  if(allEntries.length)window.__lastKnownAllPicksEntries=allEntries.slice();
}
function rememberLocalEntryOverride(entry){
  if(!entry)return;
  window.__localEntryOverrides=window.__localEntryOverrides||[];
  var copy=Object.assign({},entry,{props:Object.assign({},entry.props||{})});
  var replaced=false;
  window.__localEntryOverrides=window.__localEntryOverrides.map(function(existing){
    var before=allEntries;
    allEntries=[existing];
    var match=false;
    try{syncEntryToAllEntries(copy);match=allEntries[0]!==existing;}catch(e){match=false;}
    allEntries=before;
    if(match){replaced=true;return copy;}
    return existing;
  });
  if(!replaced)window.__localEntryOverrides.push(copy);
}
function applyLocalEntryOverrides(entries){
  var overrides=window.__localEntryOverrides||[];
  if(!overrides.length)return entries;
  var merged=(entries||[]).slice();
  overrides.forEach(function(override){
    var before=allEntries;
    allEntries=merged;
    syncEntryToAllEntries(override);
    merged=allEntries;
    allEntries=before;
  });
  return merged;
}
