function randomChoice(arr){return arr[Math.floor(Math.random()*arr.length)];}
window.randomizeEntry=async function(docId){
  if(!adminPrototypeToolsEnabled())return;
  var entry=allEntries.find(function(e){return e.docId===docId;});
  if(!entry)return;
  if(!confirm("Randomize all picks for "+(entry.name||"this entry")+"? This will overwrite their current picks for testing."))return;
  var newPicks={}, newMethods={}, pr=getEntryProps(entry), newGloves=Object.assign({},pr.gloves||{}), newTimings=Object.assign({},pr.timings||{});
  fights.forEach(function(f){
    var side=Math.random()<0.5?1:2;
    newPicks[f.id]=side;
    if(f.bonus){
      var m=randomChoice(["ko","sub","dec"]);
      newMethods[f.id]=m;
      if(f.timingEnabled){newTimings[f.id]=(m==="dec")?"distance":randomChoice(roundOptionsForFight(f));}
    }else if(f.timingEnabled){
      newTimings[f.id]=randomChoice(timingOptionsForFight(f));
    }
    if(f.glovesEnabled){newGloves[f.id]=Math.random()<0.5?"yes":"no";}
  });
  var updated=Object.assign({},entry,{picks:newPicks,methods:newMethods,props:Object.assign({},pr,{gloves:newGloves,timings:newTimings}),profileBanner:entryBanner(entry)});
  try{await setDoc(poolDoc("entries",docId),updated);if(docId===myDocId)loadMyEntry(updated);renderLeaderboard();renderAllPicks();renderAdminEntries();}
  catch(e){alert("Could not randomize picks.");console.error(e);}
};

function makeLocalDemoEntry(seed,name,profileBanner){
  var now=new Date().toISOString(), demoPicks={}, demoMethods={}, demoTimings={}, demoOvers={};
  fights.forEach(function(f,i){
    var side=((i+seed)%2)+1;
    demoPicks[f.id]=side;
    if(f.bonus)demoMethods[f.id]=["ko","sub","dec"][(i+seed)%3];
    if(f.timingEnabled){
      var m=demoMethods[f.id]||"ko";
      demoTimings[f.id]=m==="dec"?"distance":roundOptionsForFight(f)[(i+seed)%roundOptionsForFight(f).length];
    }
    if(f.overUnderEnabled)demoOvers[f.id]=(i+seed)%2?"over":"under";
  });
  var lockFight=fights.find(function(f){return demoPicks[f.id];})||fights[0];
  var lock=lockFight?lockFight.id+":"+demoPicks[lockFight.id]:"";
  return {
    docId:"demo-entry-"+seed,
    memberId:"demo-entry-"+seed,
    authUid:"demo-entry-"+seed,
    uid:"demo-entry-"+seed,
    poolId:currentPoolId,
    eventId:DEFAULT_EVENT_ID,
    poolEventId:DEFAULT_EVENT_ID,
    poolEventStatus:"open_for_picks",
    name:name,
    email:"demo"+seed+"@fightlocks.local",
    picks:demoPicks,
    methods:demoMethods,
    props:{timings:demoTimings,overs:demoOvers,lock:lock,fastestFinish:{round:"r1",mark:"2:14",time:"2:14",seconds:134,totalSeconds:134}},
    profileBanner:profileBanner||"",
    submittedAt:now,
    updatedAt:now,
    localOnly:true,
    demoOnly:true
  };
}
