  allEntries=mergeLocalHostedPreviewEntries(withLinkedInDemoEntries(snap.docs.map(function(d){
    var data=d.data()||{};
    if(!data.docId)data=Object.assign({},data,{docId:d.id});
    return data;
  })));
  allEntries=applyLocalEntryOverrides(allEntries);
  window.allEntries=allEntries;
  if(allEntries.length)window.__lastKnownAllPicksEntries=allEntries.slice();
  if(!myDocId){
    var memberEntry=currentMemberEntry();
    if(memberEntry)loadMyEntry(memberEntry);
  }
