  fightResults=snap.exists()?snap.data():{};
  fights.forEach(function(f){if(fightResults[f.id])fightResults[f.id]=normalizeFightResultData(f,fightResults[f.id]);});
  try{renderLeaderboard();}catch(e){console.warn("Could not render leaderboard after result update",e);}
