let globalFighterLinesLoaded=false;
let globalFighterLinesLoading=null;
let globalFighterLinesListenerStarted=false;
let globalFighterLinesUnsub=null;
var SPORTSDATA_IMPORTS_ENABLED=false;
let globalSportsDataEventsLoaded=false;
let globalSportsDataEventsLoading=null;
function loadGlobalSportsDataEventsOnce(){
  if(!SPORTSDATA_IMPORTS_ENABLED)return Promise.resolve(false);
  if(firebaseDisabled)return Promise.resolve(false);
  if(globalSportsDataEventsLoaded)return Promise.resolve(true);
  if(globalSportsDataEventsLoading)return globalSportsDataEventsLoading;
  globalSportsDataEventsLoading=getDoc(globalSportsDataEventsDoc()).then(function(snap){
    if(snap&&snap.exists()){
      applySportsDataImportedEvents(snap.data()||{});
      if(godModeRequested)setGodEventStatus("Latest SportsDataIO drafts loaded.");
    }
    globalSportsDataEventsLoaded=true;
    return true;
  }).catch(function(e){
    listenerDebug("sportsdata-events-load-failed",{message:e&&e.message||String(e)});
    return false;
  }).finally(function(){
    globalSportsDataEventsLoading=null;
  });
  return globalSportsDataEventsLoading;
}
function applyGlobalFighterLinesSnapshot(snap){
  if(snap&&snap.exists()){
    globalFighterLines=normalizeOddsPayload(snap.data()||{});
    applyGlobalLinesRefresh();
    if(godModeRequested)renderGodOddsPanel();
  }
}
function loadGlobalFighterLinesOnce(){
  if(firebaseDisabled)return Promise.resolve(false);
  if(globalFighterLinesLoaded)return Promise.resolve(true);
  if(globalFighterLinesLoading)return globalFighterLinesLoading;
  globalFighterLinesLoading=getDoc(globalFighterLinesDoc()).then(function(snap){
    applyGlobalFighterLinesSnapshot(snap);
    globalFighterLinesLoaded=true;
    return true;
  }).catch(function(e){
    listenerDebug("fighter-lines-one-time-load-failed",{message:e&&e.message||String(e)});
    return false;
  }).finally(function(){
    globalFighterLinesLoading=null;
  });
  return globalFighterLinesLoading;
}
function startGlobalFighterLinesListener(){
  if(globalFighterLinesListenerStarted)return;
  globalFighterLinesListenerStarted=true;
  listenerDebug("fighter-lines-listener-start");
  globalFighterLinesUnsub=liveSnapshot(function(){return globalFighterLinesDoc();},function(snap){
    applyGlobalFighterLinesSnapshot(snap);
  });
}
loadGlobalFighterLinesOnce();
if(SPORTSDATA_IMPORTS_ENABLED)loadGlobalSportsDataEventsOnce();

