function startChatListeners(){
  if(chatListenersStarted){listenerDebug("chat-listeners-skip-duplicate");return;}
  if(localDemoMode){
    chatListenersStarted=true;
    listenerDebug("demo-chat-listeners-skipped");
    renderChat();
    return;
  }
  chatListenersStarted=true;
  listenerDebug("chat-listeners-start");
  chatListenerUnsubs.push(liveSnapshot(function(){return poolCollection("chat");},function(snap){
    if(embeddedUfc328Preview){chatMessages=[];updateChatNotificationBadge();renderChat();if(document.getElementById("adminPanel").style.display!=="none")renderAdminChatMessages();return;}
    chatMessages=snap.docs.map(function(d){
      var data=d.data();
      data.docId=data.docId||d.id;
      return data;
    }).sort(function(a,b){
      return String(a.createdAt||"").localeCompare(String(b.createdAt||""));
    });
    updateChatNotificationBadge();
    if(currentTab==="chat"){
      renderChat();
      markChatNotificationsSeen();
    }else{
      renderChat();
    }
    if(document.getElementById("adminPanel").style.display!=="none")renderAdminChatMessages();
  }));
  chatListenerUnsubs.push(liveSnapshot(function(){return poolCollection("typing");},function(snap){
    typingUsers=snap.docs.map(function(d){
      var data=d.data();
      data.docId=data.docId||d.id;
      return data;
    });
    renderTyping();
  }));
  chatListenerUnsubs.push(liveSnapshot(function(){return poolCollection("presence");},function(snap){
    presenceUsers=snap.docs.map(function(d){
      var data=d.data();
      data.docId=data.docId||d.id;
      return data;
    });
    refreshChatPresenceDots();
  }));
  chatListenerUnsubs.push(liveSnapshot(function(){return poolDoc("settings","chatControl");},function(snap){
    if(snap.exists()){
      var data=snap.data();
      chatEnabled=data.chatEnabled!==false;
      mutedUsers=data.mutedUsers||{};
    }else{
      chatEnabled=true;
      mutedUsers={};
    }
    renderChatControls();
    renderChat();
    if(document.getElementById("adminPanel").style.display!=="none")renderAdminChatMessages();
  }));
  startPresenceHeartbeat();
}

function startAdminListeners(){
  if(!(typeof isPoolAdmin==="function"&&isPoolAdmin())){listenerDebug("admin-listeners-blocked");return;}
  if(adminListenersStarted){listenerDebug("admin-listeners-skip-duplicate");return;}
  adminListenersStarted=true;
  listenerDebug("admin-listeners-start");
  adminListenerUnsubs.push(liveSnapshot(function(){return poolCollection("adminNotifications");},function(snap){
    adminNotifications=snap.docs.map(function(d){
      var data=d.data();
      data.docId=data.docId||d.id;
      return data;
    });
    if(document.getElementById("adminPanel").style.display!=="none")renderAdminNotifications();
  }));
  adminListenerUnsubs.push(liveSnapshot(function(){return poolCollection("joinRequests");},async function(snap){
    joinRequests=snap.docs.map(function(d){
      var data=d.data();
      data.docId=data.docId||d.id;
      return data;
    });
    var mine=currentUser&&joinRequests.find(function(r){return (r.uid||r.memberId||r.docId)===currentUser.uid;});
    currentJoinRequestStatus=mine?(mine.status||"pending"):"";
    if(mine&&mine.status==="approved"&&!currentPoolMemberApproved){
      currentPoolMemberApproved=true;
      accountNeedsPoolChoice=false;
      try{await hydrateProfileFromAccount(currentUser);}catch(e){console.warn("Could not refresh approved membership",e);}
    }
    if(mine&&mine.status==="denied"){
      currentPoolMemberApproved=false;
      accountNeedsPoolChoice=true;
    }
    renderJoinRequests();
    renderMemberGate();
  }));
}

