/* === Final UX cleanup overrides === */
(function(){
  function enhanceMyPicksView(){
    var root=document.getElementById('mineContent');
    if(!root||!myEntry)return;
    var score=root.querySelector('.my-banner');
    if(score){
      score.classList.add('profile-banner', bannerClass(getPreferredBanner()));
      decorateMyChampionBanner();
      [].slice.call(score.querySelectorAll('.banner-label-pill')).forEach(function(x){x.remove();});
    }
    var existingWrap=root.querySelector('.my-official-wrap');
    if(existingWrap&&existingWrap.querySelector('.my-pick-detail'))return;
    var rows=existingWrap?[].slice.call(existingWrap.children).filter(function(el){return el.classList&&el.classList.contains('my-row');}):[].slice.call(root.querySelectorAll(':scope > div .my-row'));
    if(!rows.length)return;
    var oldContainer=rows[0].parentNode;
    if(!oldContainer||oldContainer.id==='myInlineEditor'||oldContainer.closest('#myInlineEditor'))return;
    var wrap=existingWrap||document.createElement('div');
    wrap.className='my-official-wrap';
    wrap.innerHTML='<div class="my-official-head"><div class="my-official-title">Official Picks</div><div class="my-official-actions"><button type="button" class="my-small-btn" onclick="openAllMyOfficialPicks()">Open All</button><button type="button" class="my-small-btn" onclick="closeAllMyOfficialPicks()">Close All</button></div></div>';
    rows.forEach(function(row,idx){
      var title=(row.querySelector('.my-fight')&&row.querySelector('.my-fight').textContent)||('Pick '+(idx+1));
      if(row.classList.contains('fastest-tie-row')){
        wrap.appendChild(row.cloneNode(true));
        return;
      }
      var detail=document.createElement('details');
      detail.className='my-pick-detail';
      detail.innerHTML='<summary><span class="my-pick-title">'+safeHtml(title)+'</span><span class="my-pick-chevron">▼</span></summary>';
      detail.appendChild(row.cloneNode(true));
      wrap.appendChild(detail);
    });
    if(!existingWrap)oldContainer.replaceWith(wrap);
  }
  window.openAllMyOfficialPicks=function(){document.querySelectorAll('#mineContent .my-pick-detail').forEach(function(d){d.open=true;});};
  window.closeAllMyOfficialPicks=function(){document.querySelectorAll('#mineContent .my-pick-detail').forEach(function(d){d.open=false;});};
  var prevRenderMySummary=renderMySummary;
  renderMySummary=function(){prevRenderMySummary();enhanceMyPicksView();};
})();



