    orderedFightsLikeMakePicks().forEach(function(f){
      var res=getEffectiveFightResult(f.id), resolved=res&&res.winner, wn=resolved?(res.winner===1?f.f1:f.f2):null, f1c=allEntries.filter(function(e){return e.picks[f.id]===1;}).length, f2c=allEntries.filter(function(e){return e.picks[f.id]===2;}).length, cc=resolved?allEntries.filter(function(e){return e.picks[f.id]===res.winner;}).length:null, stat=resolved?'<span class="ap-result-label">RESULT</span><span style="color:#68d391;font-size:10px">✓ '+esc2(wn.split(' ').pop())+' ('+cc+'/'+allEntries.length+')</span>':'<span style="color:#555;font-size:10px">Pending</span>', rows='';
      order.forEach(function(e){
        var mp=e.methods||{}, pr=getEntryProps(e), side=e.picks[f.id], nm=side===1?f.f1:f.f2, odds=side===1?f.o1:f.o2, sc=calcScore(e), correct=resolved&&side===res.winner, bg=resolved?(correct?'#1c4532':'#742a2a'):(odds<0?'#2d3748':odds>=250?'#4a1628':'#1a365d'), col=resolved?(correct?'#68d391':'#fc8181'):(odds<0?'#a0aec0':odds>=250?'#fc8181':'#63b3ed'), ptLbl=resolved?(correct?'+'+getWinPts(f,side)+'pt ✓':'0pt'):'+'+getWinPts(f,side)+'pt', bon='';
        if(f.bonus&&mp[f.id]){var ok=resolved&&correct&&mp[f.id]===res.method;bon+='<div><span class="ap-method-pill" style="background:'+(resolved?(ok?'#1c4532':'#742a2a'):bg)+';color:'+(resolved?(ok?'#68d391':'#fc8181'):col)+'">'+mmLabel(mp[f.id])+'<span class="ap-method-pts">'+(resolved?(ok?'+'+getMethodPts(f,res.method,side)+'pt ✓':'0pt'):'+'+getMethodPts(f,mp[f.id],side)+'pt')+'</span></span></div>';}
        if(f.glovesEnabled&&pr.gloves[f.id]){var gv=pr.gloves[f.id],okg=resolved&&res.gloves&&gv===res.gloves;bon+='<div><span class="ap-method-pill" style="background:'+(resolved?(okg?'#1c4532':'#742a2a'):bg)+';color:'+(resolved?(okg?'#68d391':'#fc8181'):col)+'">Gloves '+gv+'<span class="ap-method-pts">'+(resolved?(okg?'+'+getGlovePts(f,gv)+'pt ✓':'0pt'):'+'+getGlovePts(f,gv)+'pt')+'</span></span></div>';}
        if(f.timingEnabled&&currentPoolFeatureEnabled("allowRoundPicks")&&pr.timings[f.id]){var tv=pr.timings[f.id],okt=resolved&&correct&&isTimingValidForMethod(f,mp[f.id],tv)&&res.timing&&tv===res.timing;bon+='<div><span class="ap-method-pill" style="background:'+(resolved?(okt?'#1c4532':'#742a2a'):bg)+';color:'+(resolved?(okt?'#68d391':'#fc8181'):col)+'">'+timingLabel(tv)+'<span class="ap-method-pts">'+(resolved?(okt?'+'+getTimingPts(f,tv)+'pt ✓':'0pt'):'+'+getTimingPts(f,tv)+'pt')+'</span></span></div>';}
        bon+=lockStatusPill(e,f,'all');
        rows+='<div class="ap-row profile-banner '+bannerClass(entryBanner(e))+'"><div><div class="ap-name">'+esc2(e.name||'')+'</div><div class="ap-score">'+sc+'pt</div></div><div class="ap-right"><div class="ap-pick"><span class="ap-tag combined-pick" style="background:'+bg+';color:'+col+'">'+(correct?'✓ ':'')+esc2((nm||'—').split(' ').pop())+'<span class="ap-tag-pts">'+ptLbl+'</span></span></div>'+bon+'</div></div>';
      });
      html+='<div class="ap-block" id="apb_'+f.id+'"><div class="ap-header" onclick="document.getElementById(\'apb_'+f.id+'\').classList.toggle(\'open\')"><div><div class="ap-title">'+esc2(fightTitle2(f))+'</div><div class="ap-split">'+esc2(f.f1.split(' ').pop())+' '+f1c+' · '+esc2(f.f2.split(' ').pop())+' '+f2c+'</div></div><div style="display:flex;align-items:center;gap:8px">'+stat+'<span class="ap-chevron">▼</span></div></div><div class="ap-body">'+rows+'</div></div>';
    });
