    if(!picks[fid])problems.push('choose a fighter');
    if(f.bonus&&!methods[fid])problems.push('choose a method');
    if(f.timingEnabled&&currentPoolFeatureEnabled("allowRoundPicks")&&!timings[fid])problems.push('choose a round/distance');if(f.overUnderEnabled&&currentPoolFeatureEnabled("allowOverUnder")&&!overs[fid])problems.push('choose over/under');
