        +inlinePropBtn('my_mk_'+f.id,'KO/TKO',getMethodPts(f,'ko',methodSide),"setMyInlineMethod('"+f.id+"','ko')",methods[f.id]==='ko',false,methodLineLabel(getMethodLine(f,'ko',methodSide)))
        +inlinePropBtn('my_ms_'+f.id,'Submission',getMethodPts(f,'sub',methodSide),"setMyInlineMethod('"+f.id+"','sub')",methods[f.id]==='sub',false,methodLineLabel(getMethodLine(f,'sub',methodSide)))
        +inlinePropBtn('my_md_'+f.id,'Decision',getMethodPts(f,'dec',methodSide),"setMyInlineMethod('"+f.id+"','dec')",methods[f.id]==='dec',false,methodLineLabel(getMethodLine(f,'dec',methodSide)))
