    var saved=window.__myLockSaveMsg||'',h='<div class="lock-card"><div class="lock-title">Lock of the Night</div><div class="lock-note">Choose the fighter you trust most. Correct lock earns +2 points; a miss scores 0 with no deduction. Be strategic here. Most people may pick the biggest favorite on the card, but that is not always the smartest choice. Good luck.</div><div class="lock-grid">';
    activeFights().forEach(function(f){[1,2].forEach(function(side){var val=f.id+':'+side,nm=side===1?f.f1:f.f2,elig=lockEligibility(val),ineligible=!elig.valid;h+='<button type="button" class="lock-btn'+(lockPick===val?' active':'')+(ineligible?' lock-ineligible':'')+'" title="'+esc(ineligible?elig.message:'')+'" onclick="setMyInlineLock(\''+esc(val)+'\')">'+esc(nm)+'</button>';});});
