  window.toggleMyPicksEditor=function(){if(isLocked())return;var picker=document.getElementById('profileBannerDropdown');if(picker)picker.open=false;window.__profileBannerPickerOpen=false;window.__myPicksEditorOpen=!window.__myPicksEditorOpen;renderMySummary();};
