  window.setMyInlineOverUnder=function(fid,val){if(!currentPoolFeatureEnabled("allowOverUnder"))return;if(isLocked())return publicLockNotice();var f=fights.find(function(x){return x.id===fid;});if(!f||!isOverUnderValidForPick(f,val)){window.__myPicksEditorOpen=true;renderMySummary();return;}overs[fid]=val;afterChange(fid);};
  window.setMyInlineLock=function(val){if(!currentPoolFeatureEnabled("allowLockOfTheNight"))return;if(isLocked())return publicLockNotice();var elig=lockEligibility(val);if(!elig.valid){window.__myLockEligibilityMsg=elig.message;showLockEligibilityMessage(elig.message);window.__myPicksEditorOpen=true;window.__myInlineLockOpen=true;renderMySummary();return;}window.__myLockEligibilityMsg="";clearLockEligibilityMessage();lockPick=val;window.__myPicksEditorOpen=true;window.__myInlineLockOpen=true;renderMySummary();};
