    var props={gloves:Object.assign({},gloves),timings:currentPoolFeatureEnabled("allowRoundPicks")?Object.assign({},timings):{},overs:currentPoolFeatureEnabled("allowOverUnder")?Object.assign({},overs):{},lock:validLock,fastestFinish:(window.fastestFinishForSave?window.fastestFinishForSave():null)};
