  function installAllPicksOpeners(root){
    (root||document).querySelectorAll('.ap-header').forEach(function(head){
      head.classList.add('ap-header-fixed');
      head.classList.remove('ap-header');
      head.removeAttribute('onclick');
      head.onclick=null;
      head.setAttribute('role','button');
      head.setAttribute('tabindex','0');
      head.style.setProperty('position','relative','important');
      head.style.setProperty('z-index','20','important');
      head.style.setProperty('pointer-events','auto','important');
      head.style.setProperty('cursor','pointer','important');
      head.querySelectorAll('*').forEach(function(child){child.style.setProperty('pointer-events','none','important');});
    });
  }
  function toggleAllPicksHeader(target){
    var head=target&&target.closest?target.closest('.ap-header-fixed,.ap-header'):null;
    if(!head)return false;
    var block=head.closest('.ap-block');
    if(!block)return false;
    block.classList.toggle('open');
    head.setAttribute('aria-expanded',block.classList.contains('open')?'true':'false');
    return true;
  }
  function allPicksHeaderAtPoint(x,y){
    var heads=[].slice.call(document.querySelectorAll('#allPicksContent .ap-header-fixed,#allPicksContent .ap-header'));
    for(var i=0;i<heads.length;i++){
      var r=heads[i].getBoundingClientRect();
      if(x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom)return heads[i];
    }
    return null;
  }
  function toggleAllPicksFromEvent(e){
    var target=e.target;
    if(!(target&&target.closest&&target.closest('#allPicksContent'))&&!(typeof e.clientX==='number'&&allPicksHeaderAtPoint(e.clientX,e.clientY)))return false;
    var head=target&&target.closest?target.closest('#allPicksContent .ap-header-fixed,#allPicksContent .ap-header'):null;
    if(!head&&typeof e.clientX==='number')head=allPicksHeaderAtPoint(e.clientX,e.clientY);
    return head?toggleAllPicksHeader(head):false;
  }
  function forceTwoPointUnderdogGray(root){
    if(document.body&&document.body.classList.contains("phone-design-preview"))return;
    var gray='linear-gradient(180deg,#737b86 0%,#343b45 48%,#141922 100%)';
    var scope=root||document;
    function setImportant(el,prop,value){
      if(el.style.getPropertyValue(prop)===value&&el.style.getPropertyPriority(prop)==='important')return;
      el.style.setProperty(prop,value,'important');
    }
    [].slice.call(scope.querySelectorAll('.fighter-odds.dog,.fighter-btn.sel-dog .fighter-odds,.fighter-pts.pts-dog,.fighter-btn.sel-dog .fighter-pts,.my-tag[style*="#1a365d"],.combined-pick[style*="#1a365d"],.extra-pill[style*="#1a365d"],.my-method-pill[style*="#1a365d"],.ap-method-pill[style*="#1a365d"],.ap-tag[style*="#1a365d"]')).forEach(function(el){
      setImportant(el,'background',gray);
      setImportant(el,'border','1px solid rgba(226,232,240,.44)');
      setImportant(el,'color','#fff');
      setImportant(el,'-webkit-text-fill-color','#fff');
      setImportant(el,'text-shadow','0 2px 7px rgba(0,0,0,.84)');
      setImportant(el,'box-shadow','inset 0 1px 0 rgba(255,255,255,.22),0 6px 12px rgba(0,0,0,.30)');
	    });
	  }
  function removeGloveArtifacts(root){
    var scope=root||document;
    [].slice.call(scope.querySelectorAll('.pick-extra-section,.scoring-key-category,.scoring-guide-key-row,.scoring-explain-item')).forEach(function(el){
      if(/\bTouch\s+Gloves\b|\bGloves\?/i.test(el.textContent||''))el.remove();
    });
    [].slice.call(scope.querySelectorAll('.extra-pill,.ap-method-pill,.my-result-method,.result-btn,.god-result-btn')).forEach(function(el){
      if(/\bGloves\b/i.test(el.textContent||''))el.remove();
    });
  }
