/* Final guard: keep old banner imagery disabled for the lightweight launch UI. */
(function(){
  if(typeof embeddedUfc328Preview!=="undefined"&&embeddedUfc328Preview)return;
  function removeBannerClasses(el){
    if(!el||!el.classList)return;
    Array.prototype.slice.call(el.classList).forEach(function(cls){
      if(cls==="profile-banner"||cls==="my-banner-champion"||cls.indexOf('banner-')===0)el.classList.remove(cls);
    });
    el.classList.add('plain-nameplate');
    el.style.removeProperty('--profile-banner-image');
    el.style.removeProperty('background');
    [].slice.call(el.querySelectorAll('.lb-banner-full,.profile-banner-img,.profile-banner-choice-img')).forEach(function(img){img.remove();});
  }
  function stripProfileBanners(){
    [].slice.call(document.querySelectorAll('#mineContent>.my-banner,#mineContent .my-banner,#lbList .lb-entry,#allPicksContent .ap-row,.preview-lb-list .lb-entry,.setup-preview .ap-row')).forEach(removeBannerClasses);
    [].slice.call(document.querySelectorAll('#profileBannerDropdown,#profileBannerGrid,.profile-banner-card,.profile-banner-select-card,.profile-banner-gallery')).forEach(function(el){el.remove();});
  }
  ['renderMySummary','renderAllPicks','renderFights'].forEach(function(name){
    if(typeof window[name]!=='function')return;
    var prev=window[name];
    window[name]=function(){
      var out=prev.apply(this,arguments);
      stripProfileBanners();
      requestAnimationFrame(stripProfileBanners);
      setTimeout(stripProfileBanners,80);
      return out;
    };
  });
  stripProfileBanners();
  if(window.MutationObserver&&!window.__bannerAndLogoGuard){
    var guardTimer=null;
    window.__bannerAndLogoGuard=new MutationObserver(function(){
      if(guardTimer)return;
      guardTimer=requestAnimationFrame(function(){
        guardTimer=null;
        stripProfileBanners();
      });
    });
    var bannerGuardRoot=document.body||document.documentElement;
    if(bannerGuardRoot&&bannerGuardRoot.nodeType===1)window.__bannerAndLogoGuard.observe(bannerGuardRoot,{childList:true,subtree:true,attributes:true,attributeFilter:['class','style']});
  }
})();

