/* Hard freeze: card art and scroll position must stay still while picks rerender. */
(function(){
  if(typeof embeddedUfc328Preview!=="undefined"&&embeddedUfc328Preview)return;
  var hardFreezePickArtStyle=document.createElement('style');
  hardFreezePickArtStyle.textContent='html.pick-click-freeze,html.pick-click-freeze *{scroll-behavior:auto!important}';
  document.head.appendChild(hardFreezePickArtStyle);
  var pickScrollLockTimer=null;
  function clearPickScrollLock(){
    if(!window.__pickScrollLock)return;
    var lock=window.__pickScrollLock;
    if(Date.now()<lock.until)return;
    window.__pickScrollLock=null;
    document.documentElement.classList.remove('pick-click-freeze');
  }
  function isLiveMakePicksScroll(){
    return typeof currentTab!=="undefined"&&currentTab==="picks"&&document.body&&!document.body.classList.contains("embedded-readonly-preview");
  }
  function restorePickScrollLock(){
    var lock=window.__pickScrollLock;
    if(!lock)return;
    if(isLiveMakePicksScroll()){window.__pickScrollLock=null;document.documentElement.classList.remove('pick-click-freeze');return;}
    document.documentElement.classList.add('pick-click-freeze');
    window.scrollTo(lock.x,lock.y);
    clearTimeout(pickScrollLockTimer);
    pickScrollLockTimer=setTimeout(clearPickScrollLock,lock.until-Date.now()+20);
  }
  function startPickScrollLock(){
    if(isLiveMakePicksScroll())return;
    window.__pickScrollLock={x:window.scrollX||window.pageXOffset||0,y:window.scrollY||window.pageYOffset||0,until:Date.now()+900};
    restorePickScrollLock();
  }
  function holdScroll(fn){
    if(typeof fn!=='function')return fn;
    return function(){
      startPickScrollLock();
      if(!window.__pickScrollLock)return fn.apply(this,arguments);
      var x=window.__pickScrollLock.x,y=window.__pickScrollLock.y;
      var out=fn.apply(this,arguments);
      function restore(){window.scrollTo(x,y);}
      requestAnimationFrame(restore);
      setTimeout(restore,0);
      setTimeout(restore,60);
      setTimeout(restore,160);
      return out;
    };
  }
  ['doPick','pickMethod','pickTiming','pickOverUnder','pickLock','setMyInlinePick','setMyInlineMethod','setMyInlineTiming','setMyInlineOverUnder','setMyInlineLock'].forEach(function(name){
    if(typeof window[name]==='function'&&!window[name].__holdsPickScroll){
      var wrapped=holdScroll(window[name]);
      wrapped.__holdsPickScroll=true;
      window[name]=wrapped;
    }
  });
  function rememberPickAnchor(target){
    var card=target&&target.closest&&target.closest('#view-picks .fight-card,#view-picks .lock-card,#myInlineEditor.make-picks-clone .fight-card,#myInlineEditor.make-picks-clone .lock-card');
    if(!card)return;
    if(isLiveMakePicksScroll()&&card.closest('#view-picks'))return;
    startPickScrollLock();
    window.__pickFrozenAnchor={el:card,top:card.getBoundingClientRect().top,x:window.scrollX||0,y:window.scrollY||0,until:Date.now()+900};
  }
  function restorePickAnchor(){
    var a=window.__pickFrozenAnchor;
    if(!a||!a.el||Date.now()>a.until)return;
    var nowTop=a.el.getBoundingClientRect().top;
    window.scrollTo(a.x,(window.scrollY||0)+(nowTop-a.top));
  }
  document.addEventListener('pointerdown',function(e){rememberPickAnchor(e.target);},true);
  document.addEventListener('mousedown',function(e){
    var target=e.target&&e.target.closest&&e.target.closest('#view-picks .fight-card button,#view-picks .lock-card button,#myInlineEditor.make-picks-clone .fight-card button,#myInlineEditor.make-picks-clone .lock-card button');
    if(target){rememberPickAnchor(target);e.preventDefault();}
  },true);
  document.addEventListener('click',function(e){
    var target=e.target&&e.target.closest&&e.target.closest('#view-picks .fight-card button,#view-picks .lock-card button,#myInlineEditor.make-picks-clone .fight-card button,#myInlineEditor.make-picks-clone .lock-card button');
    if(!target)return;
    try{target.blur();}catch(err){}
    restorePickScrollLock();
    requestAnimationFrame(restorePickAnchor);
    setTimeout(restorePickAnchor,0);
    setTimeout(restorePickAnchor,60);
    setTimeout(restorePickAnchor,180);
  },true);
  window.addEventListener('scroll',function(){
    if(window.__pickScrollLock&&Date.now()<window.__pickScrollLock.until)requestAnimationFrame(restorePickScrollLock);
  },{passive:true});
})();

