window.refreshFightResultsForViews=async function(){
  try{
    if(embeddedUfc328Preview){applyEmbeddedUfc328PreviewData();return true;}
    var snap=await getDoc(poolDoc("results","fights"));
    fightResults=snap.exists()?snap.data():{};
    fights.forEach(function(f){if(fightResults[f.id])fightResults[f.id]=normalizeFightResultData(f,fightResults[f.id]);});
    try{renderLeaderboard();}catch(e){console.warn("Could not render leaderboard after result refresh",e);}
    try{renderAllPicks();}catch(e){console.warn("Could not render All Picks after result refresh",e);}
    try{renderMySummary();}catch(e){console.warn("Could not render My Picks after result refresh",e);}
    return true;
  }catch(e){
    console.warn("Could not refresh fight results",e);
    return false;
  }
};

(function(){
  return; // Disabled old fallback auth patch; canonical Firebase auth lives in the main app script.
  var firebaseConfigFallback = {
    apiKey: ["AIzaSyCZt","tp0qGCO5PE","l2Mu1Zkov9","AGZ1vyyGlY"].join(""),
    authDomain: "ufc328pool.firebaseapp.com",
    projectId: "ufc328pool",
    storageBucket: "ufc328pool.firebasestorage.app",
    messagingSenderId: "485597420591",
    appId: "1:485597420591:web:a28e635207bd41232e7ada",
    measurementId: "G-R6RM4Y4M6N"
  };
  function setSetupMessageFallback(text){
    var el=document.getElementById("setupStatus");
    if(el)el.textContent=text||"";
  }
  function authFriendlyFallback(e){
    var code=e&&e.code?e.code:"";
    if(code==="auth/invalid-email")return "That email does not look valid. Check it and try again.";
    if(code==="auth/wrong-password"||code==="auth/invalid-credential"||code==="auth/user-not-found")return "We could not sign in with that email and password. Check both, or tap Forgot Password.";
    if(code==="auth/too-many-requests")return "Firebase blocked attempts for a bit. Wait a minute, then try again.";
    if(code==="auth/network-request-failed")return "Could not reach Firebase right now. Check the internet connection and try again.";
    if(code==="auth/unauthorized-domain")return "This preview address is not authorized in Firebase yet.";
    return (e&&e.message)||"Could not sign in. Try again.";
  }
  function fallbackPoolSlug(v){
    return String(v||"").trim().toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,42);
  }
  function fallbackCurrentPoolId(){
    var params=new URLSearchParams(window.location.search);
    return fallbackPoolSlug(params.get("pool"))||"dante-casuals";
  }
  function fallbackStorageKey(poolId,k){
    return "ufc250_"+poolId+"_"+k;
  }
  function fallbackGlobalProfileKey(){
    return "ufc250_global_profile";
  }
  function fallbackSplitName(v){
    var parts=String(v||"").trim().split(/\s+/).filter(Boolean);
    return {firstName:parts[0]||"",lastName:parts.slice(1).join(" ")||""};
  }
  async function storeFallbackSignedInProfile(user,app){
    try{
      var fsMod=await import("https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js");
      var db=fsMod.getFirestore(app);
      var poolId=fallbackCurrentPoolId();
      var accountSnap=await fsMod.getDoc(fsMod.doc(db,"users",user.uid));
      var memberSnap=await fsMod.getDoc(fsMod.doc(db,"pools",poolId,"members",user.uid));
      var account=accountSnap.exists()?accountSnap.data()||{}:{};
      var member=memberSnap.exists()?memberSnap.data()||{}:{};
      var data=(member.name||member.username||member.email)?member:account;
      var split=fallbackSplitName(data.fullName||user.displayName||((data.firstName||"")+" "+(data.lastName||"")));
      var profile={
        memberId:user.uid,
        authUid:user.uid,
        poolId:poolId,
        firstName:data.firstName||split.firstName,
        lastName:data.lastName||split.lastName,
        fullName:data.fullName||[data.firstName||split.firstName,data.lastName||split.lastName].filter(Boolean).join(" "),
        username:data.username||data.name||((user.email||"").split("@")[0]),
        usernameKey:String(data.usernameKey||data.username||data.name||"").toLowerCase().replace(/[^a-z0-9_]+/g,""),
        name:data.name||data.username||((user.email||"").split("@")[0]),
        email:user.email||data.email||"",
        profileBanner:data.profileBanner||data.bannerKey||"",
        createdAt:data.createdAt||new Date().toISOString(),
        updatedAt:new Date().toISOString(),
        localOnly:true,
        syncPending:true
      };
      try{
        localStorage.setItem(fallbackStorageKey(poolId,"id"),user.uid);
        localStorage.setItem(fallbackStorageKey(poolId,"profile"),JSON.stringify(profile));
        localStorage.setItem(fallbackGlobalProfileKey(),JSON.stringify(profile));
      }catch(e){}
    }catch(e){
      console.warn("Could not store fallback signed-in profile",e);
    }
  }
  async function fallbackSignIn(){
    var emailEl=document.getElementById("signInEmailInput");
    var passwordEl=document.getElementById("signInPasswordInput");
    var email=String(emailEl&&emailEl.value||"").trim().toLowerCase();
    var password=removeCredentialSpaces(passwordEl&&passwordEl.value);
    if(!email){setSetupMessageFallback("Enter the email for the account you already created.");return;}
    if(!password){setSetupMessageFallback("Enter the password for that account.");return;}
    var btn=document.getElementById("signInAccountBtn");
    if(btn){btn.disabled=true;btn.textContent="Signing In...";}
    setSetupMessageFallback("Signing in...");
    try{
      var appMod=await import("https://www.gstatic.com/firebasejs/10.12.0/firebase-app.js");
      var authMod=await import("https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js");
      var app=appMod.getApps&&appMod.getApps().length?appMod.getApp():appMod.initializeApp(firebaseConfigFallback);
      var auth=authMod.getAuth(app);
      await authMod.setPersistence(auth,authMod.browserLocalPersistence);
      var result=await authMod.signInWithEmailAndPassword(auth,email,password);
      await storeFallbackSignedInProfile(result.user,app);
      setSetupMessageFallback("Signed in. Loading your pool...");
      setTimeout(function(){window.location.reload();},350);
    }catch(e){
      setSetupMessageFallback(authFriendlyFallback(e));
    }finally{
      if(btn){btn.disabled=false;btn.textContent="Sign In";}
    }
  }
  async function fallbackPasswordReset(){
    var emailEl=document.getElementById("signInEmailInput");
    var email=String(emailEl&&emailEl.value||"").trim().toLowerCase();
    if(!email){setSetupMessageFallback("Enter the email for your account first.");return;}
    setSetupMessageFallback("Sending password reset email...");
    try{
      var appMod=await import("https://www.gstatic.com/firebasejs/10.12.0/firebase-app.js");
      var authMod=await import("https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js");
      var app=appMod.getApps&&appMod.getApps().length?appMod.getApp():appMod.initializeApp(firebaseConfigFallback);
      var auth=authMod.getAuth(app);
      await authMod.sendPasswordResetEmail(auth,email);
      setSetupMessageFallback("Password reset email sent. Check your inbox and spam folder.");
    }catch(e){
      setSetupMessageFallback(authFriendlyFallback(e));
    }
  }
  window.showSignInMode=function(){
    var createMode=document.getElementById("createAccountMode");
    var signInMode=document.getElementById("signInMode");
    if(createMode)createMode.classList.add("auth-mode-hidden");
    if(signInMode)signInMode.classList.remove("auth-mode-hidden");
    setSetupMessageFallback("Enter the email and password for an account you already created.");
  };
  window.showCreateAccountMode=function(){
    var createMode=document.getElementById("createAccountMode");
    var signInMode=document.getElementById("signInMode");
    if(signInMode)signInMode.classList.add("auth-mode-hidden");
    if(createMode)createMode.classList.remove("auth-mode-hidden");
    setSetupMessageFallback("");
    if(typeof window.setCreateAccountBusy==="function")window.setCreateAccountBusy(false);
  };
  function switchAuthMode(e){
    var btn=e.target&&e.target.closest&&e.target.closest("#showSignInModeBtn,#showCreateAccountModeBtn,#signInAccountBtn,#signInForgotPasswordBtn");
    if(!btn)return;
    if(btn.id==="showSignInModeBtn")window.showSignInMode();
    else if(btn.id==="showCreateAccountModeBtn")window.showCreateAccountMode();
    else if(btn.id==="signInAccountBtn"){
      if(typeof window.signInExistingAccount==="function")window.signInExistingAccount();
      else fallbackSignIn();
    }
    else if(btn.id==="signInForgotPasswordBtn"){
      if(typeof window.sendPasswordResetFromSignIn==="function")window.sendPasswordResetFromSignIn();
      else fallbackPasswordReset();
    }
    e.preventDefault();
    e.stopPropagation();
    if(e.stopImmediatePropagation)e.stopImmediatePropagation();
  }
  window.addEventListener("pointerdown",switchAuthMode,true);
  window.addEventListener("mousedown",switchAuthMode,true);
  window.addEventListener("touchstart",switchAuthMode,true);
  window.addEventListener("click",switchAuthMode,true);
  document.addEventListener("pointerdown",switchAuthMode,true);
  document.addEventListener("click",switchAuthMode,true);
})();

