      if(["ko","tko","sub","doctor","doctor_stoppage","dq"].indexOf(method)<0)return;
      if(!r.timing||r.timing==="distance"||!r.stoppageMark)return;
      var rn=typeof timingRoundNumber==="function"?timingRoundNumber(r.timing):null;
      var mark=typeof parseStoppageMark==="function"?parseStoppageMark(r.stoppageMark):null;
      if(rn===null||mark===null)return;
