/* Final standalone tiebreaker controls: keep this component responsive even if older layers intercept events. */
(function(){
  return;
  function key(){var p=new URLSearchParams(location.search);return "fightLocksFastestFinishTie:"+(p.get("pool")||"default");}
  function parseMark(v){
    var raw=String(v||"").trim();
    if(/^\d{3}$/.test(raw))raw=parseInt(raw.slice(0,-2),10)+":"+raw.slice(-2);
    if(/^\d{1,2}$/.test(raw))raw="0:"+String(parseInt(raw||"0",10)).padStart(2,"0");
    var m=raw.match(/^([0-5]):([0-5]\d)$/);
    if(!m)return "";
    if(parseInt(m[1],10)===5&&parseInt(m[2],10)!==0)return "";
    return parseInt(m[1],10)+":"+m[2];
  }
  function getTie(){
    if(!currentPoolFeatureEnabled("allowFastestFinishTiebreaker"))return null;
    var t=window.__fastestFinishTie||{};
    var round=String(t.round||"").toLowerCase();
    var mark=parseMark(t.mark||"");
    if(/^r[1-3]$/.test(round)&&mark)return {round:round,mark:mark};
    return null;
  }
  function saveLocal(t){
    if(!t)return;
    window.__fastestFinishTie={round:t.round,mark:t.mark};
  }
  var fastestTieSavedMsg="";
  function entryTie(){
    var ft=(myEntry&&myEntry.props&&(myEntry.props.fastestFinish||myEntry.props.fastestFinishTiebreaker))||(myEntry&&myEntry.fastestFinishTiebreaker)||{};
    var round=String(ft.round||ft.r||"").toLowerCase();
    var mark=parseMark(ft.mark||ft.timeMark||ft.time||"");
    return /^r[1-3]$/.test(round)&&mark?{round:round,mark:mark}:null;
  }
  function sameTie(a,b){
    return !!(a&&b&&a.round===b.round&&a.mark===b.mark);
  }
  function updateTieUi(){
    var current=getTie();
    var round=(window.__fastestFinishTie&&window.__fastestFinishTie.round)||(current&&current.round)||"";
    document.querySelectorAll(".fastest-round-btn").forEach(function(btn){
      btn.classList.toggle("active",btn.getAttribute("data-round")===round);
    });
    var input=document.getElementById("fastestFinishMark");
    var typed=input?parseMark(input.value):"";
    if(input&&/^\d{3}$/.test(String(input.value||"").trim())){
      input.value=typed;
      window.__fastestFinishTie=Object.assign({},window.__fastestFinishTie||{},{mark:typed});
    }
    current=getTie();
    var summary=document.getElementById("fastestFinishSummary");
    if(summary)summary.textContent=current?"Fastest Finish Tiebreaker: "+current.round.toUpperCase()+" at "+current.mark+" elapsed":"Fastest Finish Tiebreaker: Not picked";
    var btn=document.querySelector(".fastest-tie-save");
    if(btn)btn.textContent=entryTie()?"Update Tiebreaker":"Set Tiebreaker";
    var saved=document.getElementById("fastestTieSaveMsg");
    if(saved){
      saved.textContent=fastestTieSavedMsg;
      saved.classList.toggle("saved",!!fastestTieSavedMsg);
    }
  }
  window.setFastestFinishRound=function(v){
    if(!currentPoolFeatureEnabled("allowFastestFinishTiebreaker"))return;
    fastestTieSavedMsg="";
    window.__fastestFinishUserTouched=true;
    window.__fastestFinishTie=Object.assign({},window.__fastestFinishTie||{},{round:String(v||"").toLowerCase()});
    updateTieUi();
    if(window.markBottomPickDirty)window.markBottomPickDirty();
  };
  window.setFastestFinishMark=function(v){
    if(!currentPoolFeatureEnabled("allowFastestFinishTiebreaker"))return;
    fastestTieSavedMsg="";
    window.__fastestFinishUserTouched=true;
    var raw=String(v||""), formatted=parseMark(raw);
    window.__fastestFinishTie=Object.assign({},window.__fastestFinishTie||{},{mark:formatted||raw});
    var input=document.getElementById("fastestFinishMark");
    if(input&&formatted&&/^\d{3}$/.test(raw.trim()))input.value=formatted;
    updateTieUi();
    if(window.markBottomPickDirty)window.markBottomPickDirty();
  };
  window.blurFastestFinishMark=function(el){
    if(!currentPoolFeatureEnabled("allowFastestFinishTiebreaker"))return;
    var formatted=parseMark(el&&el.value);
    if(el&&formatted)el.value=formatted;
    window.setFastestFinishMark(formatted||(el&&el.value)||"");
  };
  window.fastestFinishForSave=function(){
    if(!currentPoolFeatureEnabled("allowFastestFinishTiebreaker"))return null;
    var t=getTie();
    return t?{round:t.round,mark:t.mark}:null;
  };
  window.saveFastestFinishTiebreaker=async function(){
    if(!currentPoolFeatureEnabled("allowFastestFinishTiebreaker")){
      var err=document.getElementById("fastestFinishError");
      if(err)err.textContent=lockedFeatureMessage();
      return;
    }
    var input=document.getElementById("fastestFinishMark");
    var mark=parseMark(input&&input.value);
    var round=String(window.__fastestFinishTie&&window.__fastestFinishTie.round||"").toLowerCase();
    var err=document.getElementById("fastestFinishError"), saved=document.getElementById("fastestTieSaveMsg"), btn=document.querySelector(".fastest-tie-save");
    if(!/^r[1-3]$/.test(round)||!mark){
      if(err)err.textContent="Choose a round and enter a valid elapsed time from 0:00 through 5:00.";
      fastestTieSavedMsg="";
      if(saved){saved.textContent="";saved.classList.remove("saved");}
      return;
    }
    var hadTie=!!entryTie();
    if(btn)btn.textContent=hadTie?"Updating...":"Setting...";
    if(input)input.value=mark;
    var tie={round:round,mark:mark};
    try{
      saveLocal(tie);
      if(myEntry&&myEntry.docId){
        if(typeof submitPicks==="function"){
          await submitPicks();
        }else if(typeof setDoc==="function"){
          var props=Object.assign({},getEntryProps(myEntry),{fastestFinish:tie});
          var updated=Object.assign({},myEntry,{props:props,updatedAt:new Date().toISOString()});
          await setDoc(poolDoc("entries",myEntry.docId),updated);
          myEntry=updated;
          allEntries=allEntries.map(function(e){return entryIdentity(e)===entryIdentity(updated)?Object.assign({},e,{props:props,updatedAt:updated.updatedAt}):e;});
          renderMySummary();renderLeaderboard();renderAllPicks();
        }
      }
      fastestTieSavedMsg=hadTie?"Fastest Finish Tiebreaker updated successfully.":"Fastest Finish Tiebreaker set successfully.";
      if(err)err.textContent="";
    }catch(e){
      fastestTieSavedMsg="";
      if(err)err.textContent="Could not save Fastest Finish Tiebreaker. Try again.";
      console.warn("Could not save fastest finish tiebreaker",e);
    }
    updateTieUi();
  };
  setTimeout(updateTieUi,0);
  setTimeout(updateTieUi,800);
})();
	/* UFC 328 signup preview: force the completed fastest-finish example across the readonly preview. */
	(function(){
	  if(typeof embeddedUfc328Preview==="undefined"||!embeddedUfc328Preview)return;
	  if(new URLSearchParams(location.search).get("phoneDesignPreview")==="1")return;
	  var previewTie={round:"r1",mark:"1:57"};
  function applyPreviewTieData(){
    window.__fastestFinishTie={round:previewTie.round,mark:previewTie.mark};
    try{
      var payload=JSON.stringify(previewTie);
      localStorage.setItem("fightLocksFastestFinishTie:"+String(currentPoolId||"fightlocks"),payload);
      localStorage.setItem("fightLocksFastestFinishTie:last",payload);
    }catch(e){}
    if(myEntry){
      myEntry=Object.assign({},myEntry,{props:Object.assign({},getEntryProps(myEntry),{fastestFinish:previewTie})});
    }
    if(Array.isArray(allEntries)){
      allEntries=allEntries.map(function(entry){
        if(entry&&entry.name==="Dante")return Object.assign({},entry,{props:Object.assign({},getEntryProps(entry),{fastestFinish:previewTie})});
        return entry;
      });
    }
  }
  function paintPreviewTie(){
    applyPreviewTieData();
    document.querySelectorAll(".fastest-round-btn").forEach(function(btn){
      btn.classList.toggle("active",btn.getAttribute("data-round")===previewTie.round);
      btn.disabled=true;
      btn.setAttribute("aria-disabled","true");
    });
    var input=document.getElementById("fastestFinishMark");
    if(input){
      input.value=previewTie.mark;
      input.readOnly=true;
      input.disabled=true;
      input.setAttribute("aria-disabled","true");
    }
    var summary=document.getElementById("fastestFinishSummary");
    if(summary)summary.textContent="Fastest Finish Tiebreaker: R1 at 1:57 elapsed";
    var btn=document.querySelector(".fastest-tie-save");
    if(btn)btn.style.display="none";
  }
  window.setFastestFinishRound=function(){paintPreviewTie();};
  window.setFastestFinishMark=function(){paintPreviewTie();};
  window.blurFastestFinishMark=function(){paintPreviewTie();};
  window.saveFastestFinishTiebreaker=function(){paintPreviewTie();};
	  paintPreviewTie();
	  setTimeout(paintPreviewTie,0);
	  setTimeout(paintPreviewTie,800);
})();
