	  if(new URLSearchParams(location.search).get("phoneDesignPreview")==="1")return;
	  function installEmbeddedPreviewScroll(){
    if(window.__ufc328EmbeddedScrollReady)return;
    window.__ufc328EmbeddedScrollReady=true;
    var lastTouchY=null;
    function scrollRoot(){
      return document.scrollingElement||document.documentElement||document.body;
    }
    function maxScroll(root){
      return Math.max(0,(root.scrollHeight||0)-window.innerHeight);
    }
    function scrollPreviewBy(delta){
      var root=scrollRoot();
      if(!root||!delta)return false;
      var before=root.scrollTop||window.pageYOffset||0;
      var next=Math.max(0,Math.min(maxScroll(root),before+delta));
      if(Math.abs(next-before)<1)return false;
      root.scrollTop=next;
      if(document.body)document.body.scrollTop=next;
      return true;
    }
    window.addEventListener("wheel",function(e){
      var delta=e.deltaY;
      if(e.deltaMode===1)delta*=16;
      else if(e.deltaMode===2)delta*=window.innerHeight;
      if(scrollPreviewBy(delta)){
        e.preventDefault();
        e.stopPropagation();
      }
    },{capture:true,passive:false});
    window.addEventListener("touchstart",function(e){
      lastTouchY=e.touches&&e.touches.length===1?e.touches[0].clientY:null;
    },{capture:true,passive:true});
    window.addEventListener("touchmove",function(e){
      if(!e.touches||e.touches.length!==1||lastTouchY===null)return;
      var y=e.touches[0].clientY;
      var delta=lastTouchY-y;
      lastTouchY=y;
      if(Math.abs(delta)<2)return;
      if(scrollPreviewBy(delta)){
        e.preventDefault();
        e.stopPropagation();
      }
    },{capture:true,passive:false});
    window.addEventListener("touchend",function(){lastTouchY=null;},{capture:true,passive:true});
    window.addEventListener("touchcancel",function(){lastTouchY=null;},{capture:true,passive:true});
  }
  installEmbeddedPreviewScroll();
