/* UFC 328 preview: final My Picks collapsed rows keep fighter hit/miss badges after every repaint. */
(function(){
  if(new URLSearchParams(location.search).get("previewCard")!=="ufc328")return;
  var queued=false;
  function esc(v){return String(v==null?"":v).replace(/[&<>'"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c];});}
  function last(v){return String(v||"").split(" ").pop();}
  function fightName(f){return last(f.f1)+" vs "+last(f.f2);}
  function calcPreviewFightPts(entry,f){
    if(typeof window.fightPointsForEntry==="function")return window.fightPointsForEntry(entry,f);
    var r=getEffectiveFightResult(f.id), side=entry&&entry.picks&&entry.picks[f.id], mp=(entry&&entry.methods)||{}, pr=typeof getEntryProps==="function"?getEntryProps(entry):{}, total=0;
    if(!r||!r.winner)return 0;
    var won=side===r.winner;
    if(won)total+=getWinPts(f,side);
    if(f.bonus&&won&&mp[f.id]===r.method)total+=getMethodPts(f,r.method,side);
    if(f.glovesEnabled&&r.gloves&&pr.gloves&&pr.gloves[f.id]===r.gloves)total+=getGlovePts(f,r.gloves);
    if(f.timingEnabled&&currentPoolFeatureEnabled("allowRoundPicks")&&won&&r.timing&&pr.timings&&pr.timings[f.id]===r.timing&&isTimingValidForMethod(f,mp[f.id],pr.timings[f.id]))total+=getTimingPts(f,r.timing);
    if(f.overUnderEnabled&&currentPoolFeatureEnabled("allowOverUnder")&&pr.overs&&pr.overs[f.id]===overUnderResultFromTiming(f,r.timing))total+=getOverUnderPts(f,pr.overs[f.id]);
    if(cardScoring&&cardScoring.lockEnabled&&currentPoolFeatureEnabled("allowLockOfTheNight")&&pr.lock&&typeof lockFightAndSide==="function"){
      var li=lockFightAndSide(pr.lock);
      if(li&&li.fight&&li.fight.id===f.id&&r.winner===li.side)total+=parseInt(cardScoring.lockWinPts||0)||0;
    }
    return total;
  }
  function previewRunningTotals(){
    var totals={}, running=0;
    (fights||[]).slice().reverse().forEach(function(f){
      var r=getEffectiveFightResult(f.id);
      if(r&&r.winner){
        running+=calcPreviewFightPts(myEntry,f);
        totals[f.id]=running;
      }
    });
    return totals;
  }
  function findFight(detail){
    var text=detail.textContent||"";
    return (fights||[]).find(function(f){return text.indexOf(last(f.f1))>-1&&text.indexOf(last(f.f2))>-1;})||null;
  }
  function paintPreviewPickStatuses(){
    if(!myEntry)return;
    var totals=previewRunningTotals();
    document.querySelectorAll("#mineContent .my-pick-detail").forEach(function(detail){
      if(detail.classList.contains("fastest-tie-row")||/Fastest Finish Tiebreaker/i.test(detail.textContent||""))return;
      var summary=detail.querySelector("summary");
      if(!summary)return;
      var f=findFight(detail);
      if(!f)return;
      var r=getEffectiveFightResult(f.id), resolved=!!(r&&r.winner), side=myEntry.picks&&myEntry.picks[f.id], pickName=side===1?f.f1:f.f2, won=resolved&&side===r.winner;
      var statusClass=resolved?(won?"hit":"miss"):"";
      var runningHtml=resolved?'<span class="my-running-pill '+((totals[f.id]||0)===0?"zero":"")+'">'+(totals[f.id]||0)+' PTS</span>':"";
      summary.classList.add("my-result-summary");
      summary.innerHTML='<span class="my-pick-result-head"><span class="my-pick-match">'+esc(fightName(f))+'</span><span class="my-pick-choice '+statusClass+'">'+(resolved&&won?"✓ ":"")+esc(last(pickName||"Not Picked"))+'</span></span>'+runningHtml+'<span class="my-pick-chevron">▼</span>';
    });
  }
  function schedulePreviewPickStatuses(){
    if(queued)return;
    queued=true;
    requestAnimationFrame(function(){queued=false;paintPreviewPickStatuses();});
  }
  ["renderMySummary","showTab"].forEach(function(name){
    var original=window[name];
    if(typeof original!=="function")return;
    window[name]=function(){
      var out=original.apply(this,arguments);
      schedulePreviewPickStatuses();
      return out;
    };
  });
  schedulePreviewPickStatuses();
  setTimeout(paintPreviewPickStatuses,600);
})();
