  document.head.appendChild(style);
  function installPhonePoolAccordion(){
    if(!phoneLike||!document.body.classList.contains("phone-design-preview"))return;
    var card=document.querySelector("#view-picks .current-pool-strip");
    if(!card)return;
    if(card.querySelector(".phone-pool-native"))return;
    var poolName=(card.querySelector("#currentPicksPoolName")&&card.querySelector("#currentPicksPoolName").textContent||"Pool Details").trim();
    var poolCode=(card.querySelector("#currentPicksPoolCode")&&card.querySelector("#currentPicksPoolCode").textContent||"").trim();
    var details=document.createElement("details");
    details.className="phone-pool-native";
    var summary=document.createElement("summary");
    summary.className="phone-pool-native-summary";
    summary.innerHTML='<span class="phone-pool-native-main"><span class="phone-pool-native-kicker">Pool Details</span><span class="phone-pool-native-title">'+escapeHtml(poolName)+'</span><span class="phone-pool-native-sub">'+(poolCode?'Code: '+escapeHtml(poolCode):'Tap to view invite codes')+'</span></span><span class="phone-pool-native-state" aria-hidden="true"></span>';
    details.appendChild(summary);
    while(card.firstChild)details.appendChild(card.firstChild);
    card.classList.add("phone-pool-native-card");
    card.appendChild(details);
  }
  function installPhoneFightAccordions(){
    if(!phoneLike||!document.body.classList.contains("phone-design-preview"))return;
    if(!collapsePhonePickCards)return;
    var cards=[].slice.call(document.querySelectorAll("#view-picks .fight-card"));
    cards.forEach(function(card,index){
      if(card.classList.contains("phone-fight-collapsible"))return;
      var names=[].slice.call(card.querySelectorAll(".fighter-name")).map(function(el){return (el.textContent||"").trim();}).filter(Boolean);
      var weight=(card.querySelector(".fight-weight")&&card.querySelector(".fight-weight").textContent||"Fight").trim();
      var badges=[].slice.call(card.querySelectorAll(".badge,.badge-title-text")).map(function(el){return (el.textContent||"").trim();}).filter(Boolean).join(" · ");
      var title=(names[0]||"Fighter 1")+" vs "+(names[1]||"Fighter 2");
      var btn=document.createElement("button");
      btn.type="button";
      btn.className="phone-fight-toggle";
      btn.setAttribute("aria-expanded","false");
      btn.innerHTML='<span class="phone-fight-toggle-main"><span class="phone-fight-toggle-kicker">'+escapeHtml(weight)+(badges?" · "+escapeHtml(badges):"")+'</span><span class="phone-fight-toggle-title">'+escapeHtml(title)+'</span><span class="phone-fight-toggle-sub">Tap to make winner, method, round, and O/U picks</span></span><span class="phone-fight-toggle-state">Open</span>';
      btn.addEventListener("click",function(){
        var open=!card.classList.contains("phone-fight-open");
        card.classList.toggle("phone-fight-open",open);
        btn.setAttribute("aria-expanded",open?"true":"false");
        var state=btn.querySelector(".phone-fight-toggle-state");
        if(state)state.textContent=open?"Close":"Open";
      });
      card.classList.add("phone-fight-collapsible");
      card.insertBefore(btn,card.firstChild);
	    });
  }
  function installPhoneSpecialAccordions(){
    if(!phoneLike||!document.body.classList.contains("phone-design-preview"))return;
    if(!collapsePhonePickCards)return;
    var sections=[
      {card:document.querySelector("#view-picks .lock-card"),kind:"lock",kicker:"Bonus Pick",title:"Lock of the Night",sub:"Choose your +2 fighter lock"},
      {card:document.querySelector("#view-picks #fastestFinishTieCard"),kind:"fastest",kicker:"Tiebreaker",title:"Fastest Finish",sub:"Pick round and elapsed time"}
    ];
    sections.forEach(function(item){
      var card=item.card;
      if(!card||card.classList.contains("phone-special-collapsible"))return;
      var btn=document.createElement("button");
      btn.type="button";
      btn.className="phone-special-toggle";
      btn.setAttribute("aria-expanded","false");
      btn.innerHTML='<span class="phone-special-toggle-main"><span class="phone-special-toggle-kicker">'+escapeHtml(item.kicker)+'</span><span class="phone-special-toggle-title">'+escapeHtml(item.title)+'</span><span class="phone-special-toggle-sub">'+escapeHtml(item.sub)+'</span></span><span class="phone-special-toggle-state">Open</span>';
      btn.addEventListener("click",function(){
        var open=!card.classList.contains("phone-special-open");
        card.classList.toggle("phone-special-open",open);
        btn.setAttribute("aria-expanded",open?"true":"false");
        var state=btn.querySelector(".phone-special-toggle-state");
        if(state)state.textContent=open?"Close":"Open";
      });
      card.classList.add("phone-special-collapsible","phone-special-"+item.kind);
      card.insertBefore(btn,card.firstChild);
    });
  }
