  function phonePreviewFastestTie(){
    var tie=null;
    try{
      if(typeof embeddedUfc328FastestFinish==="function")tie=embeddedUfc328FastestFinish(0);
    }catch(e){}
    tie=tie||{round:"r1",mark:"1:57"};
    return {round:String(tie.round||"r1").toLowerCase(),mark:String(tie.mark||"1:57")};
  }
  function applyPhonePreviewFastestFinish(){
    if(!phoneLike||!document.body.classList.contains("phone-design-preview"))return null;
    var fastest=document.querySelector("#view-picks #fastestFinishTieCard");
    if(!fastest)return null;
    var tie=phonePreviewFastestTie();
    window.__fastestFinishTie={round:tie.round,mark:tie.mark};
    fastest.querySelectorAll(".fastest-round-btn").forEach(function(btn){
      var active=String(btn.getAttribute("data-round")||"").toLowerCase()===tie.round;
      btn.classList.toggle("active",active);
      var radio=btn.querySelector("input[type='radio']");
      if(radio)radio.checked=active;
    });
    var input=fastest.querySelector("#fastestFinishMark");
    if(input)input.value=tie.mark;
    var summary=fastest.querySelector("#fastestFinishSummary,.fastest-tie-summary");
    if(summary)summary.textContent="Fastest Finish Tiebreaker: "+tie.round.toUpperCase()+" at "+tie.mark+" elapsed";
    return tie;
  }
  function updatePhoneFastestSummary(){
    var fastest=document.querySelector("#view-picks #fastestFinishTieCard");
    if(!fastest)return;
    var previewTie=applyPhonePreviewFastestFinish();
    if(previewTie)return;
    var active=fastest.querySelector(".fastest-round-btn.active");
    var input=fastest.querySelector("#fastestFinishMark");
    var summary=fastest.querySelector("#fastestFinishSummary,.fastest-tie-summary");
    if(summary)summary.textContent="Fastest Finish Tiebreaker: "+((active&&active.textContent.trim())||"R1")+" at "+((input&&input.value)||"0:00")+" elapsed";
  }
  function installPhonePreviewDragScroll(){
    if(!phoneLike||!document.body.classList.contains("phone-design-preview")||document.body.dataset.phoneDragScroll==="1")return;
    document.body.dataset.phoneDragScroll="1";
    var dragging=false,startY=0,startScroll=0,moved=false;
    function isTextField(target){
      return !!(target&&target.closest&&target.closest("input,textarea,select"));
    }
    document.body.addEventListener("pointerdown",function(event){
      if(event.button!==0||isTextField(event.target))return;
      dragging=true;
      moved=false;
      startY=event.clientY;
      startScroll=window.scrollY||document.documentElement.scrollTop||0;
      document.body.classList.add("phone-drag-scrolling");
    },{passive:true});
    document.body.addEventListener("pointermove",function(event){
      if(!dragging)return;
      var delta=startY-event.clientY;
      if(Math.abs(delta)>3)moved=true;
      window.scrollTo(0,startScroll+delta);
    },{passive:true});
    function stopDrag(){
      dragging=false;
      document.body.classList.remove("phone-drag-scrolling");
    }
    document.body.addEventListener("pointerup",stopDrag,{passive:true});
    document.body.addEventListener("pointercancel",stopDrag,{passive:true});
    document.body.addEventListener("click",function(event){
      if(moved){
        event.preventDefault();
        event.stopPropagation();
        moved=false;
      }
    },true);
	  }
